class AudioStartFrameDropLabel(QLabel):
    """Drop target that resolves an audio track path for Start-at-Frame assignment."""
    track_dropped = pyqtSignal(str)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAcceptDrops(True)
        self.setAlignment(Qt.AlignCenter)
        self.setFrameShape(QFrame.StyledPanel)
        self._normal_style = (
            "QLabel { border: 1px dashed #6b7280; background-color: #111827;"
            " color: #d1d5db; padding: 4px 10px; border-radius: 4px; }"
        )
        self._hover_style = (
            "QLabel { border: 1px solid #22c55e; background-color: #052e1a;"
            " color: #dcfce7; padding: 4px 10px; border-radius: 4px; }"
        )
        self.setStyleSheet(self._normal_style)

    def _extract_audio_path_from_mime(self, mime_data):
        if not mime_data:
            return ''

        supported = ('.mp3', '.wav', '.m4a', '.aac', '.flac', '.ogg')
        if mime_data.hasUrls():
            for url in mime_data.urls():
                if not url.isLocalFile():
                    continue
                local_path = os.path.normpath(url.toLocalFile())
                if str(local_path).lower().endswith(supported):
                    return local_path

        if mime_data.hasText():
            raw_text = mime_data.text() or ''
            for token in re.split(r'[\r\n]+', raw_text):
                candidate = token.strip().strip('"')
                if not candidate:
                    continue
                if candidate.startswith('file:///'):
                    local_path = QUrl(candidate).toLocalFile()
                else:
                    local_path = candidate
                local_path = os.path.normpath(local_path)
                if str(local_path).lower().endswith(supported):
                    return local_path

        return ''

    def _extract_audio_path_from_drag_source(self, event):
        src = event.source()
        if not isinstance(src, QListWidget):
            return ''
        item = src.currentItem()
        if not item:
            return ''
        data = item.data(Qt.UserRole)
        if isinstance(data, dict):
            for key in ('track_path', 'path', 'file_path'):
                value = data.get(key)
                if value:
                    return os.path.normpath(str(value))
        if isinstance(data, str) and data:
            return os.path.normpath(data)
        tip = (item.toolTip() or '').strip()
        if tip:
            return os.path.normpath(tip)
        return ''

    def dragEnterEvent(self, event):
        path = self._extract_audio_path_from_mime(event.mimeData())
        if not path:
            path = self._extract_audio_path_from_drag_source(event)
        if path:
            self.setStyleSheet(self._hover_style)
            event.acceptProposedAction()
            return
        event.ignore()

    def dragMoveEvent(self, event):
        path = self._extract_audio_path_from_mime(event.mimeData())
        if not path:
            path = self._extract_audio_path_from_drag_source(event)
        if path:
            event.acceptProposedAction()
            return
        event.ignore()

    def dragLeaveEvent(self, event):
        self.setStyleSheet(self._normal_style)
        super().dragLeaveEvent(event)

    def dropEvent(self, event):
        self.setStyleSheet(self._normal_style)
        path = self._extract_audio_path_from_mime(event.mimeData())
        if not path:
            path = self._extract_audio_path_from_drag_source(event)
        if path:
            self.track_dropped.emit(path)
            event.acceptProposedAction()
            return
        event.ignore()


class PreserveTreeItemForegroundDelegate(QStyledItemDelegate):
    """Preserve per-item foreground colors when a tree item is selected."""

    def paint(self, painter, option, index):
        opt = QStyleOptionViewItem(option)
        self.initStyleOption(opt, index)

        if opt.state & QStyle.State_Selected:
            fg_value = index.data(Qt.ForegroundRole)
            if isinstance(fg_value, QBrush):
                opt.palette.setBrush(QPalette.HighlightedText, fg_value)
            elif isinstance(fg_value, QColor):
                opt.palette.setColor(QPalette.HighlightedText, fg_value)

        super().paint(painter, opt, index)


class QTextEditLogger(logging.Handler, QObject):
    """Logging handler that writes to a QTextEdit widget (thread-safe)"""
    log_signal = pyqtSignal(str)
    
    def __init__(self, text_edit):
        logging.Handler.__init__(self)
        QObject.__init__(self)
        self.text_edit = text_edit
        self._closed = False
        # Prevent Python's logging.shutdown() from flushing when Qt objects are deleted
        self.flushOnClose = False
        # Connect signal to slot with auto-scroll
        self.log_signal.connect(self._append_and_scroll)
    
    def _append_and_scroll(self, msg):
        """Append text and scroll to bottom"""
        try:
            self.text_edit.append(msg)
            # Auto-scroll to bottom
            scrollbar = self.text_edit.verticalScrollBar()
            scrollbar.setValue(scrollbar.maximum())
        except RuntimeError:
            self._closed = True
    
    def emit(self, record):
        """Emit log record - safely handle if widget is deleted"""
        if self._closed:
            return
        try:
            msg = self.format(record)
            
            # Color-code download mode indicators
            if '(authenticated)' in msg.lower() or 'authenticated session' in msg.lower():
                # Red for authenticated mode
                msg = msg.replace('(authenticated)', '<span style="color: #ff3333; font-weight: bold;">(AUTHENTICATED)</span>')
                msg = msg.replace('(Authenticated)', '<span style="color: #ff3333; font-weight: bold;">(AUTHENTICATED)</span>')
                # Handle "Using authenticated session" phrase
                if 'Using authenticated session' in msg:
                    msg = msg.replace('Using authenticated session', '<span style="color: #ff3333; font-weight: bold;">Using AUTHENTICATED session</span>')
            elif '(anonymous)' in msg.lower() or 'anonymous download' in msg.lower():
                # Blue for anonymous mode
                msg = msg.replace('(anonymous)', '<span style="color: #0066ff; font-weight: bold;">(ANONYMOUS)</span>')
                msg = msg.replace('(Anonymous)', '<span style="color: #0066ff; font-weight: bold;">(ANONYMOUS)</span>')
                # Handle "Attempting anonymous download" phrase
                if 'Attempting anonymous download' in msg:
                    msg = msg.replace('Attempting anonymous download', '<span style="color: #0066ff; font-weight: bold;">Attempting ANONYMOUS download</span>')
            
            # Check for C: drive paths in DOWNLOADS/FILES only (not working directory)
            # Ignore references to the script's working directory (C:\A7\qs\...)
            if ('C:' in msg or 'c:' in msg) and 'qs.python.instagram-downloader' not in msg:
                # Check if it's actually a file/download path (contains common patterns)
                if any(pattern in msg.lower() for pattern in ['download', 'path', 'directory', 'file', '.jpg', '.mp4', '.png', 'sassenheimer\\D', 'Instagram\\']):
                    # Add red HTML formatting for C: drive warnings
                    msg = f'<span style="color: #ff3333; font-weight: bold;">⚠️ C: DRIVE FILE PATH DETECTED</span> {msg}'
            
            # Emit signal instead of directly calling append()
            # This ensures thread-safe operation
            self.log_signal.emit(msg)
        except RuntimeError:
            # Qt object has been deleted
            self._closed = True
    
    def close(self):
        """Close handler - safely disconnect without accessing Qt objects"""
        if not self._closed:
            self._closed = True
            try:
                # Disconnect signal if Qt objects still exist
                self.log_signal.disconnect()
            except (RuntimeError, TypeError):
                # Qt object already deleted or signal not connected
                pass
        # Call parent close but don't flush (flushOnClose = False)
        super().close()


class LoginThread(QThread):
    """Background thread for login operation"""
    finished = pyqtSignal(bool, str, str)  # success, message, ig_username
    
    def __init__(self, manager, username, password, session_file):
        super().__init__()
        self.manager = manager
        self.username = username
        self.password = password
        self.session_file = session_file
    
    def run(self):
        try:
            result = self.manager.login_detailed(self.username, self.password, self.session_file)
            self.finished.emit(bool(result.get('success')), str(result.get('message') or ''), str(result.get('ig_username') or ''))
        except Exception as e:
            self.finished.emit(False, f"Error: {str(e)}", "")


class SoccrTechniquesTestThread(QThread):
    """Background thread for testing soccr_api_client techniques endpoint."""
    test_completed = pyqtSignal(bool, str, float)

    def __init__(self, configuration_factory):
        super().__init__()
        self.configuration_factory = configuration_factory

    def run(self):
        start_time = time.perf_counter()
        try:
            configuration = self.configuration_factory()
            if configuration is None:
                elapsed_s = time.perf_counter() - start_time
                self.test_completed.emit(False, "Soccr API client is OFF. Select Dev or Prod first.", elapsed_s)
                return

            from soccr_api_client import ApiClient
            from soccr_api_client.api.techniques_api import TechniquesApi

            with ApiClient(configuration) as api_client:
                api = TechniquesApi(api_client)
                result = api.get_techniques_test()

            elapsed_s = time.perf_counter() - start_time
            self.test_completed.emit(True, str(result), elapsed_s)
        except Exception as e:
            elapsed_s = time.perf_counter() - start_time
            self.test_completed.emit(False, str(e), elapsed_s)


class LoadSavedThread(QThread):
    """Background thread for loading saved posts"""
    post_loaded = pyqtSignal(dict)  # individual post
    duplicate_post_loaded = pyqtSignal(dict)  # duplicate post to show in green
    finished = pyqtSignal(int)  # total count
    error = pyqtSignal(str)
    duplicate_found = pyqtSignal(str)  # shortcode of duplicate post
    progress = pyqtSignal(int, int, int, int, int, int)  # processed_count, discovered_count, new_count, existing_db_count, skipped_ui_count, batch_size
    
    def __init__(self, manager, content_db, stop_at_first_duplicate, existing_shortcodes=None, batch_size=80):
        super().__init__()
        self.manager = manager
        self.content_db = content_db
        self.stop_at_first_duplicate = stop_at_first_duplicate
        self.existing_shortcodes = existing_shortcodes or set()
        self.batch_size = max(10, int(batch_size or 80))
        self._stop_requested = False
    
    def run(self):
        try:
            new_count = 0  # Posts that don't exist in database
            existing_count = 0  # Posts that already exist in database
            skipped_ui = 0  # Posts already loaded in UI
            total_fetched = 0  # Total posts fetched from Instagram
            processed_count = 0  # Rows already handled (saved/duplicate/skipped)
            batch_size = self.batch_size
            pending_posts = []

            def flush_batch(posts_batch):
                nonlocal new_count, existing_count, processed_count
                if not posts_batch:
                    return

                if not self.content_db:
                    for batched_post in posts_batch:
                        new_count += 1
                        processed_count += 1
                        self.progress.emit(
                            processed_count,
                            total_fetched,
                            new_count,
                            existing_count,
                            skipped_ui,
                            batch_size
                        )
                        self.post_loaded.emit(batched_post)
                    return

                batch_stats = self.content_db.save_posts_batch(posts_batch)
                saved_shortcodes = set(batch_stats.get('saved_shortcodes', []))
                duplicate_shortcodes = set(batch_stats.get('duplicate_shortcodes', []))
                row_numbers = batch_stats.get('row_numbers', {})

                for batched_post in posts_batch:
                    shortcode_value = batched_post.get('shortcode')
                    if shortcode_value in saved_shortcodes:
                        batched_post['_skip_db_save'] = True
                        if shortcode_value in row_numbers:
                            batched_post['row_number'] = row_numbers.get(shortcode_value)
                        new_count += 1
                        processed_count += 1
                        self.progress.emit(
                            processed_count,
                            total_fetched,
                            new_count,
                            existing_count,
                            skipped_ui,
                            batch_size
                        )
                        self.post_loaded.emit(batched_post)
                    elif shortcode_value in duplicate_shortcodes:
                        existing_count += 1
                        processed_count += 1
                        self.progress.emit(
                            processed_count,
                            total_fetched,
                            new_count,
                            existing_count,
                            skipped_ui,
                            batch_size
                        )
                        self.duplicate_post_loaded.emit(batched_post)
                    else:
                        processed_count += 1
                        self.progress.emit(
                            processed_count,
                            total_fetched,
                            new_count,
                            existing_count,
                            skipped_ui,
                            batch_size
                        )
                        # Unexpected/failed insert path; do not emit row into UI.
                        logger.debug(f"Skipping unresolved batch insert outcome for {shortcode_value}")

            # Stream discovery and batch inserts in one pass so DB count grows continuously.
            for post in self.manager.get_saved_posts():
                if self._stop_requested:
                    break

                total_fetched += 1
                if total_fetched == 1 or total_fetched % 10 == 0:
                    self.progress.emit(
                        processed_count,
                        total_fetched,
                        new_count,
                        existing_count,
                        skipped_ui,
                        batch_size
                    )

                shortcode = post.get('shortcode')
                
                # Skip if already loaded in UI
                if shortcode in self.existing_shortcodes:
                    skipped_ui += 1
                    processed_count += 1
                    self.progress.emit(
                        processed_count,
                        total_fetched,
                        new_count,
                        existing_count,
                        skipped_ui,
                        batch_size
                    )
                    continue
                
                # Check if exists in database (before saving)
                is_existing = False
                if self.content_db and self.stop_at_first_duplicate:
                    is_existing = self.content_db.is_duplicate(shortcode)
                    
                    # Stop at first duplicate if setting is enabled
                    if self.stop_at_first_duplicate and is_existing:
                        self.duplicate_found.emit(shortcode)
                        break
                
                if is_existing:
                    existing_count += 1
                    # Emit progress update
                    processed_count += 1
                    self.progress.emit(
                        processed_count,
                        total_fetched,
                        new_count,
                        existing_count,
                        skipped_ui,
                        batch_size
                    )
                    # Emit as duplicate to show in green UI and skip downloading
                    self.duplicate_post_loaded.emit(post)
                    logger.debug(f"Duplicate found, showing in green: {shortcode}")
                    continue

                pending_posts.append(post)
                if len(pending_posts) >= batch_size:
                    flush_batch(pending_posts)
                    pending_posts = []

            # Flush final partial batch
            flush_batch(pending_posts)

            # Final progress frame after all discovered rows are processed.
            self.progress.emit(
                processed_count,
                total_fetched,
                new_count,
                existing_count,
                skipped_ui,
                batch_size
            )
            
            logger.info(f"Fetched {total_fetched} saved posts from Instagram:")
            logger.info(f"  - {new_count} new (added to UI + database)")
            logger.info(f"  - {existing_count} already in database (skipped)")
            logger.info(f"  - {skipped_ui} already in UI (skipped)")
            self.finished.emit(new_count)
        except Exception as e:
            self.error.emit(f"Failed to load posts: {str(e)}")
    
    def stop(self):
        """Request the thread to stop"""
        self._stop_requested = True


class LoadPageThread(QThread):
    """Background thread for loading a single page of entries on demand"""
    page_loaded = pyqtSignal(int, list)  # page_num, posts
    error = pyqtSignal(str)
    
    def __init__(self, content_db, page_num, items_per_page, search_filters=None):
        super().__init__()
        self.content_db = content_db
        self.page_num = page_num
        self.items_per_page = items_per_page
        self.search_filters = search_filters or {}
        self._stop_requested = False
    
    def run(self):
        try:
            offset = self.page_num * self.items_per_page
            logger.debug(f"[LoadPageThread] Loading page {self.page_num} (offset={offset}, limit={self.items_per_page})")
            
            # Check if stopped before starting
            if self._stop_requested:
                logger.debug(f"[LoadPageThread] Page {self.page_num} load cancelled before starting")
                return
            
            # Extract sort/filter parameters from search_filters
            sort_by_ui = self.search_filters.get('sort_by', 'Row Number')
            sort_direction = self.search_filters.get('sort_direction', 'DESC')
            filter_ui = self.search_filters.get('filter', 'All (Unfiltered)')
            topic_filter = self.search_filters.get('topic_filter', 'All Topics')
            
            logger.info(f"[LoadPageThread] Page {self.page_num}: sort_by_ui={sort_by_ui}, direction={sort_direction}")
            
            # Map UI dropdown text to database column names
            sort_by_map = {
                'Save Date': 'saved_time',
                'Post Date': 'posted_time',
                'Import Date': 'import_time',
                'Row Number': 'row_number'
            }
            sort_by_db = sort_by_map.get(sort_by_ui, 'row_number')
            
            logger.info(f"[LoadPageThread] Page {self.page_num}: Mapped '{sort_by_ui}' to database field '{sort_by_db}'")
            
            # Map filter dropdown to filter type
            filter_type = None
            if filter_ui == 'Only Ignored (Black) Items':
                filter_type = 'ignored'
            elif filter_ui == 'Only Uncategorized':
                filter_type = 'uncategorized'
            elif filter_ui == 'Only Categorized & Undownloaded':
                filter_type = 'categorized_undownloaded'
            elif filter_ui == 'Only Error Items':
                filter_type = 'error'
            elif filter_ui == 'Specific Topic-Undownloaded':
                filter_type = 'specific_topic_undownloaded'
            
            # Only apply topic criteria for the specific-topic filter mode.
            topic_name = None
            if filter_ui == 'Specific Topic-Undownloaded':
                topic_name = None if topic_filter == 'All Topics' else topic_filter
            
            logger.info(f"[LoadPageThread] Page {self.page_num}: Calling get_all_account_entries with sort_by={sort_by_db}, direction={sort_direction}")
            
            # Get entries for this page with sort/filter
            entries = self.content_db.get_all_account_entries(
                limit=self.items_per_page, 
                offset=offset,
                sort_by=sort_by_db,
                sort_direction=sort_direction,
                filter_type=filter_type,
                topic_filter=topic_name
            )
            
            logger.info(f"[LoadPageThread] Page {self.page_num}: Retrieved {len(entries)} entries from database")
            
            # Check if stopped after database query
            if self._stop_requested:
                logger.debug(f"Page {self.page_num} load cancelled after database query")
                return
            
            # Convert to posts
            posts = []
            for entry in entries:
                if self._stop_requested:
                    logger.debug(f"Page {self.page_num} load cancelled during conversion")
                    return
                post = self.content_db.convert_entry_to_post(entry)
                if post:
                    posts.append(post)
            
            # Only emit if not stopped
            if not self._stop_requested:
                logger.debug(f"Page {self.page_num} loaded: {len(posts)} posts")
                self.page_loaded.emit(self.page_num, posts)
            else:
                logger.debug(f"Page {self.page_num} load cancelled after conversion")
            
        except Exception as e:
            if not self._stop_requested:
                self.error.emit(f"Failed to load page {self.page_num}: {str(e)}")
    
    def stop(self):
        """Request the thread to stop"""
        self._stop_requested = True


class LoadDatabaseThread(QThread):
    """Background thread for getting database count and initializing lazy loading"""
    count_loaded = pyqtSignal(int, dict)  # total count, statistics
    error = pyqtSignal(str)
    
    def __init__(self, content_db):
        super().__init__()
        self.content_db = content_db
        self._stop_requested = False
    
    def run(self):
        try:
            logger.info("LoadDatabaseThread.run() started - getting count")
            # Get total count (fast query - no data loading)
            total = self.content_db.get_content_count()
            logger.info(f"Got total count: {total}")
            
            # Get statistics
            stats = self.content_db.get_statistics()
            logger.info(f"Got statistics: {stats}")
            
            logger.info(f"Database initialized: {total} entries total (lazy loading enabled)")
            self.count_loaded.emit(total, stats)
            logger.info("count_loaded signal emitted")
            
        except Exception as e:
            logger.error(f"LoadDatabaseThread error: {e}", exc_info=True)
            self.error.emit(f"Failed to initialize database: {str(e)}")
    
    def stop(self):
        """Request the thread to stop"""
        self._stop_requested = True


class DownloadThread(QThread):
    """Background thread for downloading posts with pause/resume/cancel support"""
    progress = pyqtSignal(int, int)  # current, total
    finished = pyqtSignal(int, int)  # success, failed
    status = pyqtSignal(str)
    download_complete = pyqtSignal(str, bool, str, str, list, dict)  # shortcode, success, file_path, error_msg, downloaded_files, metadata
    session_expired = pyqtSignal()  # Signal when session expires during download
    failure_classified = pyqtSignal(str, str, str)  # category, shortcode, error_message
    
    def __init__(self, manager, shortcodes, target_dir, process_id=None):
        super().__init__()
        self.manager = manager
        self.shortcodes = shortcodes
        self.target_dir = target_dir
        self.process_id = process_id
        
        # Control flags
        self._paused = False
        self._cancelled = False
        self._mutex = QMutex()
        
    def pause(self):
        """Pause the download"""
        logger.info(f"DownloadThread.pause() called for process {self.process_id}")
        self._mutex.lock()
        self._paused = True
        self._mutex.unlock()
        logger.info(f"DownloadThread paused flag set to True for process {self.process_id}")
        self.status.emit("Paused")
        
    def resume(self):
        """Resume the download"""
        logger.info(f"DownloadThread.resume() called for process {self.process_id}")
        self._mutex.lock()
        self._paused = False
        self._mutex.unlock()
        logger.info(f"DownloadThread paused flag set to False for process {self.process_id}")
        
    def cancel(self):
        """Cancel the download"""
        logger.info(f"DownloadThread.cancel() called for process {self.process_id}")
        self._mutex.lock()
        self._cancelled = True
        self._paused = False
        self._mutex.unlock()
        logger.info(f"DownloadThread cancelled flag set to True for process {self.process_id}")
        self.status.emit("Cancelled")
    
    def is_paused(self):
        """Check if paused"""
        self._mutex.lock()
        result = self._paused
        self._mutex.unlock()
        return result
    
    def is_cancelled(self):
        """Check if cancelled"""
        self._mutex.lock()
        result = self._cancelled
        self._mutex.unlock()
        return result
    
    def run(self):
        import os
        import time
        logger.info(f"DownloadThread.run() started for process {self.process_id}, {len(self.shortcodes)} shortcode(s)")
        success = 0
        failed = 0
        total = len(self.shortcodes)
        
        for i, shortcode in enumerate(self.shortcodes, 1):
            # Check for cancellation
            if self.is_cancelled():
                logger.info(f"DownloadThread detected cancellation at start of loop iteration {i}")
                self.status.emit("Cancelled")
                break
            
            # Wait while paused
            if self.is_paused():
                logger.info(f"DownloadThread detected pause at iteration {i}, entering pause loop")
            while self.is_paused() and not self.is_cancelled():
                time.sleep(0.1)
            
            # Check again after pause
            if self.is_cancelled():
                logger.info(f"DownloadThread detected cancellation after pause at iteration {i}")
                self.status.emit("Cancelled")
                break
            
            # Add delay between downloads to avoid Instagram rate limiting (except for first download)
            if i > 1:
                delay = 10  # 10 second delay between downloads to avoid detection
                logger.info(f"Waiting {delay} seconds before next download (avoiding Instagram detection)...")
                time.sleep(delay)
            elif i == 1:
                # Even before first download in a batch, add a small delay if not first ever download
                delay = 3
                logger.info(f"Initial {delay} second delay before starting batch download...")
                time.sleep(delay)
            
            self.status.emit(f"Downloading {shortcode}...")
            self.progress.emit(i, total)
            
            try:
                result, metadata = self.manager.download_post(shortcode, self.target_dir)
                
                if result:
                    success += 1
                    # Emit success with metadata (caption, tags, files, owner, typename)
                    self.download_complete.emit(
                        shortcode, True, str(self.target_dir), "", 
                        metadata.get('files', []), metadata
                    )
                else:
                    failed += 1
                    self.download_complete.emit(shortcode, False, "", "Download failed", [], {})
            except Exception as e:
                failed += 1
                error_msg = str(e)

                try:
                    category = self.manager.classify_failure_category(e)
                except Exception:
                    category = 'null_metadata_shape'
                self.failure_classified.emit(category, shortcode, error_msg)
                
                # Check if session expired or rate limited
                if "BadResponseException" in str(type(e).__name__) or "Fetching Post metadata failed" in error_msg:
                    self.session_expired.emit()
                
                # Check if rate limited (feedback_required)
                if "feedback_required" in error_msg.lower():
                    logger.warning(f"Instagram rate limit detected for {shortcode}. Try again in a few minutes or reduce download speed.")
                
                # Emit the actual exception message
                self.download_complete.emit(shortcode, False, "", error_msg, [], {})

            # Emit detailed action report after each processed item.
            completed = success + failed
            percent = int((completed * 100) / total) if total else 100
            if failed > 0:
                self.status.emit(f"{completed} / {total} ({percent}%, {failed} failures)")
            else:
                self.status.emit(f"{completed} / {total} ({percent}%)")
        
        self.finished.emit(success, failed)


class ProcessManager(QObject):
    """Manages background processes with pause/resume/cancel support"""
    process_added = pyqtSignal(str, str, str)  # process_id, process_type, description
    process_updated = pyqtSignal(str, str, int, int)  # process_id, status, current, total
    process_removed = pyqtSignal(str)  # process_id
    
    def __init__(self):
        super().__init__()
        self.processes = {}  # {process_id: {type, description, status, thread, current, total}}
        self.next_id = 1
        
    def add_process(self, process_type, description, thread=None):
        """Add a new process to track
        
        Args:
            process_type: Type of process ('batch_download', 'single_download', 'thumbnail_bulk')
            description: Human-readable description
            thread: Optional thread object (DownloadThread, etc.)
            
        Returns:
            process_id: Unique identifier for this process
        """
        process_id = f"proc_{self.next_id}"
        self.next_id += 1
        
        self.processes[process_id] = {
            'type': process_type,
            'description': description,
            'status': 'running',
            'thread': thread,
            'current': 0,
            'total': 0,
            'start_time': QTimer()  # Track how long it's been running
        }
        
        self.process_added.emit(process_id, process_type, description)
        logger.info(f"Process added: {process_id} - {description}")
        return process_id
    
    def update_process(self, process_id, status=None, current=None, total=None):
        """Update process status and progress"""
        if process_id not in self.processes:
            return
        
        process = self.processes[process_id]
        if status is not None:
            process['status'] = status
        if current is not None:
            process['current'] = current
        if total is not None:
            process['total'] = total
        
        self.process_updated.emit(
            process_id,
            process['status'],
            process['current'],
            process['total']
        )
    
    def remove_process(self, process_id):
        """Remove a completed/cancelled process"""
        if process_id in self.processes:
            del self.processes[process_id]
            self.process_removed.emit(process_id)
            logger.info(f"Process removed: {process_id}")
    
    def get_process(self, process_id):
        """Get process info"""
        return self.processes.get(process_id)
    
    def get_all_processes(self):
        """Get all processes"""
        return dict(self.processes)
    
    def pause_process(self, process_id):
        """Pause a process"""
        logger.info(f"ProcessManager.pause_process() called for {process_id}")
        process = self.processes.get(process_id)
        if not process:
            logger.warning(f"Process {process_id} not found in processes dict")
            return
        logger.info(f"Process found: type={process['type']}, status={process['status']}, has_thread={process['thread'] is not None}")
        if process and process['thread']:
            if hasattr(process['thread'], 'pause'):
                logger.info(f"Calling thread.pause() for {process_id}")
                process['thread'].pause()
                process['status'] = 'paused'
                self.process_updated.emit(process_id, 'paused', process['current'], process['total'])
                logger.info(f"Process paused: {process_id}")
            else:
                logger.warning(f"Thread for {process_id} does not have pause() method")
        else:
            logger.warning(f"No thread reference for process {process_id}")
    
    def resume_process(self, process_id):
        """Resume a paused process"""
        logger.info(f"ProcessManager.resume_process() called for {process_id}")
        process = self.processes.get(process_id)
        if not process:
            logger.warning(f"Process {process_id} not found in processes dict")
            return
        logger.info(f"Process found: type={process['type']}, status={process['status']}, has_thread={process['thread'] is not None}")
        if process and process['thread']:
            if hasattr(process['thread'], 'resume'):
                logger.info(f"Calling thread.resume() for {process_id}")
                process['thread'].resume()
                process['status'] = 'running'
                self.process_updated.emit(process_id, 'running', process['current'], process['total'])
                logger.info(f"Process resumed: {process_id}")
            else:
                logger.warning(f"Thread for {process_id} does not have resume() method")
        else:
            logger.warning(f"No thread reference for process {process_id}")
    
    def cancel_process(self, process_id):
        """Cancel a process"""
        logger.info(f"ProcessManager.cancel_process() called for {process_id}")
        process = self.processes.get(process_id)
        if not process:
            logger.warning(f"Process {process_id} not found in processes dict")
            return
        logger.info(f"Process found: type={process['type']}, status={process['status']}, has_thread={process['thread'] is not None}")
        if process and process['thread']:
            if hasattr(process['thread'], 'cancel'):
                logger.info(f"Calling thread.cancel() for {process_id}")
                process['thread'].cancel()
                process['status'] = 'cancelled'
                self.process_updated.emit(process_id, 'cancelled', process['current'], process['total'])
                logger.info(f"Process cancelled: {process_id}")
            else:
                logger.warning(f"Thread for {process_id} does not have cancel() method")
        else:
            logger.warning(f"No thread reference for process {process_id}")
    
    def restart_process(self, process_id):
        """Restart a cancelled/failed process (not implemented yet)"""
        logger.warning(f"Restart not yet implemented for {process_id}")
        # TODO: Implement restart logic


class VideoCropPreview(QLabel):
    """Drag/drop video preview with mouse-drawn crop rectangle."""
    file_dropped = pyqtSignal(str)
    crop_changed = pyqtSignal(int, int, int, int)  # x, y, w, h in source pixels

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAcceptDrops(True)
        self.setAlignment(Qt.AlignCenter)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        self.setMinimumSize(640, 360)
        self.setStyleSheet("QLabel { border: 2px dashed #888; background-color: #1f1f1f; color: #ddd; }")
        self.setText("")

        self._source_frame = None
        self._source_w = 0
        self._source_h = 0
        self._base_pixmap = None
        self._scaled_pixmap = None
        self._image_rect = QRect()

        self._dragging = False
        self._start_pt = QPoint()
        self._end_pt = QPoint()
        self._crop_rect_display = QRect()

    def sizeHint(self):
        return QSize(640, 360)

    def minimumSizeHint(self):
        return QSize(640, 360)

    def _is_supported_video(self, file_path):
        return file_path.lower().endswith((".mp4", ".mov", ".m4v", ".avi", ".mkv", ".webm"))

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            for url in event.mimeData().urls():
                if url.isLocalFile() and self._is_supported_video(url.toLocalFile()):
                    event.acceptProposedAction()
                    return
        event.ignore()

    def dropEvent(self, event):
        if not event.mimeData().hasUrls():
            event.ignore()
            return
        for url in event.mimeData().urls():
            if url.isLocalFile():
                file_path = url.toLocalFile()
                if self._is_supported_video(file_path):
                    self.file_dropped.emit(file_path)
                    event.acceptProposedAction()
                    return
        event.ignore()

    def set_video_frame(self, frame_bgr, keep_crop=True):
        """Set the preview image from an OpenCV BGR frame."""
        import cv2

        if frame_bgr is None:
            self._source_frame = None
            self._source_w = 0
            self._source_h = 0
            self._base_pixmap = None
            self._scaled_pixmap = None
            self._image_rect = QRect()
            self._crop_rect_display = QRect()
            self.setPixmap(QPixmap())
            self.setText("")
            return

        self._source_h, self._source_w = frame_bgr.shape[:2]
        self._source_frame = frame_bgr
        frame_rgb = cv2.cvtColor(frame_bgr, cv2.COLOR_BGR2RGB)
        qimg = QImage(frame_rgb.data, self._source_w, self._source_h, frame_rgb.strides[0], QImage.Format_RGB888)
        self._base_pixmap = QPixmap.fromImage(qimg)
        if not keep_crop:
            self._crop_rect_display = QRect()
        self._update_scaled_pixmap()

    def clear_crop_selection(self):
        """Clear the current crop rectangle overlay from the preview."""
        self._crop_rect_display = QRect()
        self._update_scaled_pixmap()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._update_scaled_pixmap()

    def _update_scaled_pixmap(self):
        if not self._base_pixmap:
            return

        previous_image_rect = QRect(self._image_rect)
        previous_crop_rect = QRect(self._crop_rect_display)

        scaled = self._base_pixmap.scaled(self.size(), Qt.KeepAspectRatio, Qt.FastTransformation)
        x = (self.width() - scaled.width()) // 2
        y = (self.height() - scaled.height()) // 2
        self._image_rect = QRect(x, y, scaled.width(), scaled.height())

        # Keep existing crop selection stable when the preview widget is resized.
        if not previous_crop_rect.isNull() and not previous_image_rect.isNull() and not self._image_rect.isNull():
            prev = previous_crop_rect.normalized().intersected(previous_image_rect)
            if not prev.isNull() and previous_image_rect.width() > 0 and previous_image_rect.height() > 0:
                rel_x = (prev.left() - previous_image_rect.left()) / max(1, previous_image_rect.width())
                rel_y = (prev.top() - previous_image_rect.top()) / max(1, previous_image_rect.height())
                rel_w = prev.width() / max(1, previous_image_rect.width())
                rel_h = prev.height() / max(1, previous_image_rect.height())

                new_x = int(round(self._image_rect.left() + rel_x * self._image_rect.width()))
                new_y = int(round(self._image_rect.top() + rel_y * self._image_rect.height()))
                new_w = int(round(rel_w * self._image_rect.width()))
                new_h = int(round(rel_h * self._image_rect.height()))

                remapped = QRect(new_x, new_y, max(1, new_w), max(1, new_h)).intersected(self._image_rect)
                if not remapped.isNull():
                    self._crop_rect_display = remapped

        self.setPixmap(scaled)
        self.update()

    def paintEvent(self, event):
        """Paint base label content, then draw crop overlay on top for persistent playback guides."""
        super().paintEvent(event)

        if self._crop_rect_display.isNull() or self._image_rect.isNull() or not self._base_pixmap:
            return

        r = self._crop_rect_display.normalized()
        # Keep overlay constrained to the current displayed frame area.
        r = r.intersected(self._image_rect)
        if r.isNull() or r.width() < 1 or r.height() < 1:
            return

        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing, False)

        painter.setBrush(QBrush(QColor(0, 0, 0, 90)))
        painter.setPen(Qt.NoPen)
        frame = self._image_rect
        painter.drawRect(frame.left(), frame.top(), frame.width(), max(0, r.top() - frame.top()))
        painter.drawRect(frame.left(), r.bottom() + 1, frame.width(), max(0, frame.bottom() - r.bottom()))
        painter.drawRect(frame.left(), r.top(), max(0, r.left() - frame.left()), r.height())
        painter.drawRect(r.right() + 1, r.top(), max(0, frame.right() - r.right()), r.height())

        painter.setBrush(Qt.NoBrush)
        painter.setPen(QPen(QColor("#00e5ff"), 2))
        painter.drawRect(r)
        painter.end()

    def _clamp_to_image(self, pt):
        x = max(self._image_rect.left(), min(pt.x(), self._image_rect.right()))
        y = max(self._image_rect.top(), min(pt.y(), self._image_rect.bottom()))
        return QPoint(x, y)

    def mousePressEvent(self, event):
        if not self._base_pixmap or event.button() != Qt.LeftButton:
            return super().mousePressEvent(event)
        if not self._image_rect.contains(event.pos()):
            return super().mousePressEvent(event)

        self._dragging = True
        self._start_pt = self._clamp_to_image(event.pos())
        self._end_pt = self._start_pt
        self._crop_rect_display = QRect(self._start_pt, self._end_pt).normalized()
        self._update_scaled_pixmap()

    def mouseMoveEvent(self, event):
        if not self._dragging:
            return super().mouseMoveEvent(event)
        self._end_pt = self._clamp_to_image(event.pos())
        self._crop_rect_display = QRect(self._start_pt, self._end_pt).normalized()
        self._update_scaled_pixmap()

    def mouseReleaseEvent(self, event):
        if not self._dragging or event.button() != Qt.LeftButton:
            return super().mouseReleaseEvent(event)

        self._dragging = False
        self._end_pt = self._clamp_to_image(event.pos())
        self._crop_rect_display = QRect(self._start_pt, self._end_pt).normalized()
        self._update_scaled_pixmap()

        crop = self.get_crop_rect_source()
        if crop:
            self.crop_changed.emit(*crop)

    def get_crop_rect_source(self):
        """Return crop rect in source pixels as (x, y, w, h), or None."""
        if self._crop_rect_display.isNull() or self._image_rect.isNull():
            return None
        if self._source_w <= 0 or self._source_h <= 0:
            return None

        r = self._crop_rect_display.normalized()
        if r.width() < 4 or r.height() < 4:
            return None

        scale_x = self._source_w / max(1, self._image_rect.width())
        scale_y = self._source_h / max(1, self._image_rect.height())

        x = int((r.left() - self._image_rect.left()) * scale_x)
        y = int((r.top() - self._image_rect.top()) * scale_y)
        w = int(r.width() * scale_x)
        h = int(r.height() * scale_y)

        x = max(0, min(x, self._source_w - 2))
        y = max(0, min(y, self._source_h - 2))
        w = max(2, min(w, self._source_w - x))
        h = max(2, min(h, self._source_h - y))

        if w % 2 != 0:
            w -= 1
        if h % 2 != 0:
            h -= 1
        w = max(2, w)
        h = max(2, h)

        return x, y, w, h

    def select_full_crop(self, emit_signal=True):
        """Select the entire visible source frame as the crop rectangle."""
        if not self._base_pixmap or self._image_rect.isNull():
            return False

        self._crop_rect_display = QRect(self._image_rect)
        self._update_scaled_pixmap()

        crop = self.get_crop_rect_source()
        if emit_signal and crop:
            self.crop_changed.emit(*crop)
        return bool(crop)


class VideoTrimRangeSlider(QWidget):
    """Horizontal range slider with draggable start/end trim handles."""
    range_changed = pyqtSignal(int, int)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._minimum = 0
        self._maximum = 100
        self._start = 0
        self._end = 100
        self._dragging_handle = None
        self.setMinimumHeight(36)
        self.setMouseTracking(True)
        self.setCursor(Qt.PointingHandCursor)

    def setRange(self, minimum, maximum):
        minimum = int(minimum)
        maximum = max(minimum, int(maximum))
        self._minimum = minimum
        self._maximum = maximum
        self._start = max(self._minimum, min(self._start, self._maximum))
        self._end = max(self._start, min(self._end, self._maximum))
        self.update()

    def setValues(self, start, end):
        start = int(start)
        end = int(end)
        if start > end:
            start, end = end, start
        self._start = max(self._minimum, min(start, self._maximum))
        self._end = max(self._start, min(end, self._maximum))
        self.update()
        self.range_changed.emit(self._start, self._end)

    def startValue(self):
        return self._start

    def endValue(self):
        return self._end

    def _usable_rect(self):
        return QRect(18, self.height() // 2 - 6, max(1, self.width() - 36), 12)

    def _value_to_x(self, value):
        usable = self._usable_rect()
        if self._maximum <= self._minimum:
            return usable.left()
        ratio = (value - self._minimum) / float(self._maximum - self._minimum)
        return int(usable.left() + ratio * usable.width())

    def _x_to_value(self, x):
        usable = self._usable_rect()
        if usable.width() <= 0 or self._maximum <= self._minimum:
            return self._minimum
        ratio = (x - usable.left()) / float(usable.width())
        ratio = max(0.0, min(1.0, ratio))
        return int(round(self._minimum + ratio * (self._maximum - self._minimum)))

    def _handle_rect(self, value):
        x = self._value_to_x(value)
        return QRect(x - 6, self.height() // 2 - 11, 12, 22)

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)

        usable = self._usable_rect()
        center_y = usable.center().y()

        painter.setPen(Qt.NoPen)
        painter.setBrush(QColor("#3a3a3a"))
        painter.drawRoundedRect(usable, 5, 5)

        start_x = self._value_to_x(self._start)
        end_x = self._value_to_x(self._end)
        selected = QRect(start_x, usable.top(), max(1, end_x - start_x), usable.height())
        painter.setBrush(QColor("#00c2ff"))
        painter.drawRoundedRect(selected, 5, 5)

        for handle_value, handle_color in ((self._start, QColor("#ffffff")), (self._end, QColor("#ffffff"))):
            rect = self._handle_rect(handle_value)
            painter.setBrush(handle_color)
            painter.setPen(QPen(QColor("#1f1f1f"), 1))
            painter.drawRoundedRect(rect, 3, 3)
            painter.setPen(QPen(QColor("#1f1f1f"), 2))
            painter.drawLine(rect.center().x(), rect.top() + 4, rect.center().x(), rect.bottom() - 4)

        painter.setPen(QPen(QColor("#808080"), 1))
        painter.drawLine(usable.left(), center_y, usable.right(), center_y)

    def _pick_handle(self, pos):
        start_rect = self._handle_rect(self._start)
        end_rect = self._handle_rect(self._end)
        if start_rect.adjusted(-6, -6, 6, 6).contains(pos):
            return "start"
        if end_rect.adjusted(-6, -6, 6, 6).contains(pos):
            return "end"
        start_dist = abs(pos.x() - start_rect.center().x())
        end_dist = abs(pos.x() - end_rect.center().x())
        return "start" if start_dist <= end_dist else "end"

    def mousePressEvent(self, event):
        if event.button() != Qt.LeftButton:
            return super().mousePressEvent(event)
        self._dragging_handle = self._pick_handle(event.pos())
        self._update_from_x(event.pos().x())

    def mouseMoveEvent(self, event):
        if self._dragging_handle is None:
            return super().mouseMoveEvent(event)
        self._update_from_x(event.pos().x())

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.LeftButton:
            self._dragging_handle = None
        return super().mouseReleaseEvent(event)

    def _update_from_x(self, x):
        value = self._x_to_value(x)
        if self._dragging_handle == "start":
            self._start = max(self._minimum, min(value, self._end))
        else:
            self._end = min(self._maximum, max(value, self._start))
        self.update()
        self.range_changed.emit(self._start, self._end)


class TrackPositionSlider(VideoTrimRangeSlider):
    """Range slider that supports resizing and moving a track interval."""
    activated = pyqtSignal()

    def __init__(self, parent=None):
        super().__init__(parent)
        self._dragging_handle = None
        self._dragging_body = False
        self._body_drag_offset = 0
        self.setMinimumHeight(32)
        self.setCursor(Qt.OpenHandCursor)

    def _selected_rect(self):
        usable = self._usable_rect()
        start_x = self._value_to_x(self._start)
        end_x = self._value_to_x(self._end)
        left = min(start_x, end_x)
        right = max(start_x, end_x)
        return QRect(left, usable.top(), max(1, right - left), usable.height())

    def _pick_handle(self, pos):
        start_rect = self._handle_rect(self._start)
        end_rect = self._handle_rect(self._end)
        if start_rect.adjusted(-6, -6, 6, 6).contains(pos):
            return "start"
        if end_rect.adjusted(-6, -6, 6, 6).contains(pos):
            return "end"
        if self._selected_rect().adjusted(-2, -6, 2, 6).contains(pos):
            return "move"
        return super()._pick_handle(pos)

    def mousePressEvent(self, event):
        if event.button() != Qt.LeftButton:
            return super().mousePressEvent(event)
        self.activated.emit()
        self._dragging_handle = self._pick_handle(event.pos())
        if self._dragging_handle == "move":
            self._dragging_body = True
            self._body_drag_offset = event.pos().x() - self._value_to_x(self._start)
            self.setCursor(Qt.ClosedHandCursor)
            return
        self._dragging_body = False
        self._update_from_x(event.pos().x())

    def mouseMoveEvent(self, event):
        if self._dragging_body:
            span = max(0, self._end - self._start)
            if span <= 0:
                return
            new_start = self._x_to_value(event.pos().x() - self._body_drag_offset)
            self._start = max(self._minimum, min(new_start, self._maximum - span))
            self._end = min(self._maximum, self._start + span)
            self.update()
            self.range_changed.emit(self._start, self._end)
            return
        return super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.LeftButton:
            self._dragging_body = False
            self._dragging_handle = None
            self.setCursor(Qt.OpenHandCursor)
        return super().mouseReleaseEvent(event)


class AudioTrackRangeSlider(VideoTrimRangeSlider):
    """Range slider for track placement that supports dragging the full span."""
    activated = pyqtSignal()

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMinimumHeight(34)
        self._move_origin_start = 0
        self._move_origin_end = 0
        self._move_press_value = 0

    def _selected_rect(self):
        usable = self._usable_rect()
        start_x = self._value_to_x(self._start)
        end_x = self._value_to_x(self._end)
        left = min(start_x, end_x)
        right = max(start_x, end_x)
        return QRect(left, usable.top(), max(1, right - left), usable.height())

    def _pick_handle(self, pos):
        start_rect = self._handle_rect(self._start)
        end_rect = self._handle_rect(self._end)
        if start_rect.adjusted(-6, -6, 6, 6).contains(pos):
            return "start"
        if end_rect.adjusted(-6, -6, 6, 6).contains(pos):
            return "end"
        if self._selected_rect().adjusted(-2, -6, 2, 6).contains(pos):
            return "move"
        start_dist = abs(pos.x() - start_rect.center().x())
        end_dist = abs(pos.x() - end_rect.center().x())
        return "start" if start_dist <= end_dist else "end"

    def mousePressEvent(self, event):
        if event.button() != Qt.LeftButton:
            return super().mousePressEvent(event)
        self.activated.emit()
        self._dragging_handle = self._pick_handle(event.pos())
        if self._dragging_handle == "move":
            self._move_origin_start = self._start
            self._move_origin_end = self._end
            self._move_press_value = self._x_to_value(event.pos().x())
        self._update_from_x(event.pos().x())


class AudioTrackTableWidget(QTableWidget):
    """Table widget for track rows with drag/drop file addition support."""
    files_dropped = pyqtSignal(list)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setAcceptDrops(True)
        self.viewport().setAcceptDrops(True)
        self.viewport().installEventFilter(self)
        self.setDefaultDropAction(Qt.CopyAction)
        self.setDropIndicatorShown(True)
        self.setDragDropMode(QAbstractItemView.DropOnly)

    def _extract_supported_paths(self, mime_data):
        if not mime_data or not mime_data.hasUrls():
            return []

        supported = ('.mp3', '.wav', '.m4a', '.aac', '.flac', '.ogg')
        paths = []
        for url in mime_data.urls():
            if not url.isLocalFile():
                continue
            local_path = url.toLocalFile()
            if str(local_path).lower().endswith(supported):
                paths.append(local_path)
        return paths

    def dragEnterEvent(self, event):
        if self._extract_supported_paths(event.mimeData()):
            event.setDropAction(Qt.CopyAction)
            event.accept()
            return
        super().dragEnterEvent(event)

    def dragMoveEvent(self, event):
        if self._extract_supported_paths(event.mimeData()):
            event.setDropAction(Qt.CopyAction)
            event.accept()
            return
        super().dragMoveEvent(event)

    def dropEvent(self, event):
        file_paths = self._extract_supported_paths(event.mimeData())
        if file_paths:
            self.files_dropped.emit(file_paths)
            event.setDropAction(Qt.CopyAction)
            event.accept()
            return
        super().dropEvent(event)

    def eventFilter(self, obj, event):
        if obj is self.viewport() and event.type() in (QEvent.DragEnter, QEvent.DragMove, QEvent.Drop):
            if event.type() == QEvent.Drop:
                file_paths = self._extract_supported_paths(event.mimeData())
                if file_paths:
                    self.files_dropped.emit(file_paths)
                    event.setDropAction(Qt.CopyAction)
                    event.accept()
                    return True
                event.ignore()
                return True

            if self._extract_supported_paths(event.mimeData()):
                event.setDropAction(Qt.CopyAction)
                event.accept()
                return True
            event.ignore()
            return True

        return super().eventFilter(obj, event)


class InstagramDownloaderGUI(QMainWindow):
    """Main application window"""
    
    def __init__(self):
        super().__init__()
        self.account_manager = AccountManager()
        self.instagram_manager = InstagramManager()
        self.content_db = None  # Will be initialized when user selects account
        self.current_username = None
        self.instagram_authenticated = False  # Track if we're logged into Instagram (vs offline mode)
        self.saved_posts = []  # Deprecated - kept for backward compatibility
        self.current_content_entry = None
        
        # === Lazy loading system ===
        self.total_items = 0  # Total count from database
        self.page_cache = {}  # {page_num: [posts]}
        self.cache_max_pages = 5  # Keep up to 5 pages in memory
        self.loading_pages = set()  # Track pages currently being loaded
        self.page_load_threads = {}  # {page_num: LoadPageThread}
        self.posts_added_since_pagination_update = 0  # Track when to update pagination
        
        # Fetch tracking for pagination adjustment
        self.fetch_in_progress = False
        self.fetch_initial_total_items = 0
        self.fetch_initial_page = 0
        
        self.db_load_thread = None  # Thread for loading database entries
        self.soccr_client_test_thread = None  # Thread for Soccr API test calls
        self.queued_shortcodes = set()  # Track shortcodes in download queue
        self.selected_tiles = set()  # Track selected tile shortcodes for batch operations
        self.carousel_indices = {}  # Track current index for carousel posts {shortcode: index}
        self.active_download_threads = []  # Track active download threads
        self.thumbnail_threads = []  # Track active thumbnail download threads
        self.stop_thumbnail_downloads = False  # Flag to stop thumbnail downloads
        self.failed_thumbnail_downloads = set()  # Track shortcodes with failed thumbnail downloads
        self.fetch_thumbnail_candidates = []  # New posts queued for post-fetch thumbnail pass
        self.failure_diagnostics_counts = {
            'null_metadata_shape': 0,
            'auth_session_issue': 0,
            'rate_limit_gating_issue': 0,
            'hard_not_found': 0,
        }
        self.failure_diagnostics_total = 0
        
        # Path settings (loaded from account)
        self.thumbnails_path = None  # Will be set from account
        self.topics_root_path = None  # Will be set from account
        
        # Process manager for tracking background operations
        self.process_manager = ProcessManager()
        
        # View mode settings
        self.current_view_mode = 'tiles'  # Always use tiles (table view disabled)
        self.tiles_per_page = 20
        self.current_page = 0
        self.target_page = 0  # Target page to restore after data loads (from saved settings)
        self.filtered_posts = []  # Posts after filtering for pagination
        self.current_tile_data = {}  # Track currently displayed tiles: {(row, col): (shortcode, status_hash)}
        self.last_displayed_page = -1  # Track which page is currently displayed
        self.last_displayed_columns = 0  # Track column count for layout changes
        
        # Table pagination settings
        self.table_current_page = 0
        self.table_items_per_page = 100
        
        self.tile_size = 'medium'  # 'small', 'medium', 'large', 'xlarge'
        self.theme = 'light'  # 'light' or 'dark'
        self.inline_video = False  # Play videos inline (True) or in popup (False)
        self.tile_video_volume = 30  # Default volume for inline tile videos (0-100)
        self.resize_timer = QTimer()  # Timer for debouncing window resize
        self.resize_timer.setSingleShot(True)
        self.resize_timer.timeout.connect(self.on_resize_complete)
        self._populating_tiles = False  # Flag to prevent concurrent populate_tiles calls
        
        # Qt multimedia availability check - load from settings
        saved_qt_available = self.account_manager.get_setting('qt_multimedia_available', 'auto')
        if saved_qt_available == 'auto':
            self.qt_multimedia_available = None  # Not checked yet
        else:
            self.qt_multimedia_available = saved_qt_available == 'true'
            if not self.qt_multimedia_available:
                logger.info("Qt multimedia previously detected as unavailable - will use alternate player")
        
        # VLC player availability (lazy check)
        self.vlc_available = None  # None=not checked, True/False=result
        self.vlc_instance = None
        
        # Force system player (skip all built-in players)
        self.force_system_player = self.account_manager.get_setting('force_system_player', 'false') == 'true'
        if self.force_system_player:
            logger.info("Force system player enabled - will skip built-in players")
        
        # Sort and filter settings
        self.current_sort_by = 'Row Number'  # Default sort field
        self.current_sort_direction = 'DESC'  # Default sort direction
        self.current_filter = 'All (Unfiltered)'  # Default filter
        self.current_topic_filter = 'All Topics'  # Default topic filter

        # Vid Prep state
        self.vid_prep_source_path = None
        self.vid_prep_crop_rect = None  # (x, y, w, h) in source pixels
        self.vid_prep_cap = None
        self.vid_prep_frame_count = 0
        self.vid_prep_fps = 30.0
        self.vid_prep_duration_s = 0.0
        self.vid_prep_last_output_path = None
        self.vid_prep_source_loop_enabled = False
        self.content_selected_topic = ''
        self.content_selected_topic_id = None
        self.content_current_page = 0
        self.content_tiles_per_page = 20
