    def setup_logging(self):
        """Setup logging to GUI console"""
        # Create handler
        self.gui_handler = QTextEditLogger(self.log_console)
        self.gui_handler.setFormatter(logging.Formatter(
            '%(asctime)s - %(name)s - %(levelname)s - %(message)s',
            datefmt='%H:%M:%S'
        ))
        
        # Add to root logger
        root_logger = logging.getLogger()
        root_logger.addHandler(self.gui_handler)
        root_logger.setLevel(logging.INFO)
        
        # Initialize thumbnail cache
        self.thumbnail_cache = {}  # {shortcode: QPixmap}
        
        # Connect process manager signals
        self.process_manager.process_added.connect(self.on_process_added)
        self.process_manager.process_updated.connect(self.on_process_updated)
        self.process_manager.process_removed.connect(self.on_process_removed)
        self.reset_failure_diagnostics()

    def _normalize_failure_category(self, category: str) -> str:
        """Normalize category names to the four diagnostics buckets."""
        normalized = (category or "").strip().lower().replace('-', '_').replace(' ', '_')
        aliases = {
            '403': 'rate_limit_gating_issue',
            'parse_miss': 'rate_limit_gating_issue',
            'decode_fail': 'rate_limit_gating_issue',
            'timeout': 'rate_limit_gating_issue',
            'thumbnail_fetch_issue': 'rate_limit_gating_issue',
        }
        normalized = aliases.get(normalized, normalized)
        valid = {
            'null_metadata_shape',
            'auth_session_issue',
            'rate_limit_gating_issue',
            'hard_not_found',
        }
        return normalized if normalized in valid else 'null_metadata_shape'

    def _friendly_failure_category(self, category: str) -> str:
        mapping = {
            'null_metadata_shape': 'null metadata shape',
            'auth_session_issue': 'auth/session issue',
            'rate_limit_gating_issue': 'rate-limit/gating issue',
            'hard_not_found': 'hard not-found',
        }
        return mapping.get(category, 'null metadata shape')

    def _refresh_failure_diagnostics_ui(self):
        self.diag_null_metadata_value.setText(str(self.failure_diagnostics_counts['null_metadata_shape']))
        self.diag_auth_session_value.setText(str(self.failure_diagnostics_counts['auth_session_issue']))
        self.diag_rate_limit_value.setText(str(self.failure_diagnostics_counts['rate_limit_gating_issue']))
        self.diag_hard_not_found_value.setText(str(self.failure_diagnostics_counts['hard_not_found']))
        self.diag_total_value.setText(str(self.failure_diagnostics_total))

    def reset_failure_diagnostics(self):
        self.failure_diagnostics_counts = {
            'null_metadata_shape': 0,
            'auth_session_issue': 0,
            'rate_limit_gating_issue': 0,
            'hard_not_found': 0,
        }
        self.failure_diagnostics_total = 0
        if hasattr(self, 'diag_last_event'):
            self.diag_last_event.setText("Last: n/a")
        if hasattr(self, 'diag_total_value'):
            self._refresh_failure_diagnostics_ui()

    @pyqtSlot(str, str, str, str)
    def _record_failure_diagnostic_slot(self, category: str, shortcode: str, source: str, error_message: str):
        category_key = self._normalize_failure_category(category)
        self.failure_diagnostics_counts[category_key] += 1
        self.failure_diagnostics_total += 1
        self._refresh_failure_diagnostics_ui()

        short_display = (shortcode or '?').strip() or '?'
        source_display = (source or 'unknown').strip() or 'unknown'
        self.diag_last_event.setText(
            f"Last: {self._friendly_failure_category(category_key)} | {source_display} | {short_display}"
        )

        logger.info(
            f"[DIAGNOSTICS] {category_key} | source={source_display} | shortcode={short_display} | "
            f"error={error_message[:220] if error_message else ''}"
        )

    @pyqtSlot(str, str, str)
    def on_download_failure_classified(self, category: str, shortcode: str, error_message: str):
        self._record_failure_diagnostic_slot(category, shortcode, 'post_download', error_message)
    
    # ========== PROCESS MANAGEMENT METHODS ==========
    
    def on_process_added(self, process_id, process_type, description):
        """Handle new process added"""
        row = 0  # Insert at top for newest-first ordering
        self.process_table.insertRow(row)
        
        # Checkbox
        checkbox = QCheckBox()
        checkbox_widget = QWidget()
        checkbox_layout = QHBoxLayout(checkbox_widget)
        checkbox_layout.addWidget(checkbox)
        checkbox_layout.setAlignment(Qt.AlignCenter)
        checkbox_layout.setContentsMargins(0, 0, 0, 0)
        self.process_table.setCellWidget(row, 0, checkbox_widget)
        
        # Process description
        self.process_table.setItem(row, 1, QTableWidgetItem(description))
        
        # Status
        status_item = QTableWidgetItem("Running")
        status_item.setForeground(QColor("#28a745"))  # Green
        self.process_table.setItem(row, 2, status_item)
        
        # Progress
        self.process_table.setItem(row, 3, QTableWidgetItem("0 / 0"))
        
        # Action buttons
        actions_widget = QWidget()
        actions_layout = QHBoxLayout(actions_widget)
        actions_layout.setContentsMargins(2, 2, 2, 2)
        actions_layout.setSpacing(2)
        
        pause_btn = QPushButton("⏸")
        pause_btn.setMaximumWidth(30)
        pause_btn.setToolTip("Pause")
        pause_btn.clicked.connect(lambda: self.pause_process_by_id(process_id))
        actions_layout.addWidget(pause_btn)
        
        cancel_btn = QPushButton("⏹")
        cancel_btn.setMaximumWidth(30)
        cancel_btn.setToolTip("Cancel")
        cancel_btn.clicked.connect(lambda: self.cancel_process_by_id(process_id))
        actions_layout.addWidget(cancel_btn)
        
        clear_btn = QPushButton("🗑")
        clear_btn.setMaximumWidth(30)
        clear_btn.setToolTip("Clear")
        clear_btn.clicked.connect(lambda: self.clear_process_by_id(process_id))
        actions_layout.addWidget(clear_btn)
        
        actions_layout.addStretch()
        self.process_table.setCellWidget(row, 4, actions_widget)
        
        # Hidden ID column
        self.process_table.setItem(row, 5, QTableWidgetItem(process_id))
    
    def on_process_updated(self, process_id, status, current, total):
        """Handle process status/progress update"""
        # Find row with this process_id
        for row in range(self.process_table.rowCount()):
            id_item = self.process_table.item(row, 5)
            if id_item and id_item.text() == process_id:
                # Refresh description text if process metadata changed.
                process_info = self.process_manager.get_process(process_id)
                if process_info:
                    desc_item = self.process_table.item(row, 1)
                    if desc_item:
                        desc_item.setText(process_info.get('description', ''))

                # Update status
                status_item = self.process_table.item(row, 2)
                if status_item:
                    known_statuses = {
                        'running',
                        're-downloading',
                        'paused',
                        'cancelled',
                        'completed',
                        're-downloaded',
                        'failed',
                        'space_on_disk',
                        'completed_with_errors',
                    }
                    # Format status text for display
                    if status == 'space_on_disk':
                        status_display = 'SPACE ON DISK'
                    elif status in known_statuses:
                        status_display = status.replace('_', ' ').title()
                    else:
                        # Preserve detailed, user-facing step text verbatim.
                        status_display = str(status)
                    status_item.setText(status_display)
                    # Color code status
                    if status == 'running':
                        status_item.setForeground(QColor("#28a745"))  # Green
                    elif status == 're-downloading':
                        status_item.setForeground(QColor("#17a2b8"))  # Cyan (distinct from regular running)
                    elif status == 'paused':
                        status_item.setForeground(QColor("#ffc107"))  # Yellow
                    elif status == 'cancelled':
                        status_item.setForeground(QColor("#dc3545"))  # Red
                    elif status == 'completed':
                        status_item.setForeground(QColor("#007bff"))  # Blue
                    elif status == 're-downloaded':
                        status_item.setForeground(QColor("#6610f2"))  # Purple (distinct from completed)
                    elif status == 'failed':
                        status_item.setForeground(QColor("#dc3545"))  # Red
                    elif status == 'space_on_disk':
                        status_item.setForeground(QColor("#dc3545"))  # Red
                    elif status == 'completed_with_errors':
                        status_item.setForeground(QColor("#ff8c00"))  # Orange
                    else:
                        # Default custom in-flight steps to active green for readability.
                        status_item.setForeground(QColor("#28a745"))
                
                # Update progress
                progress_item = self.process_table.item(row, 3)
                if progress_item:
                    if total > 0:
                        percentage = int((current / total) * 100)
                        progress_item.setText(f"{current} / {total} ({percentage}%)")
                    else:
                        progress_item.setText(f"{current} / {total}")
                break
    
    def on_process_removed(self, process_id):
        """Handle process removal"""
        # Find and remove row with this process_id
        for row in range(self.process_table.rowCount()):
            id_item = self.process_table.item(row, 5)
            if id_item and id_item.text() == process_id:
                self.process_table.removeRow(row)
                break
    
    def pause_process_by_id(self, process_id):
        """Pause a specific process"""
        logger.info(f"UI: pause_process_by_id() called for {process_id}")
        self.process_manager.pause_process(process_id)
    
    def cancel_process_by_id(self, process_id):
        """Cancel a specific process"""
        logger.info(f"UI: cancel_process_by_id() called for {process_id}")
        self.process_manager.cancel_process(process_id)
    
    def clear_process_by_id(self, process_id):
        """Clear/remove a specific process from the list"""
        self.process_manager.remove_process(process_id)
    
    def get_selected_process_ids(self):
        """Get list of selected process IDs"""
        selected_ids = []
        for row in range(self.process_table.rowCount()):
            checkbox_widget = self.process_table.cellWidget(row, 0)
            if checkbox_widget:
                checkbox = checkbox_widget.findChild(QCheckBox)
                if checkbox and checkbox.isChecked():
                    id_item = self.process_table.item(row, 5)
                    if id_item:
                        selected_ids.append(id_item.text())
        return selected_ids
    
    def select_all_processes(self):
        """Select all processes"""
        for row in range(self.process_table.rowCount()):
            checkbox_widget = self.process_table.cellWidget(row, 0)
            if checkbox_widget:
                checkbox = checkbox_widget.findChild(QCheckBox)
                if checkbox:
                    checkbox.setChecked(True)
    
    def deselect_all_processes(self):
        """Deselect all processes"""
        for row in range(self.process_table.rowCount()):
            checkbox_widget = self.process_table.cellWidget(row, 0)
            if checkbox_widget:
                checkbox = checkbox_widget.findChild(QCheckBox)
                if checkbox:
                    checkbox.setChecked(False)
    
    def pause_selected_processes(self):
        """Pause all selected processes"""
        selected_ids = self.get_selected_process_ids()
        logger.info(f"UI: pause_selected_processes() called for {len(selected_ids)} process(es): {selected_ids}")
        for process_id in selected_ids:
            self.process_manager.pause_process(process_id)
    
    def resume_selected_processes(self):
        """Resume all selected processes"""
        selected_ids = self.get_selected_process_ids()
        logger.info(f"UI: resume_selected_processes() called for {len(selected_ids)} process(es): {selected_ids}")
        for process_id in selected_ids:
            self.process_manager.resume_process(process_id)
    
    def cancel_selected_processes(self):
        """Cancel all selected processes"""
        selected_ids = self.get_selected_process_ids()
        logger.info(f"UI: cancel_selected_processes() called for {len(selected_ids)} process(es): {selected_ids}")
        for process_id in selected_ids:
            self.process_manager.cancel_process(process_id)
    
    def clear_completed_processes(self):
        """Clear all completed/cancelled processes"""
        to_remove = []
        for process_id, process in self.process_manager.get_all_processes().items():
            if process['status'] in ['completed', 're-downloaded', 'cancelled', 'failed']:
                to_remove.append(process_id)
        
        for process_id in to_remove:
            self.process_manager.remove_process(process_id)
    
    # ========== END PROCESS MANAGEMENT METHODS ==========
    
    @staticmethod
    def sanitize_topic_path(topic_path):
        """
        Sanitize and validate a topic path to ensure it's safe.
        Supports both absolute paths (with drive letters) and relative paths.
        
        Args:
            topic_path: Path string from user input or database
        
        Returns:
            Tuple of (sanitized_path, is_absolute) or (None, False) if invalid
        """
        if not topic_path or not topic_path.strip():
            return None, False
        
        # Remove leading/trailing whitespace
        path = topic_path.strip()
        
        # Check if it's an absolute Windows path with drive letter (e.g., C:\, G:\)
        is_absolute = False
        if len(path) >= 2 and path[1] == ':':
            # It's an absolute path with drive letter - keep it
            is_absolute = True
            logger.info(f"Topic path is absolute: {path}")
        
        # Block UNC paths (\\server\share) - these are security risks
        if path.startswith('\\\\') or path.startswith('//'):
            logger.error(f"UNC paths not allowed in topic path: {topic_path}")
            return None, False
        
        # For relative paths, remove leading slashes
        if not is_absolute:
            path = path.lstrip('\\/')
        
        # Replace backslashes with forward slashes for consistency (but keep drive letter colon)
        if is_absolute and len(path) >= 2 and path[1] == ':':
            # Keep drive letter, convert rest
            drive = path[:2]
            rest = path[2:].replace('\\', '/')
            path = drive + rest
        else:
            path = path.replace('\\', '/')
        
        # Check for invalid characters that could cause issues
        invalid_chars = ['<', '>', '"', '|', '?', '*']
        for char in invalid_chars:
            if char in path:
                logger.error(f"Invalid character '{char}' in topic path: {topic_path}")
                return None, False
        
        # Don't allow parent directory references for security
        if '..' in path:
            logger.error(f"Parent directory references (..) not allowed in topic path: {topic_path}")
            return None, False
        
        return path if path else None, is_absolute
    
    def select_account_for_local_access(self, account_dict, load_database=True):
        """
        Select an account for local data access WITHOUT requiring Instagram authentication.
        This allows browsing already-downloaded content offline.
        
        Args:
            account_dict: Account dictionary from account_manager
            load_database: Whether to load database entries after selecting account
        """
        username = account_dict['username']
        logger.info(f"Selecting account '{username}' for local data access (offline mode)")
        
        # Set current account
        self.current_username = username
        self.instagram_authenticated = False  # Offline mode
        
        # Initialize content database manager (does not require Instagram auth)
        self.content_db = ContentDatabaseManager(str(config.DATA_DIR), username)
        logger.info(f"Initialized content database for {username}")
        
        # Update UI to show offline mode
        self.account_status.setText(f"📁 {username} (Local Data Only)")
        self.account_status.setStyleSheet(
            "font-weight: bold; padding: 10px; color: #FF9800;"  # Orange for offline mode
        )
        self.statusBar().showMessage(f"Accessing local data for {username}")
        self.load_accounts()
        
        # Load account's download path
        download_path = account_dict.get('download_path')
        if download_path:
            self.download_path_input.setText(download_path)
            logger.info(f"Loaded download path: {download_path}")
        else:
            logger.warning(f"No download_path in account data")
        
        # Load account's thumbnails path
        thumbnails_path = account_dict.get('thumbnails_path')
        if thumbnails_path:
            self.thumbnails_path = thumbnails_path
            logger.info(f"Loaded thumbnails path: {thumbnails_path}")
        else:
            # Calculate from download_path if available
            if download_path:
                dl_path = Path(download_path)
                if dl_path.name == 'content':
                    self.thumbnails_path = str(dl_path.parent / ".thumbnails")
                else:
                    self.thumbnails_path = str(dl_path / ".thumbnails")
                logger.warning(f"No thumbnails_path, calculated from download_path: {self.thumbnails_path}")
            else:
                self.thumbnails_path = None
                logger.error("No download_path or thumbnails_path - cannot determine thumbnails location")
        
        # Load account's topics root path
        topics_root_path = account_dict.get('topics_root_path')
        if topics_root_path:
            self.topics_root_path = topics_root_path
            logger.info(f"Loaded topics_root_path: {topics_root_path}")
        else:
            if download_path:
                self.topics_root_path = download_path
                logger.warning(f"No topics_root_path, using download_path: {self.topics_root_path}")
            else:
                self.topics_root_path = None
                logger.error("No download_path or topics_root_path - cannot determine topics location")
        
        # Clear failed thumbnail tracking for new account
        self.failed_thumbnail_downloads.clear()
        
        # Load UI settings for this account
        self.load_ui_settings()
        
        # Restore download queue from database
        self.restore_queue_from_database()
        
        # Refresh Settings tab with account paths
        self.refresh_settings_paths()
        logger.info("Settings tab paths refreshed")
        
        # Load saved content entries from database
        if load_database:
            if self.auto_load_at_startup:
                self.load_database_entries_async()
                logger.info(f"Loading database in background for {username}")
            else:
                logger.info(f"Account selected (auto-load disabled)")
                self.browse_status.setText("Click 'Load Database Entries' to view saved content")
        
        logger.info(f"✓ Account '{username}' selected for local data access")
    
    def auto_login(self):
        """Automatically login with the most recent account if available"""
        logger.info("=" * 60)
        logger.info("AUTO-LOGIN STARTED")
        logger.info("=" * 60)
        try:
            accounts = self.account_manager.list_accounts()
            logger.info(f"Found {len(accounts)} account(s) in database")
            if not accounts:
                logger.info("No accounts found - auto-login skipped")
                return
            
            # Get most recent account (they're ordered by last_login DESC)
            account = accounts[0]
            username = account['username']
            ig_username = account.get('ig_username') or username  # Use IG username, fallback to account name
            session_file = Path(account['session_file'])
            
            logger.info(f"Most recent account: {username} (IG: {ig_username})")
            logger.info(f"Session file path: {session_file}")
            
            # Try to login with saved session if session file exists
            login_success = False
            if session_file.exists():
                logger.info(f"Attempting Instagram login with {username} (IG: {ig_username})...")
                login_result = self.instagram_manager.login_detailed(ig_username, "", session_file)
                login_success = bool(login_result.get('success'))
                logger.info(f"Instagram login result: {login_success}")
                self._apply_instagram_manager_status()
            else:
                logger.warning(f"Session file not found for {username} - continuing in offline mode")
            
            if login_success:
                # Instagram authentication successful
                logger.info(f"✓ Instagram login successful for {username}")
                self.instagram_authenticated = True
                self.account_status.setText(f"✓ {username} (Instagram Connected)")
                self.account_status.setStyleSheet(
                    "font-weight: bold; padding: 10px; color: green;"
                )
            else:
                # Instagram login failed or not attempted - continue in offline mode
                logger.info(f"Continuing in offline mode for {username}")
                self.instagram_authenticated = False
            
            # Initialize account data (works with or without Instagram auth)
            self.select_account_for_local_access(account, load_database=True)
            
            if self.instagram_authenticated:
                logger.info("=" * 60)
                logger.info("AUTO-LOGIN COMPLETED SUCCESSFULLY (ONLINE MODE)")
                logger.info("=" * 60)
            else:
                logger.info("=" * 60)
                logger.info("AUTO-LOGIN COMPLETED (OFFLINE MODE - LOCAL DATA ONLY)")
                logger.info("=" * 60)
        except Exception as e:
            logger.error(f"Auto-login error: {e}")
            import traceback
            logger.error(traceback.format_exc())
            logger.info("=" * 60)
            logger.info("AUTO-LOGIN ERROR")
            logger.info("=" * 60)
    
