    def update_vid_prep_audio_mode_ui(self):
        """Enable/disable MP3 controls based on selected audio mode."""
        use_mp3 = self.vid_prep_audio_replace_radio.isChecked() or self.vid_prep_audio_mix_radio.isChecked()
        # Keep list enabled so drag/drop of MP3 files always works.
        self.vid_prep_audio_library_list.setEnabled(True)
        self.vid_prep_sfx_library_list.setEnabled(True)
        self.vid_prep_audio_library_add_btn.setEnabled(use_mp3)
        self.vid_prep_sfx_library_add_btn.setEnabled(use_mp3)
        self._update_vid_prep_audio_library_buttons()
        self._update_vid_prep_sfx_library_buttons()
        self._save_vid_prep_ui_settings()
        self._set_vid_prep_output_preview_dirty(True)

    def create_extract_audio_tab(self):
        """Create tab for extracting audio from video sources."""
        tab = QWidget()
        layout = QVBoxLayout(tab)
        layout.setContentsMargins(8, 8, 8, 8)
        layout.setSpacing(6)

        instructions = QLabel(
            "Load a source video or drag-drop a video file, set audio trim start/end in frames, preview audio, then save the extracted audio file."
        )
        instructions.setWordWrap(True)
        layout.addWidget(instructions)

        # Video drop zone
        self.audio_extract_drop_label = VideoDropLabel("Drop video file here")
        self.audio_extract_drop_label.setFixedHeight(60)
        self.audio_extract_drop_label.setAlignment(Qt.AlignCenter)
        self.audio_extract_drop_label.setStyleSheet(
            "padding: 10px; background-color: #2a2a2a; border: 2px dashed #666; "
            "border-radius: 5px; color: #999;"
        )
        self.audio_extract_drop_label.file_dropped.connect(self.on_audio_extract_video_dropped)
        layout.addWidget(self.audio_extract_drop_label)

        source_row = QHBoxLayout()
        source_row.addWidget(QLabel("Source Video:"))
        self.audio_extract_source_input = QLineEdit()
        self.audio_extract_source_input.setReadOnly(True)
