    def on_framevid_audio_preview_state_changed(self, state):
        """Update preview button labels based on current playback state."""
        is_playing = state == QMediaPlayer.PlayingState
        if hasattr(self, 'framevid_music_preview_btn'):
            self.framevid_music_preview_btn.setText("⏹ Stop" if is_playing else "▶ Preview")
        if hasattr(self, 'framevid_effect_preview_btn'):
            self.framevid_effect_preview_btn.setText("⏹ Stop" if is_playing else "▶ Preview")

    def _preview_framevid_audio_path(self, selected_path):
        """Preview/stop the given audio file using the shared FrameVid preview player."""
        if not selected_path:
            return

        if not os.path.exists(selected_path):
            QMessageBox.warning(self, "FrameVid", "Selected audio file does not exist on disk.")
            return

        current_state = self.framevid_audio_preview_player.state()
        if (
            current_state == QMediaPlayer.PlayingState
            and os.path.normcase(self.framevid_preview_audio_path) == os.path.normcase(selected_path)
        ):
            self.framevid_audio_preview_player.stop()
            self.framevid_preview_audio_path = ''
            return

        self.framevid_audio_preview_player.stop()
        self.framevid_preview_audio_path = selected_path
        self.framevid_audio_preview_player.setMedia(QMediaContent(QUrl.fromLocalFile(selected_path)))
        self.framevid_audio_preview_player.play()

    def preview_selected_framevid_music(self):
        """Preview/stop the currently selected music selection file."""
        item = self.framevid_music_list.currentItem()
        if not item:
            return
        self._preview_framevid_audio_path(self._framevid_list_item_path(item))

    def preview_selected_framevid_effect(self):
        """Preview/stop the currently selected effect selection file."""
        item = self.framevid_effect_list.currentItem()
        if not item:
            return
        self._preview_framevid_audio_path(self._framevid_list_item_path(item))

    def _framevid_file_type(self, file_path):
        """Classify a FrameVid source file."""
        if self._is_image_file_path(file_path):
            return 'image'
        if self._is_video_file_path(file_path):
            return 'video'
        return 'unknown'

    def _is_image_file_path(self, file_path):
        return str(file_path).lower().endswith(('.png', '.jpg', '.jpeg', '.webp', '.bmp', '.gif', '.tif', '.tiff'))

    def _is_video_file_path(self, file_path):
        return str(file_path).lower().endswith(('.mp4', '.mov', '.mkv', '.m4v', '.webm', '.avi', '.flv'))

    def _save_framevid_state_setting(self):
        """Persist FrameVid source/audio track state for the current account."""
        if getattr(self, '_framevid_state_loading', False):
            return
        if not self.current_username:
            return
        try:
            source_items = []
            for i in range(self.framevid_source_list.count()):
                item = self.framevid_source_list.item(i)
                if not item:
                    continue
                data = item.data(Qt.UserRole) or {}
                path = str(data.get('path') or '').strip()
                if not path:
                    continue
                file_type = str(data.get('type') or self._framevid_file_type(path))
                if file_type not in ('image', 'video'):
                    continue
                source_items.append({
                    'path': path,
                    'type': file_type,
                    'duration_seconds': float(data.get('duration_seconds') or 7.0),
                    'fade_in_seconds': float(data.get('fade_in_seconds') if data.get('fade_in_seconds') is not None else 0.25),
                    'fade_out_seconds': float(data.get('fade_out_seconds') if data.get('fade_out_seconds') is not None else 0.25),
                    'clip_start_seconds': float(data.get('clip_start_seconds') or 0.0),
                    'source_media_duration_seconds': float(data.get('source_media_duration_seconds') or 0.0),
                })

            audio_tracks = []
            for i in range(self.framevid_audio_track_list.count()):
                item = self.framevid_audio_track_list.item(i)
                if not item:
                    continue
                data = item.data(Qt.UserRole) or {}
                track_path = str(data.get('track_path') or '').strip()
                if not track_path:
                    continue
                audio_tracks.append({
                    'track_id': int(data.get('track_id') or 0),
                    'track_path': track_path,
                    'track_name': str(data.get('track_name') or os.path.basename(track_path)),
                    'volume_percent': float(data.get('volume_percent') or 100.0),
                    'clip_start_seconds': float(data.get('clip_start_seconds') or 0.0),
                    'clip_end_seconds': float(data.get('clip_end_seconds') or 0.0),
                    'enter_frame': int(data.get('enter_frame') or 0),
                    'exit_frame': int(data.get('exit_frame') or 0),
                    'fade_in_seconds': float(data.get('fade_in_seconds') or 0.0),
                    'fade_out_seconds': float(data.get('fade_out_seconds') or 0.0),
                })

            state_payload = {
                'source_items': source_items,
                'audio_tracks': audio_tracks,
                'source_current_row': int(self.framevid_source_list.currentRow()),
                'audio_current_row': int(self.framevid_audio_track_list.currentRow()),
                'audio_mode': self._current_framevid_audio_mode(),
                'crop_to_max_image_size': bool(self.framevid_crop_to_max_image_checkbox.isChecked()),
            }
            self.save_ui_setting('framevid_state', json.dumps(state_payload))
        except Exception as e:
            logger.debug(f"Failed to save FrameVid state: {e}")

    def _load_framevid_state_setting(self):
        """Restore persisted FrameVid source/audio track state for the current account."""
        if not self.current_username:
            return
        raw_state = self.account_manager.get_account_setting(self.current_username, 'ui_framevid_state', '')
        if not raw_state:
            return

        try:
            parsed = json.loads(raw_state)
        except Exception as e:
            logger.debug(f"Failed to parse FrameVid state: {e}")
            return

        if not isinstance(parsed, dict):
            return

        previous_loading = getattr(self, '_framevid_state_loading', False)
        self._framevid_state_loading = True
        try:
            self.framevid_source_list.clear()
            self.framevid_audio_track_list.clear()

            source_items = parsed.get('source_items') or []
            for entry in source_items:
                if not isinstance(entry, dict):
                    continue
                file_path = str(entry.get('path') or '').strip()
                if not file_path:
                    continue
                file_type = str(entry.get('type') or self._framevid_file_type(file_path))
                if file_type not in ('image', 'video'):
                    continue

                item = QListWidgetItem(os.path.basename(file_path) or file_path)
                item.setToolTip(file_path)
                item.setData(Qt.UserRole, {
                    'path': file_path,
                    'type': file_type,
                    'duration_seconds': float(entry.get('duration_seconds') or 7.0),
                    'fade_in_seconds': float(entry.get('fade_in_seconds') if entry.get('fade_in_seconds') is not None else 0.25),
                    'fade_out_seconds': float(entry.get('fade_out_seconds') if entry.get('fade_out_seconds') is not None else 0.25),
                    'clip_start_seconds': float(entry.get('clip_start_seconds') or 0.0),
                    'source_media_duration_seconds': float(entry.get('source_media_duration_seconds') or 0.0),
                })
                self.framevid_source_list.addItem(item)

            self._refresh_framevid_source_indices()

            audio_tracks = parsed.get('audio_tracks') or []
            max_track_id = 0
            for entry in audio_tracks:
                if not isinstance(entry, dict):
                    continue
                track_path = str(entry.get('track_path') or '').strip()
                if not track_path:
                    continue

                track_id = int(entry.get('track_id') or 0)
                max_track_id = max(max_track_id, track_id)
                display_name = str(entry.get('track_name') or os.path.basename(track_path) or track_path)
                item = QListWidgetItem(display_name)
                item.setToolTip(track_path)
                item.setData(Qt.UserRole, {
                    'track_id': track_id,
                    'track_path': track_path,
                    'track_name': display_name,
                    'volume_percent': float(entry.get('volume_percent') or 100.0),
                    'clip_start_seconds': float(entry.get('clip_start_seconds') or 0.0),
                    'clip_end_seconds': float(entry.get('clip_end_seconds') or 0.0),
                    'enter_frame': int(entry.get('enter_frame') or 0),
                    'exit_frame': int(entry.get('exit_frame') or 0),
                    'fade_in_seconds': float(entry.get('fade_in_seconds') or 0.0),
                    'fade_out_seconds': float(entry.get('fade_out_seconds') or 0.0),
                })
                self.framevid_audio_track_list.addItem(item)

            self.framevid_next_audio_track_id = max(1, max_track_id + 1)

            audio_mode = str(parsed.get('audio_mode') or 'remove').strip().lower()
            if audio_mode == 'replace':
                self.framevid_audio_replace_radio.setChecked(True)
            elif audio_mode == 'maintain':
                self.framevid_audio_maintain_radio.setChecked(True)
            elif audio_mode == 'mix':
                self.framevid_audio_mix_radio.setChecked(True)
            else:
                self.framevid_audio_remove_radio.setChecked(True)
            self.update_framevid_audio_mode_ui()

            self.framevid_crop_to_max_image_checkbox.setChecked(bool(parsed.get('crop_to_max_image_size')))

            source_row = int(parsed.get('source_current_row') or -1)
            if self.framevid_source_list.count() > 0:
                source_row = max(0, min(source_row, self.framevid_source_list.count() - 1))
                self.framevid_source_list.setCurrentRow(source_row)
            else:
                self.framevid_source_list.setCurrentRow(-1)
                self._framevid_input_preview_placeholder()

            audio_row = int(parsed.get('audio_current_row') or -1)
            if self.framevid_audio_track_list.count() > 0:
                audio_row = max(0, min(audio_row, self.framevid_audio_track_list.count() - 1))
                self.framevid_audio_track_list.setCurrentRow(audio_row)
            else:
                self.framevid_audio_track_list.setCurrentRow(-1)

            self.framevid_status_text(
                f"{self.framevid_display_name} state restored ({self.framevid_source_list.count()} source(s), {self.framevid_audio_track_list.count()} track(s))."
            )
        finally:
            self._framevid_state_loading = previous_loading

    def _extract_local_file_paths_from_clipboard(self):
        """Extract local filesystem paths from clipboard MIME/text payloads."""
        clipboard = QApplication.clipboard()
        mime_data = clipboard.mimeData()
        if not mime_data:
            return []

        paths = []

        if mime_data.hasUrls():
            for url in mime_data.urls():
                if url.isLocalFile():
                    local_path = os.path.normpath(url.toLocalFile())
                    if local_path:
                        paths.append(local_path)

        if mime_data.hasText():
            raw_text = (mime_data.text() or '').strip()
            if raw_text:
                for token in re.split(r'[\r\n]+', raw_text):
                    candidate = token.strip().strip('"')
                    if not candidate:
                        continue
                    if candidate.startswith('file:///'):
                        candidate = QUrl(candidate).toLocalFile()
                    candidate = os.path.normpath(candidate)
                    if candidate:
                        paths.append(candidate)

        unique_paths = []
        seen = set()
        for path in paths:
            key = os.path.normcase(path)
            if key in seen:
                continue
            seen.add(key)
            unique_paths.append(path)
        return unique_paths

    def _framevid_clipboard_images_dir(self):
        """Return/create app-local directory for pasted FrameVid clipboard images."""
        base_dir = Path(config.DATA_DIR) / 'framevid_clipboard'
        base_dir.mkdir(parents=True, exist_ok=True)
        return base_dir

    def _save_framevid_clipboard_image(self, image):
        """Save a clipboard image payload to disk and return its path."""
        if image is None or image.isNull():
            return ''

        output_dir = self._framevid_clipboard_images_dir()
        timestamp_ms = int(time.time() * 1000)
        output_path = output_dir / f"clipboard_image_{timestamp_ms}.png"
        if not image.save(str(output_path), 'PNG'):
            return ''
        return str(output_path)

    def paste_framevid_image_from_clipboard(self):
        """Paste clipboard image data or image file path(s) into FrameVid sources."""
        clipboard = QApplication.clipboard()
        mime_data = clipboard.mimeData()

        # Prefer raw image payloads copied from external apps.
        if mime_data and mime_data.hasImage():
            image = clipboard.image()
            saved_path = self._save_framevid_clipboard_image(image)
            if not saved_path:
                pixmap = clipboard.pixmap()
                if pixmap and not pixmap.isNull():
                    saved_path = self._save_framevid_clipboard_image(pixmap.toImage())

            if saved_path:
                self.on_framevid_source_files_dropped([saved_path])
                return

        # Fallback: clipboard might contain copied image file path(s).
        clipboard_paths = self._extract_local_file_paths_from_clipboard()
        image_paths = [path for path in clipboard_paths if self._is_image_file_path(path)]
        if image_paths:
            self.on_framevid_source_files_dropped(image_paths)
            return

        QMessageBox.information(
            self,
            "FrameVid",
            "Clipboard does not contain image data or local image file paths.\n\n"
            "Copy an image (bitmap) or image file(s), then try Paste Image again."
        )

    def paste_framevid_video_from_clipboard(self):
        """Paste copied video file path(s) from clipboard into FrameVid sources."""
        clipboard_paths = self._extract_local_file_paths_from_clipboard()
        if not clipboard_paths:
            QMessageBox.information(
                self,
                "FrameVid",
                "Clipboard does not contain a local file path.\n\n"
                "Copy one or more video files in File Explorer, then try Paste Video again."
            )
            return

        video_paths = [path for path in clipboard_paths if self._is_video_file_path(path)]
        if not video_paths:
            QMessageBox.information(
                self,
                "FrameVid",
                "Clipboard file paths were found, but no supported video files were detected."
            )
            return

        self.on_framevid_source_files_dropped(video_paths)

    def _framevid_add_source_item(self, file_path):
        """Add a file path to the FrameVid source list if valid."""
        if not file_path or not os.path.exists(file_path):
            return False
        file_type = self._framevid_file_type(file_path)
        if file_type == 'unknown':
            return False

        media_duration = 0.0
        if file_type == 'video':
            media_duration = max(0.0, float(self._get_media_duration_seconds(file_path) or 0.0))

        duration_seconds = media_duration if (file_type == 'video' and media_duration > 0.0) else 7.0

        item = QListWidgetItem(os.path.basename(file_path))
        item.setToolTip(file_path)
        item.setData(Qt.UserRole, {
            'path': file_path,
            'type': file_type,
            'duration_seconds': float(duration_seconds),
            'fade_in_seconds': 0.25,
            'fade_out_seconds': 0.25,
            'clip_start_seconds': 0.0,
            'source_media_duration_seconds': float(media_duration),
        })
        self.framevid_source_list.addItem(item)
        return True

    def _framevid_source_display_name(self, item):
        """Return base display name for a FrameVid source item."""
        if not item:
            return ''
        data = item.data(Qt.UserRole) or {}
        path = str(data.get('path') or item.toolTip() or '').strip()
        return os.path.basename(path) or path or (item.text() or '').strip()

    def _refresh_framevid_source_indices(self):
        """Rewrite FrameVid source row labels to include a stable 1-based index."""
        for idx in range(self.framevid_source_list.count()):
            item = self.framevid_source_list.item(idx)
            if not item:
                continue
            base_name = self._framevid_source_display_name(item)
            item.setText(f"[{idx + 1:03d}] {base_name}")

    def _framevid_clamp_video_timing(self, data):
        """Clamp video clip start/duration to source media duration when available."""
        if not isinstance(data, dict):
            return data

        file_type = str(data.get('type') or '')
        if file_type != 'video':
            data['clip_start_seconds'] = 0.0
            return data

        source_path = str(data.get('path') or '')
        media_duration = max(0.0, float(data.get('source_media_duration_seconds') or 0.0))
        if media_duration <= 0.0 and source_path and os.path.exists(source_path):
            media_duration = max(0.0, float(self._get_media_duration_seconds(source_path) or 0.0))
            data['source_media_duration_seconds'] = media_duration

        clip_start = max(0.0, float(data.get('clip_start_seconds') or 0.0))
        clip_duration = max(0.1, float(data.get('duration_seconds') or 3.0))

        if media_duration > 0.0:
            max_start = max(0.0, media_duration - 0.1)
            clip_start = min(clip_start, max_start)
            max_duration = max(0.1, media_duration - clip_start)
            clip_duration = min(clip_duration, max_duration)

        data['clip_start_seconds'] = clip_start
        data['duration_seconds'] = clip_duration
        return data

    def add_framevid_source_files(self):
        """Browse for image/video files to add to FrameVid."""
        start_dir = self.account_manager.get_setting('framevid_last_source_dir', '') or ''
        if not os.path.isdir(start_dir):
            start_dir = ''
        file_paths, _ = QFileDialog.getOpenFileNames(
            self,
            "Add FrameVid Sources",
            start_dir,
            "Media Files (*.png *.jpg *.jpeg *.webp *.bmp *.gif *.tif *.tiff *.mp4 *.mov *.mkv *.m4v *.webm *.avi *.flv);;All Files (*)"
        )
        if file_paths:
            self.account_manager.set_setting('framevid_last_source_dir', os.path.dirname(file_paths[0]))
        self.on_framevid_source_files_dropped(file_paths)

    def on_framevid_source_files_dropped(self, file_paths):
        """Handle media files dropped into FrameVid source list."""
        if not file_paths:
            return
        added = 0
        for file_path in file_paths:
            if self._framevid_add_source_item(file_path):
                added += 1
        if added:
            self._refresh_framevid_source_indices()
            if self.framevid_source_list.count() == added:
                self.framevid_source_list.setCurrentRow(0)
            self.framevid_status_text(f"Added {added} source file(s).")
            self._save_framevid_state_setting()

    def remove_selected_framevid_source(self):
        selected_items = self.framevid_source_list.selectedItems()
        if not selected_items:
            return
        selected_rows = sorted(self.framevid_source_list.row(item) for item in selected_items)
        removed_count = 0
        for row in reversed(selected_rows):
            item = self.framevid_source_list.takeItem(row)
            if item is not None:
                del item
                removed_count += 1
        self._refresh_framevid_source_indices()
        self.framevid_status_text(f"Removed {removed_count} selected source(s).")
        self._save_framevid_state_setting()

    def clear_framevid_sources(self):
        self.framevid_source_list.clear()
        self._refresh_framevid_source_indices()
        self.framevid_status_text("Cleared all sources.")
        self._save_framevid_state_setting()

    def reset_framevid_imagery(self):
        """Remove image entries from FrameVid sources while keeping video/audio state."""
        removed = 0
        for i in range(self.framevid_source_list.count() - 1, -1, -1):
            item = self.framevid_source_list.item(i)
            if not item:
                continue
            data = item.data(Qt.UserRole) or {}
            path = str(data.get('path') or '')
            file_type = str(data.get('type') or self._framevid_file_type(path))
            if file_type == 'image':
                removed_item = self.framevid_source_list.takeItem(i)
                del removed_item
                removed += 1

        if self.framevid_source_list.count() == 0:
            self.framevid_source_list.setCurrentRow(-1)
            self._framevid_input_preview_placeholder()
        elif self.framevid_source_list.currentRow() < 0:
            self.framevid_source_list.setCurrentRow(0)

        self._refresh_framevid_source_indices()
        self.framevid_status_text(f"Reset imagery: removed {removed} image source(s).")
        self._save_framevid_state_setting()

    def reset_framevid_all(self):
        """Clear all FrameVid sources and used audio tracks."""
        source_count = self.framevid_source_list.count()
        track_count = self.framevid_audio_track_list.count()
        self.framevid_player.stop()
        self._framevid_input_preview_placeholder()
        self.framevid_source_list.clear()
        self.framevid_audio_track_list.clear()
        self.framevid_source_list.setCurrentRow(-1)
        self.framevid_audio_track_list.setCurrentRow(-1)
        self._refresh_framevid_source_indices()
        self.framevid_status_text(f"Reset all: removed {source_count} source(s) and {track_count} track(s).")
        self._save_framevid_state_setting()

    def move_selected_framevid_source(self, step):
        selected_items = self.framevid_source_list.selectedItems()
        count = self.framevid_source_list.count()
        if not selected_items or count < 2:
            return

        selected_rows = sorted(self.framevid_source_list.row(item) for item in selected_items)
        delta = -1 if int(step) < 0 else 1

        if delta < 0 and selected_rows[0] <= 0:
            return
        if delta > 0 and selected_rows[-1] >= count - 1:
            return

        row_iter = selected_rows if delta < 0 else list(reversed(selected_rows))
        for row in row_iter:
            item = self.framevid_source_list.takeItem(row)
            self.framevid_source_list.insertItem(row + delta, item)

        self.framevid_source_list.clearSelection()
        for item in selected_items:
            item.setSelected(True)
        if selected_items:
            self.framevid_source_list.setCurrentItem(selected_items[0])

        self._refresh_framevid_source_indices()
        self._save_framevid_state_setting()

    def move_selected_framevid_source_top(self):
        """Move selected source items to the top while preserving their order."""
        selected_items = self.framevid_source_list.selectedItems()
        if not selected_items:
            return
        selected_rows = sorted(self.framevid_source_list.row(item) for item in selected_items)
        if selected_rows and selected_rows[0] == 0:
            return

        moved_items = []
        for offset, row in enumerate(selected_rows):
            moved_items.append(self.framevid_source_list.takeItem(row - offset))

        for index, item in enumerate(moved_items):
            self.framevid_source_list.insertItem(index, item)

        self.framevid_source_list.clearSelection()
        for item in moved_items:
            item.setSelected(True)
        if moved_items:
            self.framevid_source_list.setCurrentItem(moved_items[0])

        self._refresh_framevid_source_indices()
        self._save_framevid_state_setting()

    def move_selected_framevid_source_bottom(self):
        """Move selected source items to the bottom while preserving their order."""
        selected_items = self.framevid_source_list.selectedItems()
        if not selected_items:
            return

        count = self.framevid_source_list.count()
        selected_rows = sorted(self.framevid_source_list.row(item) for item in selected_items)
        if selected_rows and selected_rows[-1] == count - 1:
            return

        moved_items = []
        for row in reversed(selected_rows):
            moved_items.append(self.framevid_source_list.takeItem(row))
        moved_items.reverse()

        for item in moved_items:
            self.framevid_source_list.addItem(item)

        self.framevid_source_list.clearSelection()
        for item in moved_items:
            item.setSelected(True)
        if moved_items:
            self.framevid_source_list.setCurrentItem(moved_items[0])

        self._refresh_framevid_source_indices()
        self._save_framevid_state_setting()

    def on_framevid_source_rows_moved(self, *args):
        """Keep source indices correct after drag/drop reorder in source list."""
        self._refresh_framevid_source_indices()
        self._save_framevid_state_setting()

    def on_framevid_source_selection_changed(self, current, previous):
        item = current or self.framevid_source_list.currentItem()
        self._framevid_source_editor_updating = True
        try:
            if not item:
                self.framevid_source_duration_spin.setValue(3.0)
                self.framevid_source_fade_in_spin.setValue(0.25)
                self.framevid_source_fade_out_spin.setValue(0.25)
                self._framevid_input_preview_placeholder()
                return
            data = item.data(Qt.UserRole) or {}
            data = self._framevid_clamp_video_timing(data)
            item.setData(Qt.UserRole, data)
            self.framevid_source_duration_spin.setValue(float(data.get('duration_seconds') or 3.0))
            # Use 'if not None' to properly preserve 0.0 fade values
            fade_in = data.get('fade_in_seconds')
            self.framevid_source_fade_in_spin.setValue(float(fade_in) if fade_in is not None else 0.25)
            fade_out = data.get('fade_out_seconds')
            self.framevid_source_fade_out_spin.setValue(float(fade_out) if fade_out is not None else 0.25)
            file_path = str(data.get('path') or '')
            file_type = str(data.get('type') or self._framevid_file_type(file_path))
            self._framevid_update_input_preview(file_path, file_type)
        finally:
            self._framevid_source_editor_updating = False

    def on_framevid_source_editor_changed(self, *args):
        if getattr(self, '_framevid_source_editor_updating', False):
            return
        self.apply_framevid_timing_to_current_source(show_status=False)

    def apply_framevid_timing_to_current_source(self, show_status=True):
        """Apply current timing editor values to the active FrameVid source item."""
        item = self.framevid_source_list.currentItem()
        if not item:
            return
        data = item.data(Qt.UserRole) or {}
        data['duration_seconds'] = float(self.framevid_source_duration_spin.value())
        data['fade_in_seconds'] = float(self.framevid_source_fade_in_spin.value())
        data['fade_out_seconds'] = float(self.framevid_source_fade_out_spin.value())
        data = self._framevid_clamp_video_timing(data)
        self.framevid_source_duration_spin.blockSignals(True)
        self.framevid_source_duration_spin.setValue(float(data.get('duration_seconds') or 3.0))
        self.framevid_source_duration_spin.blockSignals(False)
        item.setData(Qt.UserRole, data)
        if show_status:
            label = item.text() or os.path.basename(str(data.get('path') or '')) or 'selected frame'
            self.framevid_status_text(f"Applied timing to: {label}")
        self._save_framevid_state_setting()

    def apply_framevid_timing_to_all_sources(self):
        """Apply current source timing editor values to all FrameVid sources."""
        total = self.framevid_source_list.count()
        if total <= 0:
            return

        duration_seconds = float(self.framevid_source_duration_spin.value())
        fade_in_seconds = float(self.framevid_source_fade_in_spin.value())
        fade_out_seconds = float(self.framevid_source_fade_out_spin.value())

        updated = 0
        for i in range(total):
            item = self.framevid_source_list.item(i)
            if not item:
                continue
            data = item.data(Qt.UserRole) or {}
            data['duration_seconds'] = duration_seconds
            data['fade_in_seconds'] = fade_in_seconds
            data['fade_out_seconds'] = fade_out_seconds
            data = self._framevid_clamp_video_timing(data)
            item.setData(Qt.UserRole, data)
            updated += 1

        # Refresh the editor to show the updated values for the currently selected frame
        current_item = self.framevid_source_list.currentItem()
        if current_item:
            self.on_framevid_source_selection_changed(current_item, None)
        
        self.framevid_status_text(f"Applied frame timing (duration: {duration_seconds}s, fade in: {fade_in_seconds}s, fade out: {fade_out_seconds}s) to {updated} source(s).")
        self._save_framevid_state_setting()

    def apply_framevid_timing_to_selected_sources(self):
        """Apply current source timing editor values to selected FrameVid sources."""
        selected_items = self.framevid_source_list.selectedItems()
        if not selected_items:
            self.framevid_status_text("Select one or more source frames first.")
            return

        duration_seconds = float(self.framevid_source_duration_spin.value())
        fade_in_seconds = float(self.framevid_source_fade_in_spin.value())
        fade_out_seconds = float(self.framevid_source_fade_out_spin.value())

        updated = 0
        for item in selected_items:
            if not item:
                continue
            data = item.data(Qt.UserRole) or {}
            data['duration_seconds'] = duration_seconds
            data['fade_in_seconds'] = fade_in_seconds
            data['fade_out_seconds'] = fade_out_seconds
            data = self._framevid_clamp_video_timing(data)
            item.setData(Qt.UserRole, data)
            updated += 1

        # Refresh the editor to show the updated values for the currently selected frame
        current_item = self.framevid_source_list.currentItem()
        if current_item:
            self.on_framevid_source_selection_changed(current_item, None)
        
        self.framevid_status_text(f"Applied frame timing (duration: {duration_seconds}s, fade in: {fade_in_seconds}s, fade out: {fade_out_seconds}s) to {updated} selected source(s).")
        self._save_framevid_state_setting()

    def on_framevid_section_type_changed(self, section_type):
        """Update section partition options for the selected section type."""
        normalized = str(section_type or '').strip().lower()
        section_count_map = {
            'quarter': 4,
            'half': 2,
            'third': 3,
        }
        count = section_count_map.get(normalized, 4)
        current_text = self.framevid_section_partition_combo.currentText() if hasattr(self, 'framevid_section_partition_combo') else '1'
        self.framevid_section_partition_combo.blockSignals(True)
        self.framevid_section_partition_combo.clear()
        for i in range(1, count + 1):
            self.framevid_section_partition_combo.addItem(str(i))
        index = self.framevid_section_partition_combo.findText(current_text)
        if index < 0:
            index = 0
        self.framevid_section_partition_combo.setCurrentIndex(index)
        self.framevid_section_partition_combo.blockSignals(False)

    def apply_framevid_full_video_time_to_current_source(self):
        """Set selected video source timing to full source duration."""
        item = self.framevid_source_list.currentItem()
        if not item:
            return

        data = item.data(Qt.UserRole) or {}
        if str(data.get('type') or '') != 'video':
            self.framevid_status_text("Full Video Time applies to video sources only.")
            return

        source_path = str(data.get('path') or '')
        media_duration = max(0.0, float(data.get('source_media_duration_seconds') or 0.0))
        if media_duration <= 0.0 and source_path and os.path.exists(source_path):
            media_duration = max(0.0, float(self._get_media_duration_seconds(source_path) or 0.0))

        if media_duration <= 0.0:
            self.framevid_status_text("Could not determine source video duration.")
            return

        data['source_media_duration_seconds'] = media_duration
        data['clip_start_seconds'] = 0.0
        data['duration_seconds'] = media_duration
        data = self._framevid_clamp_video_timing(data)
        item.setData(Qt.UserRole, data)

        self._framevid_source_editor_updating = True
        try:
            self.framevid_source_duration_spin.setValue(float(data.get('duration_seconds') or media_duration))
        finally:
            self._framevid_source_editor_updating = False

        label = item.text() or os.path.basename(source_path) or 'selected video'
        self.framevid_status_text(f"Applied Full Video Time: {label}")
        self._save_framevid_state_setting()

    def apply_framevid_section_to_current_source(self):
        """Apply selected section type/partition to current video source."""
        item = self.framevid_source_list.currentItem()
        if not item:
            return

        data = item.data(Qt.UserRole) or {}
        if str(data.get('type') or '') != 'video':
            self.framevid_status_text("Apply Section applies to video sources only.")
            return

        source_path = str(data.get('path') or '')
        media_duration = max(0.0, float(data.get('source_media_duration_seconds') or 0.0))
        if media_duration <= 0.0 and source_path and os.path.exists(source_path):
            media_duration = max(0.0, float(self._get_media_duration_seconds(source_path) or 0.0))

        if media_duration <= 0.0:
            self.framevid_status_text("Could not determine source video duration.")
            return

        section_type = str(self.framevid_section_type_combo.currentText() or 'Quarter').strip()
        partition_text = str(self.framevid_section_partition_combo.currentText() or '1').strip()
        try:
            partition = max(1, int(partition_text))
        except Exception:
            partition = 1

        section_count_map = {
            'quarter': 4,
            'half': 2,
            'third': 3,
        }
        section_count = section_count_map.get(section_type.lower(), 4)
        partition = max(1, min(partition, section_count))

        section_len = media_duration / float(section_count)
        section_start = max(0.0, section_len * float(partition - 1))
        if partition >= section_count:
            section_end = media_duration
        else:
            section_end = section_start + section_len

        data['source_media_duration_seconds'] = media_duration
        data['clip_start_seconds'] = section_start
        data['duration_seconds'] = max(0.1, section_end - section_start)
        data = self._framevid_clamp_video_timing(data)
        item.setData(Qt.UserRole, data)

        self._framevid_source_editor_updating = True
        try:
            self.framevid_source_duration_spin.setValue(float(data.get('duration_seconds') or section_len))
        finally:
            self._framevid_source_editor_updating = False

        label = item.text() or os.path.basename(source_path) or 'selected video'
        self.framevid_status_text(f"Applied {section_type} {partition} to: {label}")
        self._save_framevid_state_setting()

    def add_framevid_audio_tracks(self):
        file_paths, _ = QFileDialog.getOpenFileNames(
            self,
            "Add FrameVid Audio Tracks",
            "",
            "Audio Files (*.mp3 *.wav *.m4a *.aac *.flac *.ogg);;All Files (*)"
        )
        self.on_framevid_audio_tracks_dropped(file_paths)

    def _framevid_add_audio_track_item(self, file_path):
        if not file_path or not os.path.exists(file_path):
            return False
        normalized = self._normalize_vid_prep_audio_path(file_path)
        if not normalized:
            return False
        item = QListWidgetItem(os.path.basename(normalized))
        item.setToolTip(normalized)
        item.setData(Qt.UserRole, {
            'track_id': int(self.framevid_next_audio_track_id),
            'track_path': normalized,
            'track_name': os.path.basename(normalized),
            'volume_percent': 100.0,
            'clip_start_seconds': 0.0,
            'clip_end_seconds': float(self._get_vid_prep_audio_duration_seconds(normalized) or 0.0),
            'enter_frame': 0,
            'exit_frame': 0,
            'fade_in_seconds': 0.0,
            'fade_out_seconds': 0.0,
        })
        self.framevid_next_audio_track_id += 1
        self.framevid_audio_track_list.addItem(item)
        return True

    def _framevid_find_audio_track_item_by_path(self, file_path):
        """Find existing FrameVid audio track item by normalized path."""
        normalized = self._normalize_vid_prep_audio_path(file_path)
        if not normalized:
            return None
        for i in range(self.framevid_audio_track_list.count()):
            item = self.framevid_audio_track_list.item(i)
            if not item:
                continue
            data = item.data(Qt.UserRole) or {}
            track_path = self._normalize_vid_prep_audio_path(str(data.get('track_path') or ''))
            if track_path and os.path.normcase(track_path) == os.path.normcase(normalized):
                return item
        return None

    def _framevid_source_start_frame_options(self):
        """Return selectable source-frame options as (label, start_frame)."""
        options = []
        fps = 30.0
        timeline_seconds = 0.0
        for idx in range(self.framevid_source_list.count()):
            item = self.framevid_source_list.item(idx)
            if not item:
                continue
            data = item.data(Qt.UserRole) or {}
            source_path = str(data.get('path') or '')
            if not source_path or not os.path.exists(source_path):
                continue
            start_frame = max(0, int(round(timeline_seconds * fps)))
            duration_s = max(0.1, float(data.get('duration_seconds') or 3.0))
            source_name = os.path.basename(source_path) or source_path
            label = f"#{len(options) + 1} {source_name} -> start frame {start_frame}"
            options.append((label, start_frame))
            timeline_seconds += duration_s
        return options

    def on_framevid_start_at_frame_track_dropped(self, file_path):
        """Drop handler: choose source frame and set dropped track start frame."""
        if not self.framevid_source_list.count():
            QMessageBox.warning(self, "FrameVid", "Add FrameVid source files first, then assign track start frames.")
            return

        track_item = self._framevid_find_audio_track_item_by_path(file_path)
        if not track_item and file_path and os.path.exists(file_path):
            if self._framevid_add_audio_track_item(file_path):
                track_item = self._framevid_find_audio_track_item_by_path(file_path)

        if not track_item:
            track_item = self.framevid_audio_track_list.currentItem()

        if not track_item:
            QMessageBox.warning(self, "FrameVid", "Drop an audio track from Used Track List (or a valid audio file) to assign Start at Frame.")
            return

        options = self._framevid_source_start_frame_options()
        if not options:
            QMessageBox.warning(self, "FrameVid", "No valid FrameVid source frames available to target.")
            return

        labels = [label for label, _frame in options]
        selected_label, ok = QInputDialog.getItem(
            self,
            "Start at Frame",
            "Select FrameVid frame where this track starts:",
            labels,
            0,
            False,
        )
        if not ok or not selected_label:
            return

        frame_lookup = {label: frame for label, frame in options}
        start_frame = int(frame_lookup.get(selected_label, 0))
        data = track_item.data(Qt.UserRole) or {}
        data['enter_frame'] = start_frame
        track_item.setData(Qt.UserRole, data)

        row = self.framevid_audio_track_list.row(track_item)
        if row >= 0:
            self.framevid_audio_track_list.setCurrentRow(row)
        self.on_framevid_audio_track_selection_changed()
        self._save_framevid_state_setting()
        self.framevid_status_text(f"Assigned track start frame: {start_frame}")

    def on_framevid_audio_tracks_dropped(self, file_paths):
        if not file_paths:
            return
        added = 0
        for file_path in file_paths:
            if self._framevid_add_audio_track_item(file_path):
                added += 1
        if added and self.framevid_audio_track_list.count() == added:
            self.framevid_audio_track_list.setCurrentRow(0)
        if added:
            self._save_framevid_state_setting()

    def remove_selected_framevid_audio_track(self):
        row = self.framevid_audio_track_list.currentRow()
        if row < 0:
            return
        item = self.framevid_audio_track_list.takeItem(row)
        del item
        self._save_framevid_state_setting()

    def clear_framevid_audio_tracks(self):
        self.framevid_audio_track_list.clear()
        self._save_framevid_state_setting()

    def move_selected_framevid_audio_track(self, step):
        row = self.framevid_audio_track_list.currentRow()
        count = self.framevid_audio_track_list.count()
        if row < 0 or count < 2:
            return
        new_row = max(0, min(count - 1, row + int(step)))
        if new_row == row:
            return
        item = self.framevid_audio_track_list.takeItem(row)
        self.framevid_audio_track_list.insertItem(new_row, item)
        self.framevid_audio_track_list.setCurrentRow(new_row)
        self._save_framevid_state_setting()

    def on_framevid_audio_track_selection_changed(self):
        item = self.framevid_audio_track_list.currentItem()
        self._framevid_audio_track_editor_updating = True
        try:
            if not item:
                self.framevid_track_volume_spin.setValue(100.0)
                self.framevid_track_clip_start_spin.setValue(0.0)
                self.framevid_track_clip_end_spin.setValue(0.0)
                self.framevid_track_enter_frame_spin.setValue(0)
                self.framevid_track_exit_frame_spin.setValue(0)
                self.framevid_track_fade_in_spin.setValue(0.0)
                self.framevid_track_fade_out_spin.setValue(0.0)
                return
            data = item.data(Qt.UserRole) or {}
            self.framevid_track_volume_spin.setValue(float(data.get('volume_percent') or 100.0))
            self.framevid_track_clip_start_spin.setValue(float(data.get('clip_start_seconds') or 0.0))
            self.framevid_track_clip_end_spin.setValue(float(data.get('clip_end_seconds') or 0.0))
            self.framevid_track_enter_frame_spin.setValue(int(data.get('enter_frame') or 0))
            self.framevid_track_exit_frame_spin.setValue(int(data.get('exit_frame') or 0))
            self.framevid_track_fade_in_spin.setValue(float(data.get('fade_in_seconds') or 0.0))
            self.framevid_track_fade_out_spin.setValue(float(data.get('fade_out_seconds') or 0.0))
        finally:
            self._framevid_audio_track_editor_updating = False

    def on_framevid_audio_track_editor_changed(self, *args):
        if self._framevid_audio_track_editor_updating:
            return
        item = self.framevid_audio_track_list.currentItem()
        if not item:
            return
        data = item.data(Qt.UserRole) or {}
        data['volume_percent'] = float(self.framevid_track_volume_spin.value())
        data['clip_start_seconds'] = float(self.framevid_track_clip_start_spin.value())
        data['clip_end_seconds'] = float(self.framevid_track_clip_end_spin.value())
        data['enter_frame'] = int(self.framevid_track_enter_frame_spin.value())
        data['exit_frame'] = int(self.framevid_track_exit_frame_spin.value())
        data['fade_in_seconds'] = float(self.framevid_track_fade_in_spin.value())
        data['fade_out_seconds'] = float(self.framevid_track_fade_out_spin.value())
        item.setData(Qt.UserRole, data)

    def _framevid_source_items_in_order(self):
        items = []
        for i in range(self.framevid_source_list.count()):
            item = self.framevid_source_list.item(i)
            if not item:
                continue
            data = item.data(Qt.UserRole) or {}
            if data.get('path') and os.path.exists(data.get('path')):
                items.append(data)
        return items

    def _framevid_audio_tracks_in_order(self):
        tracks = []
        for i in range(self.framevid_audio_track_list.count()):
            item = self.framevid_audio_track_list.item(i)
            if not item:
                continue
            data = item.data(Qt.UserRole) or {}
            if data.get('track_path') and os.path.exists(data.get('track_path')):
                tracks.append(data)
        return tracks

    def framevid_status_text(self, text):
        if hasattr(self, 'framevid_time_label'):
            self.framevid_time_label.setText(text)

    def on_framevid_duration_changed(self, duration_ms):
        self.framevid_time_label.setText(f"00:00.000 / {self._format_vid_prep_time(max(0, int(duration_ms)) / 1000.0)}")

    def on_framevid_position_changed(self, position_ms):
        duration_ms = max(0, int(self.framevid_player.duration()))
        self.framevid_time_label.setText(f"{self._format_vid_prep_time(max(0, int(position_ms)) / 1000.0)} / {self._format_vid_prep_time(duration_ms / 1000.0)}")

    def stop_framevid_preview(self):
        self.framevid_player.stop()
        self.framevid_player.setPosition(0)
        duration_ms = max(0, int(self.framevid_player.duration()))
        self.framevid_time_label.setText(f"00:00.000 / {self._format_vid_prep_time(duration_ms / 1000.0)}")
        if hasattr(self, 'framevid_pause_btn'):
            self.framevid_pause_btn.setText("⏸ Pause")

    def on_framevid_player_state_changed(self, state):
        """Update Composer Pause button label based on player state."""
        if not hasattr(self, 'framevid_pause_btn'):
            return
        if state == QMediaPlayer.PausedState:
            self.framevid_pause_btn.setText("▶ Resume")
        else:
            self.framevid_pause_btn.setText("⏸ Pause")

    def toggle_framevid_preview_pause_resume(self):
        """Toggle Composer output preview between pause and resume."""
        if self.framevid_player is None:
            return

        state = self.framevid_player.state()
        if state == QMediaPlayer.PlayingState:
            self.framevid_player.pause()
            return
        if state == QMediaPlayer.PausedState:
            self.framevid_player.play()
            return

        # Stopped state: resume from current marker if media is loaded, otherwise render preview.
        if self.framevid_player.media() is not None and not self.framevid_player.media().isNull():
            self.framevid_player.play()
        else:
            self.preview_framevid_video()

    def _framevid_set_render_progress(self, visible, current_step=0, total_steps=1):
        """Show/hide and update the inline FrameVid render progress bar."""
        if not hasattr(self, 'framevid_render_progress'):
            return
        total_steps = max(1, int(total_steps or 1))
        current_step = max(0, min(int(current_step or 0), total_steps))
        self.framevid_render_progress.setMaximum(total_steps)
        self.framevid_render_progress.setValue(current_step)
        self.framevid_render_progress.setVisible(bool(visible))
        QApplication.processEvents()

    def _framevid_render_progress_callback(self, status_text, current_step, total_steps):
        """Progress callback used by FrameVid preview/save rendering."""
        self._framevid_set_render_progress(True, current_step, total_steps)
        self.framevid_status_text(status_text)

    def preview_framevid_video(self):
        self._framevid_set_render_progress(True, 0, 1)
        try:
            preview_path = self._render_framevid_video(
                tempfile.gettempdir(),
                progress_callback=self._framevid_render_progress_callback,
            )
        except Exception as e:
            self._framevid_set_render_progress(False, 0, 1)
            QMessageBox.warning(self, "FrameVid", str(e))
            return
        self._framevid_set_render_progress(False, 0, 1)
        self.framevid_last_preview_path = preview_path
        self.framevid_player.setMedia(QMediaContent(QUrl.fromLocalFile(preview_path)))
        self.framevid_player.play()
        if hasattr(self, 'framevid_pause_btn'):
            self.framevid_pause_btn.setText("⏸ Pause")

    def save_framevid_video(self):
        default_name = "framevid_output.mp4"
        last_save_dir = self.account_manager.get_setting('framevid_last_save_dir', '') or ''
        if os.path.isdir(last_save_dir):
            default_name = os.path.join(last_save_dir, default_name)
        output_path, _ = QFileDialog.getSaveFileName(self, "Save FrameVid Video", default_name, "Video Files (*.mp4);;All Files (*)")
        if not output_path:
            return
        self.account_manager.set_setting('framevid_last_save_dir', str(Path(output_path).parent))
        self._framevid_set_render_progress(True, 0, 1)
        try:
            final_path = self._render_framevid_video(
                Path(output_path).parent,
                output_path,
                progress_callback=self._framevid_render_progress_callback,
            )
        except Exception as e:
            self._framevid_set_render_progress(False, 0, 1)
            QMessageBox.warning(self, "FrameVid", str(e))
            return
        self._framevid_set_render_progress(False, 0, 1)
        self.framevid_last_preview_path = final_path
        QMessageBox.information(self, "FrameVid", f"Saved video:\n{final_path}")

    def _render_framevid_video(self, temp_parent, output_path=None, progress_callback=None):
        """Render the current FrameVid queue into an mp4 file."""
        if not self.framevid_source_list.count():
            raise ValueError("Add at least one image or video file.")

        ffmpeg_bin = shutil.which("ffmpeg")
        if not ffmpeg_bin:
            raise ValueError("ffmpeg is not available on PATH.")

        render_dir = Path(tempfile.mkdtemp(prefix='framevid_', dir=str(temp_parent)))
        segment_paths = []
        fps = 30

        source_items = self._framevid_source_items_in_order()
        crop_to_max_image = bool(self.framevid_crop_to_max_image_checkbox.isChecked())
        target_w, target_h = 1080, 1920
        if crop_to_max_image:
            max_dims = self._get_framevid_max_image_dimensions(source_items)
            if max_dims:
                target_w, target_h = max_dims
        audio_tracks = self._framevid_audio_tracks_in_order()
        audio_mode = self._current_framevid_audio_mode()
        include_source_audio = audio_mode in ('maintain', 'mix')
        include_music_audio = audio_mode in ('replace', 'mix')
        total_steps = len(source_items) + 1 + (1 if (include_music_audio and audio_tracks) else 0)
        if progress_callback:
            progress_callback("Preparing FrameVid render...", 0, total_steps)

        for index, item_data in enumerate(source_items, start=1):
            source_path = str(item_data.get('path') or '')
            duration_s = max(0.1, float(item_data.get('duration_seconds') or 3.0))
            fade_in_s = max(0.0, float(item_data.get('fade_in_seconds') or 0.0))
            fade_out_s = max(0.0, float(item_data.get('fade_out_seconds') or 0.0))
            is_image = item_data.get('type') == 'image'
            clip_start_s = max(0.0, float(item_data.get('clip_start_seconds') or 0.0))
            media_duration_s = max(0.0, float(item_data.get('source_media_duration_seconds') or 0.0))
            if (not is_image) and media_duration_s <= 0.0:
                media_duration_s = max(0.0, float(self._get_media_duration_seconds(source_path) or 0.0))
            if (not is_image) and media_duration_s > 0.0:
                clip_start_s = min(clip_start_s, max(0.0, media_duration_s - 0.1))
                duration_s = min(duration_s, max(0.1, media_duration_s - clip_start_s))
            segment_path = render_dir / f"segment_{index:03d}.mp4"

            fade_out_start = max(0.0, duration_s - fade_out_s)
            if crop_to_max_image:
                scale_and_frame_vf = (
                    f"scale={target_w}:{target_h}:force_original_aspect_ratio=increase,"
                    f"crop={target_w}:{target_h}"
                )
            else:
                scale_and_frame_vf = (
                    f"scale={target_w}:{target_h}:force_original_aspect_ratio=decrease,"
                    f"pad={target_w}:{target_h}:(ow-iw)/2:(oh-ih)/2:black"
                )
            
            # Build video filter chain - only add fade filters when duration > 0
            vf_parts = [scale_and_frame_vf, f"fps={fps}", "format=yuv420p"]
            if fade_in_s > 0:
                vf_parts.append(f"fade=t=in:st=0:d={min(fade_in_s, duration_s):.3f}")
            if fade_out_s > 0:
                vf_parts.append(f"fade=t=out:st={fade_out_start:.3f}:d={min(fade_out_s, duration_s):.3f}")
            vf = ','.join(vf_parts)

            cmd = [ffmpeg_bin, '-y']
            if is_image:
                cmd.extend([
                    '-loop', '1',
                    '-i', source_path,
                    '-f', 'lavfi',
                    '-i', 'anullsrc=channel_layout=stereo:sample_rate=48000',
                    '-t', f'{duration_s:.3f}',
                    '-vf', vf,
                    '-r', str(fps),
                    '-pix_fmt', 'yuv420p',
                    '-map', '0:v:0',
                    '-map', '1:a:0',
                    '-c:a', 'aac',
                    '-ar', '48000',
                    '-ac', '2',
                    '-shortest',
                    str(segment_path),
                ])
            else:
                has_source_audio = self._media_has_audio_stream(source_path)
                cmd.extend(['-ss', f'{clip_start_s:.3f}', '-i', source_path])
                if not has_source_audio:
                    cmd.extend(['-f', 'lavfi', '-i', 'anullsrc=channel_layout=stereo:sample_rate=48000'])
                cmd.extend([
                    '-t', f'{duration_s:.3f}',
                    '-vf', vf,
                    '-r', str(fps),
                    '-pix_fmt', 'yuv420p',
                    '-map', '0:v:0',
                    '-map', '0:a:0' if has_source_audio else '1:a:0',
                    '-c:a', 'aac',
                    '-ar', '48000',
                    '-ac', '2',
                    '-shortest',
                    str(segment_path),
                ])
            try:
                subprocess.run(cmd, check=True, capture_output=True, text=True)
            except subprocess.CalledProcessError as e:
                stderr_text = (e.stderr or '').strip()
                stdout_text = (e.stdout or '').strip()
                detail = stderr_text or stdout_text or str(e)
                raise RuntimeError(f"Failed to render segment {index}: {detail}") from e
            segment_paths.append(segment_path)
            if progress_callback:
                progress_callback(f"Rendering source {index}/{len(source_items)}...", index, total_steps)

        concat_file = render_dir / 'concat.txt'
        concat_lines = []
        for path in segment_paths:
            safe_path = str(path).replace("'", "\\'")
            concat_lines.append(f"file '{safe_path}'")
        concat_file.write_text('\n'.join(concat_lines), encoding='utf-8')
        video_only_path = render_dir / 'framevid_video.mp4'
        try:
            subprocess.run([ffmpeg_bin, '-y', '-f', 'concat', '-safe', '0', '-i', str(concat_file), '-c', 'copy', str(video_only_path)], check=True, capture_output=True, text=True)
        except subprocess.CalledProcessError as e:
            stderr_text = (e.stderr or '').strip()
            stdout_text = (e.stdout or '').strip()
            detail = stderr_text or stdout_text or str(e)
            raise RuntimeError(f"Failed to concatenate rendered segments: {detail}") from e

        if progress_callback:
            progress_callback("Concatenation complete.", len(source_items) + 1, total_steps)

        def _export_muted_video(src_path, dst_path):
            cmd = [ffmpeg_bin, '-y', '-i', str(src_path), '-map', '0:v', '-an', '-c:v', 'copy', str(dst_path)]
            try:
                subprocess.run(cmd, check=True, capture_output=True, text=True)
            except subprocess.CalledProcessError as e:
                stderr_text = (e.stderr or '').strip()
                stdout_text = (e.stdout or '').strip()
                detail = stderr_text or stdout_text or str(e)
                raise RuntimeError(f"Failed to remove FrameVid audio: {detail}") from e

        if not include_source_audio and not include_music_audio:
            muted_output = render_dir / 'framevid_video_muted.mp4'
            _export_muted_video(video_only_path, muted_output)
            if output_path:
                shutil.copyfile(str(muted_output), str(output_path))
                return str(output_path)
            return str(muted_output)

        if include_source_audio and not include_music_audio:
            if output_path:
                shutil.copyfile(str(video_only_path), str(output_path))
                return str(output_path)
            return str(video_only_path)

        if not audio_tracks:
            if include_source_audio:
                if output_path:
                    shutil.copyfile(str(video_only_path), str(output_path))
                    return str(output_path)
                return str(video_only_path)
            muted_output = render_dir / 'framevid_video_muted.mp4'
            _export_muted_video(video_only_path, muted_output)
            if output_path:
                shutil.copyfile(str(muted_output), str(output_path))
                return str(output_path)
            return str(muted_output)

        video_duration = self._get_media_duration_seconds(str(video_only_path))
        mix_output = render_dir / 'framevid_audio.mp4'
        audio_inputs = []
        filter_parts = []
        mix_input_index = 1
        mix_labels = []

        if include_source_audio and self._media_has_audio_stream(str(video_only_path)):
            filter_parts.append('[0:a]asetpts=PTS-STARTPTS,volume=1.000[src0]')
            mix_labels.append('[src0]')

        for track in audio_tracks:
            track_path = str(track.get('track_path') or '')
            if not track_path or not os.path.exists(track_path):
                continue
            audio_inputs.extend(['-i', track_path])
            clip_start = max(0.0, float(track.get('clip_start_seconds') or 0.0))
            clip_end = float(track.get('clip_end_seconds') or 0.0)
            volume = max(0.0, float(track.get('volume_percent') or 100.0) / 100.0)
            fade_in = max(0.0, float(track.get('fade_in_seconds') or 0.0))
            fade_out = max(0.0, float(track.get('fade_out_seconds') or 0.0))
            enter_frame = int(track.get('enter_frame') or 0)
            exit_frame = int(track.get('exit_frame') or 0)
            start_ms = max(0, int((enter_frame / 30.0) * 1000))
            if clip_end > clip_start:
                clip_filter = [f'atrim=start={clip_start:.3f}:end={clip_end:.3f}']
            else:
                clip_filter = [f'atrim=start={clip_start:.3f}']
            clip_filter.append('asetpts=PTS-STARTPTS')
            clip_filter.append(f'volume={volume:.3f}')
            clip_duration = max(0.1, (clip_end - clip_start) if clip_end > clip_start else max(0.1, (exit_frame - enter_frame) / 30.0 if exit_frame > enter_frame else video_duration))
            if fade_in > 0:
                clip_filter.append(f'afade=t=in:st=0:d={min(fade_in, clip_duration):.3f}')
            if fade_out > 0:
                clip_filter.append(f'afade=t=out:st={max(0.0, clip_duration - fade_out):.3f}:d={min(fade_out, clip_duration):.3f}')
            if start_ms > 0:
                clip_filter.append(f'adelay={start_ms}|{start_ms}')
            label = f'a{mix_input_index}'
            filter_parts.append(f'[{mix_input_index}:a]' + ','.join(clip_filter) + f'[{label}]')
            mix_labels.append(f'[{label}]')
            mix_input_index += 1

        if filter_parts:
            if progress_callback:
                progress_callback("Mixing audio tracks...", len(source_items) + 1, total_steps)
            amix_inputs = ''.join(mix_labels)
            filter_parts.append(f'{amix_inputs}amix=inputs={len(mix_labels)}:normalize=0[mixed]')
            cmd = [ffmpeg_bin, '-y', '-i', str(video_only_path)] + audio_inputs + ['-filter_complex', ';'.join(filter_parts), '-map', '0:v', '-map', '[mixed]', '-c:v', 'copy', '-c:a', 'aac', '-shortest', str(mix_output)]
            try:
                subprocess.run(cmd, check=True, capture_output=True, text=True)
            except subprocess.CalledProcessError as e:
                stderr_text = (e.stderr or '').strip()
                stdout_text = (e.stdout or '').strip()
                detail = stderr_text or stdout_text or str(e)
                raise RuntimeError(f"Failed to mix FrameVid audio tracks: {detail}") from e
            final_path = mix_output
            if progress_callback:
                progress_callback("Audio mix complete.", total_steps, total_steps)
        else:
            if include_source_audio:
                final_path = video_only_path
            else:
                muted_output = render_dir / 'framevid_video_muted.mp4'
                _export_muted_video(video_only_path, muted_output)
                final_path = muted_output

        if output_path:
            shutil.copyfile(str(final_path), str(output_path))
            return str(output_path)
        return str(final_path)

    def _get_media_duration_seconds(self, file_path):
        """Best-effort media duration probe in seconds."""
        ffprobe_bin = shutil.which('ffprobe')
        if not ffprobe_bin or not file_path or not os.path.exists(file_path):
            return 0.0
        try:
            result = subprocess.run([ffprobe_bin, '-v', 'error', '-show_entries', 'format=duration', '-of', 'default=noprint_wrappers=1:nokey=1', file_path], capture_output=True, text=True, check=False)
            return max(0.0, float((result.stdout or '').strip() or 0.0))
        except Exception:
            return 0.0

    def _media_has_audio_stream(self, file_path):
        """Return True when media contains at least one audio stream."""
        ffprobe_bin = shutil.which('ffprobe')
        if not ffprobe_bin or not file_path or not os.path.exists(file_path):
            return False
        try:
            result = subprocess.run(
                [ffprobe_bin, '-v', 'error', '-select_streams', 'a', '-show_entries', 'stream=codec_type', '-of', 'csv=p=0', file_path],
                capture_output=True,
                text=True,
                check=False,
            )
            return bool((result.stdout or '').strip())
        except Exception:
            return False

    def _release_audio_extract_capture(self):
        """Release OpenCV capture used for audio extract metadata."""
        if self.audio_extract_cap is not None:
            try:
                self.audio_extract_cap.release()
            except Exception:
                pass
            self.audio_extract_cap = None

    def on_audio_extract_browse_video(self):
        """Browse and load a source video for audio extraction."""
        file_path, _ = QFileDialog.getOpenFileName(
            self,
            "Select Source Video",
            "",
            "Video Files (*.mp4 *.mov *.mkv *.m4v *.webm *.avi);;All Files (*)"
        )
        if not file_path:
            return
        self.load_audio_extract_source(file_path)

    def on_audio_extract_video_dropped(self, file_path):
        """Handle drag-dropped video file for audio extraction."""
        if file_path and os.path.exists(file_path):
            self.load_audio_extract_source(file_path)

    def load_audio_extract_source(self, file_path):
        """Load source video metadata and configure preview/trim controls."""
        if not file_path or not os.path.exists(file_path):
            QMessageBox.warning(self, "Audio Tools", "Invalid source video path.")
            return False

        cv2 = self._get_cv2_for_vid_prep()
        if cv2 is None:
            self.audio_extract_status_label.setText("OpenCV not installed. Install opencv-python.")
            return False

        self._release_audio_extract_capture()
        self.audio_extract_source_path = file_path
        self.audio_extract_source_input.setText(file_path)

        cap = cv2.VideoCapture(file_path)
        if not cap or not cap.isOpened():
            QMessageBox.warning(self, "Audio Tools", "Could not open source video.")
            self.audio_extract_status_label.setText("Failed to open source video.")
            return False

        self.audio_extract_cap = cap
        self.audio_extract_frame_count = int(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
        self.audio_extract_fps = float(cap.get(cv2.CAP_PROP_FPS) or 30.0)
        if self.audio_extract_fps <= 0:
            self.audio_extract_fps = 30.0
        self.audio_extract_duration_s = (
            self.audio_extract_frame_count / self.audio_extract_fps
            if self.audio_extract_frame_count > 0 else 0.0
        )

        max_frame = max(0, self.audio_extract_frame_count - 1)
        self.audio_extract_trim_start_frame = 0
        self.audio_extract_trim_end_frame = max_frame
        self.audio_extract_trim_slider.setRange(0, max_frame)
        self.audio_extract_trim_slider.setValues(0, max_frame)
        self.update_audio_extract_trim_label()

        self.audio_extract_player.stop()
        self.audio_extract_player.setMedia(QMediaContent(QUrl.fromLocalFile(file_path)))
        self.audio_extract_position_slider.blockSignals(True)
        self.audio_extract_position_slider.setRange(0, int(self.audio_extract_duration_s * 1000))
        self.audio_extract_position_slider.setValue(0)
        self.audio_extract_position_slider.blockSignals(False)
        self.audio_extract_time_label.setText(
            f"{self._format_vid_prep_time(0.0)} / {self._format_vid_prep_time(self.audio_extract_duration_s)}"
        )
        self.audio_extract_status_label.setText("Source video loaded. Set trim and preview audio.")
        return True

    def _audio_extract_frame_to_seconds(self, frame_idx):
        """Convert frame index to seconds for Extract Audio tab."""
        fps = max(1.0, float(self.audio_extract_fps or 30.0))
        return max(0.0, float(frame_idx) / fps)

    def _audio_extract_end_boundary_seconds(self):
        """Return exclusive end boundary time from end frame."""
        return self._audio_extract_frame_to_seconds(int(self.audio_extract_trim_end_frame) + 1)

    def on_audio_extract_trim_changed(self, start_frame, end_frame):
        """Handle trim range slider changes."""
        self.audio_extract_trim_start_frame = int(start_frame)
        self.audio_extract_trim_end_frame = int(end_frame)
        self.update_audio_extract_trim_label()

    def update_audio_extract_trim_label(self):
        """Refresh human-readable trim range label."""
        start_s = self._audio_extract_frame_to_seconds(self.audio_extract_trim_start_frame)
        end_s = self._audio_extract_frame_to_seconds(self.audio_extract_trim_end_frame)
        self.audio_extract_trim_label.setText(
            f"Trim: {self._format_vid_prep_time(start_s)} -> {self._format_vid_prep_time(end_s)}"
        )

    def step_audio_extract_trim(self, boundary, delta):
        """Adjust trim start/end by frame delta."""
        max_frame = max(0, self.audio_extract_frame_count - 1)
        start = int(self.audio_extract_trim_start_frame)
        end = int(self.audio_extract_trim_end_frame)

        if boundary == 'start':
            start = max(0, min(start + int(delta), end))
        else:
            end = min(max_frame, max(end + int(delta), start))

        self.audio_extract_trim_slider.setValues(start, end)

    def seek_audio_extract_to_start(self):
        """Seek preview player to trim start."""
        position_ms = int(self._audio_extract_frame_to_seconds(self.audio_extract_trim_start_frame) * 1000)
        self.audio_extract_player.setPosition(position_ms)

    def seek_audio_extract_to_end(self):
        """Seek preview player to trim end."""
        end_s = self._audio_extract_end_boundary_seconds()
        position_ms = max(0, int(end_s * 1000) - 1)
        self.audio_extract_player.setPosition(position_ms)

    def play_audio_extract_preview(self):
        """Play video preview constrained to trim range."""
        if not self.audio_extract_source_path:
            QMessageBox.information(self, "Audio Tools", "No source video loaded.")
            return

        start_ms = int(self._audio_extract_frame_to_seconds(self.audio_extract_trim_start_frame) * 1000)
        end_ms = int(self._audio_extract_end_boundary_seconds() * 1000)
        if end_ms <= start_ms:
            QMessageBox.warning(self, "Audio Tools", "Trim range must be greater than zero.")
            return

        current_ms = int(self.audio_extract_player.position())
        if current_ms < start_ms or current_ms >= end_ms:
            self.audio_extract_player.setPosition(start_ms)

        self.audio_extract_player.play()
        self.audio_extract_preview_timer.start()
        self.audio_extract_status_label.setText("Previewing video trim range.")

    def pause_audio_extract_preview(self):
        """Pause audio preview playback."""
        self.audio_extract_player.pause()
        self.audio_extract_preview_timer.stop()
        self.audio_extract_status_label.setText("Video preview paused.")

    def on_audio_extract_repeat_toggled(self, enabled):
        """Toggle repeat mode for audio preview."""
        self.audio_extract_repeat_enabled = bool(enabled)
        self.audio_extract_repeat_btn.setText("Repeat On" if enabled else "Repeat Off")

    def on_audio_extract_position_changed(self, position_ms):
        """Sync position slider/time label from media player updates."""
        position_ms = max(0, int(position_ms))
        if not self.audio_extract_position_slider.isSliderDown():
            self.audio_extract_position_slider.blockSignals(True)
            self.audio_extract_position_slider.setValue(position_ms)
            self.audio_extract_position_slider.blockSignals(False)

        duration_ms = max(0, int(self.audio_extract_position_slider.maximum()))
        self.audio_extract_time_label.setText(
            f"{self._format_vid_prep_time(position_ms / 1000.0)} / {self._format_vid_prep_time(duration_ms / 1000.0)}"
        )

    def on_audio_extract_duration_changed(self, duration_ms):
        """Update position slider range when player duration is known."""
        duration_ms = max(0, int(duration_ms))
        self.audio_extract_position_slider.blockSignals(True)
        self.audio_extract_position_slider.setRange(0, duration_ms)
        self.audio_extract_position_slider.blockSignals(False)

    def seek_audio_extract_preview(self, position_ms):
        """Seek preview player to requested position."""
        self.audio_extract_player.setPosition(int(position_ms))

    def _enforce_audio_extract_trim_boundaries(self):
        """Stop or repeat playback when trim end is reached."""
        if self.audio_extract_player.state() != QMediaPlayer.PlayingState:
            self.audio_extract_preview_timer.stop()
            return

        start_ms = int(self._audio_extract_frame_to_seconds(self.audio_extract_trim_start_frame) * 1000)
        end_ms = int(self._audio_extract_end_boundary_seconds() * 1000)
        current_ms = int(self.audio_extract_player.position())

        if current_ms >= end_ms:
            if self.audio_extract_repeat_enabled:
                self.audio_extract_player.setPosition(start_ms)
                self.audio_extract_player.play()
            else:
                self.audio_extract_player.pause()
                self.audio_extract_player.setPosition(end_ms)
                self.audio_extract_preview_timer.stop()

    def save_extracted_audio(self):
        """Export trimmed audio from current source video using ffmpeg."""
        output_path = self._save_extracted_audio_to_path()
        if output_path:
            self.audio_extract_status_label.setText(f"Saved audio: {output_path}")
            QMessageBox.information(self, "Audio Tools", f"Saved audio:\n{output_path}")

    def save_and_add_extracted_audio_to_music(self):
        """Save extracted audio and add it to the saved music library."""
        output_path = self._save_extracted_audio_to_path()
        if not output_path:
            return

        added = self.add_vid_prep_audio_to_library(output_path, select_added=True)
        self.refresh_vid_prep_audio_library_list(output_path)
        self.audio_extract_status_label.setText(
            f"Saved audio: {output_path}" + (" and added to music." if added else "")
        )
        QMessageBox.information(
            self,
            "Extract Audio",
            f"Saved audio:\n{output_path}\n\n"
            f"{ 'Added to saved music.' if added else 'Audio was already in saved music.' }"
        )

    def save_and_add_extracted_audio_to_effects(self):
        """Save extracted audio and add it to the saved effects library."""
        output_path = self._save_extracted_audio_to_path()
        if not output_path:
            return

        added = self.add_vid_prep_sfx_to_library(output_path, select_added=True)
        self.refresh_vid_prep_sfx_library_list(output_path)
        self.audio_extract_status_label.setText(
            f"Saved audio: {output_path}" + (" and added to effects." if added else "")
        )
        QMessageBox.information(
            self,
            "Audio Tools",
            f"Saved audio:\n{output_path}\n\n"
            f"{ 'Added to sound effects.' if added else 'Audio was already in sound effects.' }"
        )

    def _save_extracted_audio_to_path(self):
        """Run the audio export and return the saved file path on success."""
        if not self.audio_extract_source_path or not os.path.exists(self.audio_extract_source_path):
            QMessageBox.warning(self, "Audio Tools", "Load a source video first.")
            return None

        ffmpeg_bin = shutil.which("ffmpeg")
        if not ffmpeg_bin:
            QMessageBox.warning(self, "Audio Tools", "ffmpeg is not available on PATH.")
            return None

        start_frame = max(0, int(self.audio_extract_trim_start_frame))
        end_frame = max(start_frame, int(self.audio_extract_trim_end_frame))
        start_s = self._audio_extract_frame_to_seconds(start_frame)
        end_s = self._audio_extract_frame_to_seconds(end_frame + 1)
        duration_s = max(0.0, end_s - start_s)
        if duration_s <= 0:
            QMessageBox.warning(self, "Audio Tools", "Trim markers must define a positive range.")
            return None

        audio_format = (self.audio_extract_format_combo.currentText() or 'mp3').strip().lower()
        source_stem = Path(self.audio_extract_source_path).stem
        default_name = f"{source_stem}.audio.{audio_format}"
        output_path, _ = QFileDialog.getSaveFileName(
            self,
            "Save Extracted Audio",
            str(Path(self.audio_extract_source_path).with_name(default_name)),
            "Audio Files (*.mp3 *.m4a *.wav);;All Files (*)"
        )
        if not output_path:
            return None

        output_path = str(Path(output_path))
        cmd = [
            ffmpeg_bin,
            "-y",
            "-ss", f"{start_s:.3f}",
            "-to", f"{end_s:.3f}",
            "-i", self.audio_extract_source_path,
            "-vn",
        ]

        if audio_format == 'wav':
            cmd.extend(["-acodec", "pcm_s16le"]) 
        elif audio_format == 'm4a':
            cmd.extend(["-c:a", "aac", "-b:a", "192k"])
        else:
            cmd.extend(["-acodec", "libmp3lame", "-q:a", "2"])

        cmd.append(output_path)

        try:
            subprocess.run(cmd, check=True, capture_output=True, text=True)
            return output_path
        except subprocess.CalledProcessError as e:
            stderr_text = (e.stderr or '').strip()
            self.audio_extract_status_label.setText("Audio extraction failed.")
            QMessageBox.warning(
                self,
                "Audio Tools",
                f"Failed to extract audio.\n\n{stderr_text or str(e)}"
            )
            return None

    # Transcription methods
    def on_transcription_browse_media(self):
        """Browse and load an audio or video file for transcription."""
        file_path, _ = QFileDialog.getOpenFileName(
            self,
            "Select Audio or Video File",
            "",
            "Media Files (*.mp3 *.wav *.m4a *.aac *.ogg *.flac *.mp4 *.mov *.mkv *.m4v *.webm *.avi);;All Files (*)"
        )
        if not file_path:
            return
        self.load_transcription_source(file_path)

    def on_transcription_media_dropped(self, file_path):
        """Handle drag-dropped media file for transcription."""
        if file_path and os.path.exists(file_path):
            self.load_transcription_source(file_path)

    def load_transcription_source(self, file_path):
        """Load media file for transcription."""
        if not file_path or not os.path.exists(file_path):
            QMessageBox.warning(self, "Audio Tools", "Invalid file path.")
            return False

        self.transcription_source_input.setText(file_path)
        self.transcription_status_label.setText(f"Loaded: {os.path.basename(file_path)}")
        return True

    def start_transcription(self):
        """Start transcribing the loaded media file using Faster-Whisper."""
        source_path = self.transcription_source_input.text()
        if not source_path or not os.path.exists(source_path):
            QMessageBox.warning(self, "Audio Tools", "Please load an audio or video file first.")
            return

        # Check if faster-whisper is available
        try:
            from faster_whisper import WhisperModel
        except ImportError:
            QMessageBox.warning(
                self,
                "Audio Tools",
                "Faster-Whisper is not installed.\n\n"
                "Install it with:\n"
                "pip install faster-whisper"
            )
            return

        # Check if it's a video file that needs audio extraction
        video_extensions = ('.mp4', '.mov', '.avi', '.mkv', '.webm', '.flv', '.wmv', '.m4v')
        is_video = source_path.lower().endswith(video_extensions)
        
        audio_path = source_path
        temp_audio_file = None

        if is_video:
            # Extract audio from video using ffmpeg
            ffmpeg_bin = shutil.which("ffmpeg")
            if not ffmpeg_bin:
                QMessageBox.warning(self, "Audio Tools", "ffmpeg is required to extract audio from video files.")
                return

            self.transcription_status_label.setText("Extracting audio from video...")
            QApplication.processEvents()

            try:
                import tempfile
                temp_audio_file = tempfile.NamedTemporaryFile(suffix='.wav', delete=False)
                audio_path = temp_audio_file.name
                temp_audio_file.close()

                cmd = [
                    ffmpeg_bin,
                    "-i", source_path,
                    "-vn",
                    "-acodec", "pcm_s16le",
                    "-ar", "16000",
                    "-ac", "1",
                    audio_path
                ]
                subprocess.run(cmd, check=True, capture_output=True)
            except subprocess.CalledProcessError as e:
                self.transcription_status_label.setText("Failed to extract audio")
                QMessageBox.warning(
                    self,
                    "Audio Tools",
                    f"Failed to extract audio from video.\n\n{e.stderr.decode() if e.stderr else str(e)}"
                )
                if temp_audio_file and os.path.exists(audio_path):
                    os.remove(audio_path)
                return

        # Run transcription in a separate thread (for now, run in main thread with progress dialog)
        self.transcription_status_label.setText("Transcribing...")
        QApplication.processEvents()

        try:
            # Initialize Whisper model (using base model for speed/quality balance)
            model = WhisperModel("base", device="cpu", compute_type="int8")
            
            # Transcribe
            segments, info = model.transcribe(audio_path, word_timestamps=False)
            
            # Clear existing results
            self.transcription_table.setRowCount(0)
            
            # Add results to table
            for segment in segments:
                row = self.transcription_table.rowCount()
                self.transcription_table.insertRow(row)
                
                # Format time as MM:SS.mmm
                start_time = segment.start
                minutes = int(start_time // 60)
                seconds = start_time % 60
                time_str = f"{minutes:02d}:{seconds:06.3f}"
                
                self.transcription_table.setItem(row, 0, QTableWidgetItem(time_str))
                self.transcription_table.setItem(row, 1, QTableWidgetItem(segment.text.strip()))
            
            self.transcription_status_label.setText(
                f"Transcription complete: {self.transcription_table.rowCount()} segments"
            )
            
        except Exception as e:
            self.transcription_status_label.setText("Transcription failed")
            QMessageBox.warning(
                self,
                "Audio Tools",
                f"Transcription failed:\n\n{str(e)}"
            )
        finally:
            # Clean up temp audio file if created
            if temp_audio_file and os.path.exists(audio_path) and audio_path != source_path:
                try:
                    os.remove(audio_path)
                except:
                    pass

    def copy_transcription(self, include_timestamps=True):
        """Copy transcription text to clipboard with or without timestamps."""
        if self.transcription_table.rowCount() == 0:
            QMessageBox.information(self, "Audio Tools", "No transcription available to copy.")
            return

        lines = []
        for row in range(self.transcription_table.rowCount()):
            time_item = self.transcription_table.item(row, 0)
            text_item = self.transcription_table.item(row, 1)
            
            if include_timestamps:
                lines.append(f"[{time_item.text()}] {text_item.text()}")
            else:
                lines.append(text_item.text())

        text = "\n".join(lines)
        clipboard = QApplication.clipboard()
        clipboard.setText(text)
        
        self.transcription_status_label.setText(
            f"Copied {len(lines)} segments to clipboard"
        )

    def save_transcription(self):
        """Save transcription to a text file."""
        if self.transcription_table.rowCount() == 0:
            QMessageBox.information(self, "Audio Tools", "No transcription available to save.")
            return

        # Get last used folder from settings
        last_folder = self.account_manager.get_setting('transcription_last_save_folder', '')
        if not last_folder or not os.path.exists(last_folder):
            source_path = self.transcription_source_input.text()
            if source_path and os.path.exists(source_path):
                last_folder = str(Path(source_path).parent)
            else:
                last_folder = str(Path.home())

        # Generate default filename based on source
        source_path = self.transcription_source_input.text()
        if source_path:
            source_stem = Path(source_path).stem
            default_name = f"{source_stem}.transcription.txt"
        else:
            default_name = "transcription.txt"

        output_path, _ = QFileDialog.getSaveFileName(
            self,
            "Save Transcription",
            str(Path(last_folder) / default_name),
            "Text Files (*.txt);;All Files (*)"
        )
        
        if not output_path:
            return

        try:
            lines = []
            for row in range(self.transcription_table.rowCount()):
                time_item = self.transcription_table.item(row, 0)
                text_item = self.transcription_table.item(row, 1)
                lines.append(f"[{time_item.text()}] {text_item.text()}")

            with open(output_path, 'w', encoding='utf-8') as f:
                f.write("\n".join(lines))

            # Save the folder for next time
            self.account_manager.set_setting('transcription_last_save_folder', str(Path(output_path).parent))

            self.transcription_status_label.setText(f"Saved: {output_path}")
            QMessageBox.information(
                self,
                "Audio Tools",
                f"Transcription saved to:\n{output_path}"
            )
        except Exception as e:
            QMessageBox.warning(
                self,
                "Audio Tools",
                f"Failed to save transcription:\n\n{str(e)}"
            )

    def on_vid_prep_audio_setting_changed(self, *args):
        """Persist audio replacement inputs and mark the preview stale."""
        self._save_vid_prep_ui_settings()
        self._set_vid_prep_output_preview_dirty(True)

    def _load_vid_prep_audio_library_setting(self):
        """Load the saved music list from global settings."""
        raw_value = self.account_manager.get_setting('vid_prep_audio_library', '[]')
        try:
            parsed = json.loads(raw_value)
        except Exception:
            logger.warning("Failed to parse vid_prep_audio_library setting; resetting to empty list")
            return []

        if not isinstance(parsed, list):
            return []

        normalized_paths = []
        seen_paths = set()
        for value in parsed:
            normalized = self._normalize_vid_prep_audio_path(value)
            if not normalized:
                continue
            compare_value = os.path.normcase(normalized)
            if compare_value in seen_paths:
                continue
            seen_paths.add(compare_value)
            normalized_paths.append(normalized)
        return normalized_paths

    def _load_vid_prep_sfx_library_setting(self):
        """Load the saved sound effects list from global settings."""
        raw_value = self.account_manager.get_setting('vid_prep_sfx_library', '[]')
        try:
            parsed = json.loads(raw_value)
        except Exception:
            logger.warning("Failed to parse vid_prep_sfx_library setting; resetting to empty list")
            return []

        if not isinstance(parsed, list):
            return []

        normalized_paths = []
        seen_paths = set()
        for value in parsed:
            normalized = self._normalize_vid_prep_audio_path(value)
            if not normalized:
                continue
            compare_value = os.path.normcase(normalized)
            if compare_value in seen_paths:
                continue
            seen_paths.add(compare_value)
            normalized_paths.append(normalized)
        return normalized_paths

    def _save_vid_prep_audio_library_setting(self):
        """Persist the saved music list in global settings."""
        self.account_manager.set_setting('vid_prep_audio_library', json.dumps(self.vid_prep_audio_library))

    def _save_vid_prep_sfx_library_setting(self):
        """Persist the saved sound effects list in global settings."""
        self.account_manager.set_setting('vid_prep_sfx_library', json.dumps(self.vid_prep_sfx_library))

    def _normalize_vid_prep_audio_path(self, file_path):
        """Normalize saved music paths for stable storage and comparison."""
        if not file_path:
            return ''
        return os.path.normpath(str(file_path).strip())

    def refresh_vid_prep_audio_library_list(self, selected_path=None):
        """Rebuild the saved music list widget from persisted state."""
        if not hasattr(self, 'vid_prep_audio_library_list'):
            return

        normalized_selected = self._normalize_vid_prep_audio_path(selected_path or self.vid_prep_selected_audio_path)
        selected_row = -1
        self.vid_prep_audio_library_list.clear()

        for index, file_path in enumerate(self.vid_prep_audio_library):
            display_name = os.path.basename(file_path) or file_path
            if not os.path.exists(file_path):
                display_name = f"{display_name} (missing)"
            item = QListWidgetItem(display_name)
            item.setData(Qt.UserRole, file_path)
            item.setToolTip(file_path)
            self.vid_prep_audio_library_list.addItem(item)
            if os.path.normcase(file_path) == os.path.normcase(normalized_selected):
                selected_row = index

        if selected_row >= 0:
            self.vid_prep_audio_library_list.setCurrentRow(selected_row)

        self._update_vid_prep_audio_library_buttons()
        self._refresh_framevid_library_lists_from_vid_prep()

    def _get_selected_vid_prep_audio_path(self):
        """Return the currently selected saved music path."""
        if not hasattr(self, 'vid_prep_audio_library_list'):
            return ''
        current_item = self.vid_prep_audio_library_list.currentItem()
        if not current_item:
            return ''
        return self._normalize_vid_prep_audio_path(current_item.data(Qt.UserRole))

    def _update_vid_prep_audio_library_buttons(self):
        """Keep saved music actions in sync with the current selection and mode."""
        use_mp3 = self.vid_prep_audio_replace_radio.isChecked() or self.vid_prep_audio_mix_radio.isChecked()
        has_selection = bool(self._get_selected_vid_prep_audio_path())
        self.vid_prep_audio_library_use_btn.setEnabled(use_mp3 and has_selection)
        self.vid_prep_audio_library_remove_btn.setEnabled(use_mp3 and has_selection)
        self.vid_prep_audio_library_preview_btn.setEnabled(has_selection)

        if not has_selection and hasattr(self, 'vid_prep_music_preview_player'):
            self.vid_prep_music_preview_player.stop()
            self.vid_prep_preview_audio_path = ''

    def refresh_vid_prep_sfx_library_list(self, selected_path=None):
        """Rebuild the saved sound effects list widget from persisted state."""
        if not hasattr(self, 'vid_prep_sfx_library_list'):
            return

        normalized_selected = self._normalize_vid_prep_audio_path(selected_path or self.vid_prep_selected_audio_path)
        selected_row = -1
        self.vid_prep_sfx_library_list.clear()

        for index, file_path in enumerate(self.vid_prep_sfx_library):
            display_name = os.path.basename(file_path) or file_path
            if not os.path.exists(file_path):
                display_name = f"{display_name} (missing)"
            item = QListWidgetItem(display_name)
            item.setData(Qt.UserRole, file_path)
            item.setToolTip(file_path)
            self.vid_prep_sfx_library_list.addItem(item)
            if os.path.normcase(file_path) == os.path.normcase(normalized_selected):
                selected_row = index

        if selected_row >= 0:
            self.vid_prep_sfx_library_list.setCurrentRow(selected_row)

        self._update_vid_prep_sfx_library_buttons()
        self._refresh_framevid_library_lists_from_vid_prep()

    def _get_selected_vid_prep_sfx_path(self):
        """Return the currently selected sound effects path."""
        if not hasattr(self, 'vid_prep_sfx_library_list'):
            return ''
        current_item = self.vid_prep_sfx_library_list.currentItem()
        if not current_item:
            return ''
        return self._normalize_vid_prep_audio_path(current_item.data(Qt.UserRole))

    def _update_vid_prep_sfx_library_buttons(self):
        """Keep sound effects actions in sync with the current selection and mode."""
        use_mp3 = self.vid_prep_audio_replace_radio.isChecked() or self.vid_prep_audio_mix_radio.isChecked()
        has_selection = bool(self._get_selected_vid_prep_sfx_path())
        self.vid_prep_sfx_library_use_btn.setEnabled(use_mp3 and has_selection)
        self.vid_prep_sfx_library_remove_btn.setEnabled(use_mp3 and has_selection)
        self.vid_prep_sfx_library_preview_btn.setEnabled(has_selection)

        if not has_selection and hasattr(self, 'vid_prep_music_preview_player'):
            self.vid_prep_music_preview_player.stop()
            self.vid_prep_preview_audio_path = ''

    def on_vid_prep_audio_library_selection_changed(self, current, previous):
        """Refresh button state when the saved music selection changes."""
        self._update_vid_prep_audio_library_buttons()

    def on_vid_prep_sfx_library_selection_changed(self, current, previous):
        """Refresh button state when the sound effects selection changes."""
        self._update_vid_prep_sfx_library_buttons()

    def on_vid_prep_music_preview_state_changed(self, state):
        """Update Preview button label based on current playback state."""
        if not hasattr(self, 'vid_prep_audio_library_preview_btn'):
            return

        if state == QMediaPlayer.PlayingState:
            if hasattr(self, 'vid_prep_audio_library_preview_btn'):
                self.vid_prep_audio_library_preview_btn.setText("⏹ Stop")
            if hasattr(self, 'vid_prep_sfx_library_preview_btn'):
                self.vid_prep_sfx_library_preview_btn.setText("⏹ Stop")
        else:
            if hasattr(self, 'vid_prep_audio_library_preview_btn'):
                self.vid_prep_audio_library_preview_btn.setText("▶ Preview")
            if hasattr(self, 'vid_prep_sfx_library_preview_btn'):
                self.vid_prep_sfx_library_preview_btn.setText("▶ Preview")

    def preview_selected_vid_prep_audio(self):
        """Preview/stop the currently selected saved music file."""
        selected_path = self._get_selected_vid_prep_audio_path()
        if not selected_path:
            return

        if not os.path.exists(selected_path):
            QMessageBox.warning(self, "Vid Prep", "Selected music file does not exist on disk.")
            return

        current_state = self.vid_prep_music_preview_player.state()
        if (
            current_state == QMediaPlayer.PlayingState
            and os.path.normcase(self.vid_prep_preview_audio_path) == os.path.normcase(selected_path)
        ):
            self.vid_prep_music_preview_player.stop()
            self.vid_prep_preview_audio_path = ''
            return

        self.vid_prep_music_preview_player.stop()
        self.vid_prep_preview_audio_path = selected_path
        self.vid_prep_music_preview_player.setMedia(QMediaContent(QUrl.fromLocalFile(selected_path)))
        self.vid_prep_music_preview_player.play()

    def add_vid_prep_audio_to_library(self, file_path, select_added=False):
        """Add a music file to the persistent saved list if it is not already present."""
        normalized = self._normalize_vid_prep_audio_path(file_path)
        if not normalized:
            return False

        compare_value = os.path.normcase(normalized)
        if any(os.path.normcase(existing_path) == compare_value for existing_path in self.vid_prep_audio_library):
            if select_added:
                self.refresh_vid_prep_audio_library_list(normalized)
            return False

        self.vid_prep_audio_library.append(normalized)
        self._save_vid_prep_audio_library_setting()
        self.refresh_vid_prep_audio_library_list(normalized if select_added else None)
        return True

    def add_vid_prep_audio_files(self):
        """Browse for one or more music files to save for reuse."""
        file_paths, _ = QFileDialog.getOpenFileNames(
            self,
            "Add Saved Music",
            "",
            "Audio Files (*.mp3 *.wav *.m4a *.aac *.flac *.ogg);;All Files (*)"
        )
        last_added = ''
        for file_path in file_paths:
            normalized = self._normalize_vid_prep_audio_path(file_path)
            if not normalized:
                continue
            self.add_vid_prep_audio_to_library(normalized)
            last_added = normalized

        if last_added:
            self.refresh_vid_prep_audio_library_list(last_added)

    def on_vid_prep_audio_files_dropped(self, file_paths):
        """Handle MP3 files dropped onto the saved music list."""
        if not file_paths:
            return

        last_added = ''
        added_count = 0
        for file_path in file_paths:
            normalized = self._normalize_vid_prep_audio_path(file_path)
            if not normalized or not os.path.exists(normalized):
                continue
            if self.add_vid_prep_audio_to_library(normalized):
                last_added = normalized
                added_count += 1

        if last_added:
            self.refresh_vid_prep_audio_library_list(last_added)

        if hasattr(self, 'vid_prep_status'):
            if added_count > 0:
                self.vid_prep_status.setText(f"Added {added_count} MP3 file(s) to saved music.")
            else:
                self.vid_prep_status.setText("No new MP3 files were added (already present or invalid).")

    def use_selected_vid_prep_audio(self):
        """Apply the selected saved music item to the current export."""
        selected_path = self._get_selected_vid_prep_audio_path()
        if not selected_path:
            return

        self.vid_prep_selected_audio_path = selected_path
        self.on_vid_prep_audio_tracks_dropped([selected_path])
        self.vid_prep_audio_replace_radio.setChecked(True)
        self.refresh_vid_prep_audio_library_list(selected_path)
        self.on_vid_prep_audio_setting_changed()

    def remove_selected_vid_prep_audio(self):
        """Remove the selected saved music item from persistent storage."""
        selected_path = self._get_selected_vid_prep_audio_path()
        if not selected_path:
            return

        compare_value = os.path.normcase(selected_path)
        self.vid_prep_audio_library = [
            existing_path for existing_path in self.vid_prep_audio_library
            if os.path.normcase(existing_path) != compare_value
        ]
        self._save_vid_prep_audio_library_setting()
        self.refresh_vid_prep_audio_library_list()

    def preview_selected_vid_prep_sfx(self):
        """Preview/stop the currently selected sound effects file."""
        selected_path = self._get_selected_vid_prep_sfx_path()
        if not selected_path:
            return

        if not os.path.exists(selected_path):
            QMessageBox.warning(self, "Vid Prep", "Selected sound effect file does not exist on disk.")
            return

        current_state = self.vid_prep_music_preview_player.state()
        if (
            current_state == QMediaPlayer.PlayingState
            and os.path.normcase(self.vid_prep_preview_audio_path) == os.path.normcase(selected_path)
        ):
            self.vid_prep_music_preview_player.stop()
            self.vid_prep_preview_audio_path = ''
            return

        self.vid_prep_music_preview_player.stop()
        self.vid_prep_preview_audio_path = selected_path
        self.vid_prep_music_preview_player.setMedia(QMediaContent(QUrl.fromLocalFile(selected_path)))
        self.vid_prep_music_preview_player.play()

    def add_vid_prep_sfx_to_library(self, file_path, select_added=False):
        """Add a sound effect file to the persistent saved list if it is not already present."""
        normalized = self._normalize_vid_prep_audio_path(file_path)
        if not normalized:
            return False

        compare_value = os.path.normcase(normalized)
        if any(os.path.normcase(existing_path) == compare_value for existing_path in self.vid_prep_sfx_library):
            if select_added:
                self.refresh_vid_prep_sfx_library_list(normalized)
            return False

        self.vid_prep_sfx_library.append(normalized)
        self._save_vid_prep_sfx_library_setting()
        self.refresh_vid_prep_sfx_library_list(normalized if select_added else None)
        return True

    def add_vid_prep_sfx_files(self):
        """Browse for one or more sound effect files to save for reuse."""
        file_paths, _ = QFileDialog.getOpenFileNames(
            self,
            "Add Sound Effects",
            "",
            "Audio Files (*.mp3 *.wav *.m4a *.aac *.flac *.ogg);;All Files (*)"
        )
        last_added = ''
        for file_path in file_paths:
            normalized = self._normalize_vid_prep_audio_path(file_path)
            if not normalized:
                continue
            self.add_vid_prep_sfx_to_library(normalized)
            last_added = normalized

        if last_added:
            self.refresh_vid_prep_sfx_library_list(last_added)

    def on_vid_prep_sfx_files_dropped(self, file_paths):
        """Handle files dropped onto the sound effects list."""
        if not file_paths:
            return

        last_added = ''
        added_count = 0
        for file_path in file_paths:
            normalized = self._normalize_vid_prep_audio_path(file_path)
            if not normalized or not os.path.exists(normalized):
                continue
            if self.add_vid_prep_sfx_to_library(normalized):
                last_added = normalized
                added_count += 1

        if last_added:
            self.refresh_vid_prep_sfx_library_list(last_added)

        if hasattr(self, 'vid_prep_status'):
            if added_count > 0:
                self.vid_prep_status.setText(f"Added {added_count} file(s) to sound effects.")
            else:
                self.vid_prep_status.setText("No new sound effect files were added (already present or invalid).")

    def use_selected_vid_prep_sfx(self):
        """Apply the selected sound effect item to the current export audio file path."""
        selected_path = self._get_selected_vid_prep_sfx_path()
        if not selected_path:
            return

        self.vid_prep_selected_audio_path = selected_path
        self.on_vid_prep_audio_tracks_dropped([selected_path])
        self.vid_prep_audio_replace_radio.setChecked(True)
        self.refresh_vid_prep_sfx_library_list(selected_path)
        self.on_vid_prep_audio_setting_changed()

    def remove_selected_vid_prep_sfx(self):
        """Remove the selected saved sound effect from persistent storage."""
        selected_path = self._get_selected_vid_prep_sfx_path()
        if not selected_path:
            return

        compare_value = os.path.normcase(selected_path)
        self.vid_prep_sfx_library = [
            existing_path for existing_path in self.vid_prep_sfx_library
            if os.path.normcase(existing_path) != compare_value
        ]
        self._save_vid_prep_sfx_library_setting()
        self.refresh_vid_prep_sfx_library_list()

    def _create_vid_prep_audio_track(self, file_path):
        """Create a new in-memory track record with default settings."""
        normalized = self._normalize_vid_prep_audio_path(file_path)
        if not normalized:
            return None

        track_duration_s = max(0.0, float(self._get_vid_prep_audio_duration_seconds(normalized)))
        end_frame = 0
        if track_duration_s > 0 and float(self.vid_prep_fps or 0.0) > 0:
            end_frame = int(round(track_duration_s * float(self.vid_prep_fps)))

        if int(self.vid_prep_frame_count or 0) > 0:
            # Track timeline placement defaults to full video span.
            # Audio clip length is handled independently via clip start/end values.
            max_frame = max(0, int(self.vid_prep_frame_count) - 1)
            end_frame = max_frame

        track = {
            'track_id': int(self.vid_prep_next_audio_track_id),
            'track_path': normalized,
            'track_name': os.path.basename(normalized) or normalized,
            'volume_percent': 100.0,
            'clip_start_seconds': 0.0,
            'clip_end_seconds': float(track_duration_s),
            'enter_frame': 0,
            'exit_frame': int(end_frame),
            'fade_in_seconds': 0.0,
            'fade_out_seconds': 0.0,
            'muted': False,
        }
        self.vid_prep_next_audio_track_id += 1
        return track

    def _sync_vid_prep_track_windows_to_video_length(self):
        """Clamp existing track timeline windows to current source video length."""
        if int(self.vid_prep_frame_count or 0) <= 0:
            return

        max_frame = max(0, int(self.vid_prep_frame_count) - 1)
        for track in self.vid_prep_audio_tracks:
            enter_frame = int(track.get('enter_frame') or 0)
            enter_frame = max(0, min(enter_frame, max_frame))
            track['enter_frame'] = enter_frame
            # New source video should define default track placement window.
            track['exit_frame'] = max(enter_frame, max_frame)

    def _get_vid_prep_audio_duration_seconds(self, file_path):
        """Best-effort duration probe for an audio file in seconds."""
        normalized = self._normalize_vid_prep_audio_path(file_path)
        if not normalized or not os.path.exists(normalized):
            return 0.0

        ffprobe_bin = shutil.which("ffprobe")
        if ffprobe_bin:
            try:
                result = subprocess.run(
                    [
                        ffprobe_bin,
                        "-v", "error",
                        "-show_entries", "format=duration",
                        "-of", "default=noprint_wrappers=1:nokey=1",
                        normalized,
                    ],
                    capture_output=True,
                    text=True,
                    check=False,
                )
                if result.returncode == 0:
                    parsed = float((result.stdout or "").strip() or 0.0)
                    if parsed > 0:
                        return parsed
            except Exception:
                pass

        # Wave fallback supports uncompressed WAV files without external tools.
        if str(normalized).lower().endswith('.wav'):
            try:
                with wave.open(normalized, 'rb') as wav_file:
                    frames = wav_file.getnframes()
                    frame_rate = wav_file.getframerate()
                if frame_rate > 0:
                    return float(frames) / float(frame_rate)
            except Exception:
                pass

        return 0.0

    def _get_vid_prep_audio_track_by_id(self, track_id):
        """Return a track record by track_id."""
        for track in self.vid_prep_audio_tracks:
            if int(track.get('track_id', -1)) == int(track_id):
                return track
        return None

    def _selected_vid_prep_audio_track_id(self):
        """Return currently selected track_id or None."""
        if not hasattr(self, 'vid_prep_audio_track_list'):
            return None

        table = self.vid_prep_audio_track_list
        current_row = int(table.currentRow())
        if current_row < 0 and table.selectionModel() is not None:
            selected_rows = table.selectionModel().selectedRows()
            if selected_rows:
                current_row = int(selected_rows[0].row())

        if current_row < 0:
            return None

        # Column 0 is a QWidget (move controls). Track ID is stored on the file-name item in column 1.
        track_item = table.item(current_row, 1)
        if track_item is None:
            return None

        track_id = track_item.data(Qt.UserRole)
        try:
            return int(track_id)
        except Exception:
            return None

    def _selected_vid_prep_audio_track_row(self):
        """Return currently selected track row index or -1."""
        if not hasattr(self, 'vid_prep_audio_track_list'):
            return -1

        table = self.vid_prep_audio_track_list
        current_row = int(table.currentRow())
        if current_row >= 0:
            return current_row

        if table.selectionModel() is not None:
            selected_rows = table.selectionModel().selectedRows()
            if selected_rows:
                return int(selected_rows[0].row())

        return -1

    def _vid_prep_track_position_bounds(self):
        """Return timeline range for track placement sliders."""
        max_frame = max(0, int(self.vid_prep_frame_count or 0) - 1)
        for track in self.vid_prep_audio_tracks:
            try:
                max_frame = max(max_frame, int(track.get('exit_frame') or 0))
            except Exception:
                continue
        return 0, max(1, max_frame)

    def _move_vid_prep_track(self, track_id, delta):
        """Move a track up or down in the in-memory ordering."""
        try:
            track_id = int(track_id)
            delta = int(delta)
        except Exception:
            return

        index = next((i for i, track in enumerate(self.vid_prep_audio_tracks) if int(track.get('track_id', -1)) == track_id), None)
        if index is None:
            return

        target_index = index + delta
        if target_index < 0 or target_index >= len(self.vid_prep_audio_tracks):
            return

        self.vid_prep_audio_tracks[index], self.vid_prep_audio_tracks[target_index] = self.vid_prep_audio_tracks[target_index], self.vid_prep_audio_tracks[index]
        self._refresh_vid_prep_audio_track_list(track_id)
        self._set_vid_prep_output_preview_dirty(True)

    def _remove_vid_prep_track_by_id(self, track_id):
        """Remove a track by ID from the in-memory ordering."""
        try:
            track_id = int(track_id)
        except Exception:
            return

        original_len = len(self.vid_prep_audio_tracks)
        self.vid_prep_audio_tracks = [
            track for track in self.vid_prep_audio_tracks
            if int(track.get('track_id', -1)) != track_id
        ]
        if len(self.vid_prep_audio_tracks) == original_len:
            return

        self._refresh_vid_prep_audio_track_list()
        self._set_vid_prep_output_preview_dirty(True)

    def _apply_vid_prep_track_position(self, track_id, start_frame, end_frame):
        """Update a track's timeline placement from the slider widget."""
        track = self._get_vid_prep_audio_track_by_id(track_id)
        if not track:
            return

        start_frame = int(start_frame)
        end_frame = int(end_frame)
        if start_frame > end_frame:
            start_frame, end_frame = end_frame, start_frame

        track['enter_frame'] = start_frame
        track['exit_frame'] = end_frame
        self._set_vid_prep_output_preview_dirty(True)

    def _refresh_vid_prep_audio_track_list(self, selected_track_id=None):
        """Repaint the track table from model state."""
        if not hasattr(self, 'vid_prep_audio_track_list'):
            return

        if selected_track_id is None:
            selected_track_id = self._selected_vid_prep_audio_track_id()

        table = self.vid_prep_audio_track_list
        table.blockSignals(True)
        table.setRowCount(len(self.vid_prep_audio_tracks))
        min_frame, max_frame = self._vid_prep_track_position_bounds()

        for row_index, track in enumerate(self.vid_prep_audio_tracks):
            track_id = int(track.get('track_id', 0))
            track_name = track.get('track_name') or os.path.basename(track.get('track_path') or '') or 'Track'

            number_widget = QWidget()
            number_layout = QHBoxLayout(number_widget)
            number_layout.setContentsMargins(0, 0, 0, 0)
            number_layout.setSpacing(2)

            up_btn = QPushButton("▲")
            up_btn.setFixedWidth(22)
            up_btn.setToolTip("Move track up")
            up_btn.clicked.connect(lambda _checked=False, tid=track_id: self._move_vid_prep_track(tid, -1))
            number_layout.addWidget(up_btn)

            down_btn = QPushButton("▼")
            down_btn.setFixedWidth(22)
            down_btn.setToolTip("Move track down")
            down_btn.clicked.connect(lambda _checked=False, tid=track_id: self._move_vid_prep_track(tid, 1))
            number_layout.addWidget(down_btn)

            row_label = QLabel(f"{row_index + 1}")
            row_label.setAlignment(Qt.AlignCenter)
            row_label.setMinimumWidth(18)
            number_layout.addWidget(row_label)
            number_layout.addStretch()
            table.setCellWidget(row_index, 0, number_widget)

            file_item = QTableWidgetItem(track_name)
            file_item.setData(Qt.UserRole, track_id)
            file_item.setToolTip(track.get('track_path') or '')
            table.setItem(row_index, 1, file_item)

            position_widget = QWidget()
            position_layout = QVBoxLayout(position_widget)
            position_layout.setContentsMargins(0, 0, 0, 0)
            position_layout.setSpacing(2)

            slider = TrackPositionSlider()
            slider.setRange(min_frame, max_frame)
            slider.setValues(int(track.get('enter_frame') or 0), int(track.get('exit_frame') or 0))
            slider.activated.connect(lambda tid=track_id, row=row_index: self.vid_prep_audio_track_list.setCurrentCell(row, 1))
            slider.range_changed.connect(lambda start, end, tid=track_id: self._apply_vid_prep_track_position(tid, start, end))
            position_layout.addWidget(slider)

            position_hint = QLabel(f"{int(track.get('enter_frame') or 0)} -> {int(track.get('exit_frame') or 0)}")
            position_hint.setAlignment(Qt.AlignCenter)
            position_hint.setStyleSheet("font-size: 8pt; color: #888;")
            position_layout.addWidget(position_hint)
            table.setCellWidget(row_index, 2, position_widget)

            mute_btn = QPushButton("Unmute" if bool(track.get('muted')) else "Mute")
            mute_btn.setCheckable(True)
            mute_btn.setChecked(bool(track.get('muted')))
            mute_btn.setFixedWidth(64)
            mute_btn.setToolTip("Mute this track so it will be skipped during export" if not bool(track.get('muted')) else "Unmute this track so it will be included during export")
            mute_btn.setStyleSheet("QPushButton { background-color: #6c757d; color: white; font-weight: bold; padding: 0px 4px; font-size: 7pt; }")
            mute_btn.toggled.connect(lambda muted, tid=track_id, button=mute_btn: self._set_vid_prep_audio_track_muted(tid, muted, button))
            mute_widget = QWidget()
            mute_layout = QHBoxLayout(mute_widget)
            mute_layout.setContentsMargins(0, 0, 0, 0)
            mute_layout.setAlignment(Qt.AlignCenter)
            mute_layout.addWidget(mute_btn)
            table.setCellWidget(row_index, 3, mute_widget)

            delete_btn = QPushButton("X")
            delete_btn.setFixedWidth(22)
            delete_btn.setToolTip("Delete this track")
            delete_btn.clicked.connect(lambda _checked=False, tid=track_id: self._remove_vid_prep_track_by_id(tid))

            delete_widget = QWidget()
            delete_layout = QHBoxLayout(delete_widget)
            delete_layout.setContentsMargins(0, 0, 0, 0)
            delete_layout.setAlignment(Qt.AlignCenter)
            delete_layout.addWidget(delete_btn)
            table.setCellWidget(row_index, 4, delete_widget)

            if selected_track_id is not None and track_id == int(selected_track_id):
                table.selectRow(row_index)

            table.setRowHeight(row_index, 42)

        table.blockSignals(False)

        has_tracks = bool(self.vid_prep_audio_tracks)
        self.vid_prep_audio_track_remove_btn.setEnabled(has_tracks and self._selected_vid_prep_audio_track_id() is not None)
        self.vid_prep_audio_track_clear_btn.setEnabled(has_tracks)
        self._set_vid_prep_audio_track_editor_enabled(self._selected_vid_prep_audio_track_id() is not None)

    def _set_vid_prep_audio_track_editor_enabled(self, enabled):
        """Enable/disable per-track editor controls."""
        controls = [
            'vid_prep_track_volume_spin',
            'vid_prep_track_clip_start_spin',
            'vid_prep_track_clip_end_spin',
            'vid_prep_track_enter_frame_spin',
            'vid_prep_track_exit_frame_spin',
            'vid_prep_track_fade_in_spin',
            'vid_prep_track_fade_out_spin',
        ]
        for control_name in controls:
            if hasattr(self, control_name):
                getattr(self, control_name).setEnabled(bool(enabled))

    def add_vid_prep_audio_tracks(self):
        """Pick and append tracks to the audio track editor."""
        file_paths, _ = QFileDialog.getOpenFileNames(
            self,
            "Add Audio Tracks",
            "",
            "Audio Files (*.mp3 *.wav *.m4a *.aac *.flac *.ogg);;All Files (*)"
        )
        self.on_vid_prep_audio_tracks_dropped(file_paths)

    def on_vid_prep_audio_tracks_dropped(self, file_paths):
        """Handle dropped track files."""
        if not file_paths:
            return

        added_count = 0
        selected_track_id = None
        for file_path in file_paths:
            normalized = self._normalize_vid_prep_audio_path(file_path)
            if not normalized or not os.path.exists(normalized):
                continue
            track = self._create_vid_prep_audio_track(normalized)
            if not track:
                continue
            self.vid_prep_audio_tracks.append(track)
            selected_track_id = track['track_id']
            added_count += 1

        if added_count > 0:
            self._refresh_vid_prep_audio_track_list(selected_track_id)
            self._set_vid_prep_output_preview_dirty(True)
            self.vid_prep_status.setText(f"Added {added_count} audio track(s) to track editor.")

    def on_vid_prep_audio_track_selection_changed(self, *args):
        """Load selected track values into the per-track editor controls."""
        track_id = self._selected_vid_prep_audio_track_id()
        track = self._get_vid_prep_audio_track_by_id(track_id) if track_id is not None else None
        self.vid_prep_audio_track_remove_btn.setEnabled(track is not None)

        self._vid_prep_audio_track_editor_updating = True
        try:
            if not track:
                self._set_vid_prep_audio_track_editor_enabled(False)
                return

            self._set_vid_prep_audio_track_editor_enabled(True)
            self.vid_prep_track_volume_spin.setValue(float(track.get('volume_percent') or 100.0))
            self.vid_prep_track_clip_start_spin.setValue(float(track.get('clip_start_seconds') or 0.0))
            self.vid_prep_track_clip_end_spin.setValue(float(track.get('clip_end_seconds') or 0.0))
            self.vid_prep_track_enter_frame_spin.setValue(int(track.get('enter_frame') or 0))
            self.vid_prep_track_exit_frame_spin.setValue(int(track.get('exit_frame') or 0))
            self.vid_prep_track_fade_in_spin.setValue(float(track.get('fade_in_seconds') or 0.0))
            self.vid_prep_track_fade_out_spin.setValue(float(track.get('fade_out_seconds') or 0.0))
        finally:
            self._vid_prep_audio_track_editor_updating = False

    def on_vid_prep_audio_track_editor_changed(self, *args):
        """Apply per-track editor values to selected track model."""
        if self._vid_prep_audio_track_editor_updating:
            return

        track_id = self._selected_vid_prep_audio_track_id()
        track = self._get_vid_prep_audio_track_by_id(track_id) if track_id is not None else None
        if not track:
            return

        track['volume_percent'] = float(self.vid_prep_track_volume_spin.value())
        track['clip_start_seconds'] = float(self.vid_prep_track_clip_start_spin.value())
        track['clip_end_seconds'] = float(self.vid_prep_track_clip_end_spin.value())
        track['enter_frame'] = int(self.vid_prep_track_enter_frame_spin.value())
        track['exit_frame'] = int(self.vid_prep_track_exit_frame_spin.value())
        track['fade_in_seconds'] = float(self.vid_prep_track_fade_in_spin.value())
        track['fade_out_seconds'] = float(self.vid_prep_track_fade_out_spin.value())
        self._set_vid_prep_output_preview_dirty(True)

    def _set_vid_prep_audio_track_muted(self, track_id, muted, button=None):
        """Set muted state for a Vid Prep audio track."""
        track = self._get_vid_prep_audio_track_by_id(track_id)
        if not track:
            return

        track['muted'] = bool(muted)
        if button is not None:
            button.blockSignals(True)
            button.setText("Unmute" if muted else "Mute")
            button.setToolTip("Unmute this track so it will be included during export" if muted else "Mute this track so it will be skipped during export")
            button.blockSignals(False)

        self._set_vid_prep_output_preview_dirty(True)
        self.vid_prep_status.setText(f"Track {'muted' if muted else 'unmuted'} for export.")

    def remove_selected_vid_prep_audio_track(self):
        """Remove currently selected track from track editor."""
        track_id = self._selected_vid_prep_audio_track_id()
        if track_id is None:
            return

        self.vid_prep_audio_tracks = [
            track for track in self.vid_prep_audio_tracks
            if int(track.get('track_id', -1)) != int(track_id)
        ]
        self._refresh_vid_prep_audio_track_list()
        self._set_vid_prep_output_preview_dirty(True)

    def clear_vid_prep_audio_tracks(self):
        """Remove all tracks from track editor."""
        if not self.vid_prep_audio_tracks:
            return

        self.vid_prep_audio_tracks = []
        self._refresh_vid_prep_audio_track_list()
        self._set_vid_prep_output_preview_dirty(True)

    def _current_vid_prep_audio_mode(self):
        """Return canonical audio mode token."""
        if self.vid_prep_audio_replace_radio.isChecked():
            return 'replace'
        if self.vid_prep_audio_maintain_radio.isChecked():
            return 'maintain'
        if self.vid_prep_audio_mix_radio.isChecked():
            return 'mix'
        return 'remove'

    def _build_vid_prep_audio_track_payload(self):
        """Build DB payload rows for VIDEO.AudioTracks."""
        payload = []
        for idx, track in enumerate(self.vid_prep_audio_tracks, start=1):
            payload.append({
                'track_order': idx,
                'track_path': track.get('track_path'),
                'track_name': track.get('track_name'),
                'volume_percent': float(track.get('volume_percent') or 0.0),
                'clip_start_seconds': float(track.get('clip_start_seconds') or 0.0),
                'clip_end_seconds': float(track.get('clip_end_seconds') or 0.0),
                'enter_frame': int(track.get('enter_frame') or 0),
                'exit_frame': int(track.get('exit_frame') or 0),
                'fade_in_seconds': float(track.get('fade_in_seconds') or 0.0),
                'fade_out_seconds': float(track.get('fade_out_seconds') or 0.0),
                'muted': bool(track.get('muted')),
            })
        return payload

    def _get_vid_prep_primary_audio_path(self):
        """Return the preferred music path for metadata persistence."""
        selected = self._normalize_vid_prep_audio_path(getattr(self, 'vid_prep_selected_audio_path', ''))
        if selected:
            return selected
        payload = self._build_vid_prep_audio_track_payload()
        if payload:
            return str(payload[0].get('track_path') or '').strip()
        return ''

    def _build_vid_prep_file_assembly_payload(self, output_path, ffmpeg_command=None, output_kind='video'):
        """Build DB payload rows for VIDEO.FileAssembly."""
        source_path = str(self.vid_prep_source_path or '')
        track_payload = self._build_vid_prep_audio_track_payload()

        command_line = ''
        if ffmpeg_command:
            try:
                command_line = ' '.join(str(part) for part in ffmpeg_command)
            except Exception:
                command_line = str(ffmpeg_command)

        if output_kind == 'image':
            return [{
                'assembly_order': 1,
                'assembly_stage': 'image_export',
                'input_path': source_path,
                'output_path': str(output_path),
                'tool_name': 'opencv',
                'command_line': '',
                'assembly_payload': {
                    'output_kind': 'image',
                    'background_mode': self.vid_prep_bg_mode.currentText(),
                    'resolution_preset': self.vid_prep_output_resolution_combo.currentText(),
                    'trim_start_frame': int(self.vid_prep_trim_start_frame),
                    'trim_end_frame': int(self.vid_prep_trim_end_frame),
                    'marker_frame': int(self._get_vid_prep_current_marker_frame()),
                    'fps': float(self.vid_prep_fps),
                },
            }]

        return [{
            'assembly_order': 1,
            'assembly_stage': 'ffmpeg_export',
            'input_path': source_path,
            'output_path': str(output_path),
            'tool_name': 'ffmpeg',
            'command_line': command_line,
            'assembly_payload': {
                'audio_mode': self._current_vid_prep_audio_mode(),
                'tracks': track_payload,
                'trim_start_frame': int(self.vid_prep_trim_start_frame),
                'trim_end_frame': int(self.vid_prep_trim_end_frame),
                'fps': float(self.vid_prep_fps),
            },
        }]

    def _build_vid_prep_video_output_payload(self, output_path, output_kind='video'):
        """Build DB payload row for VIDEO.VideoOutput."""
        crop = self.vid_prep_crop_rect or self.vid_prep_preview.get_crop_rect_source() or (0, 0, 0, 0)
        crop_x, crop_y, crop_w, crop_h = crop

        return {
            'account_name': self.current_username or getattr(self.content_db.db, 'account_name', ''),
            'output_kind': output_kind,
            'output_path': str(output_path),
            'output_file_name': os.path.basename(str(output_path)),
            'video_file_title': (self.vid_prep_video_title_input.text() or '').strip(),
            'video_file_desc': (self.vid_prep_video_desc_input.toHtml() or '').strip(),
            'source_path': self.vid_prep_source_path,
            'source_shortcode': self._extract_vid_prep_shortcode(self.vid_prep_source_path),
            'selected_topic': (self.vid_prep_selected_topic_input.text() or '').strip(),
            'file_prefix': self._current_vid_prep_file_prefix_text(),
            'file_index': self._current_vid_prep_file_index(),
            'modifier': self._current_vid_prep_modifier(),
            'separator': self._current_vid_prep_separator(),
            'prepend_topic': self.vid_prep_prepend_topic_checkbox.isChecked(),
            'output_folder_mode': self.vid_prep_output_folder_mode,
            'output_folder_path': (self.vid_prep_output_folder_path_input.text() or '').strip(),
            'codec_preset': self.vid_prep_codec_preset.currentText().strip(),
            'crf': int(self.vid_prep_crf.value()),
            'resolution_preset': self.vid_prep_output_resolution_combo.currentText(),
            'output_width': int(self.vid_prep_output_width.value()),
            'output_height': int(self.vid_prep_output_height.value()),
            'background_mode': self.vid_prep_bg_mode.currentText(),
            'background_color': str(getattr(self, 'vid_prep_bg_color', '')),
            'background_image_path': (self.vid_prep_bg_image_path.text() or '').strip(),
            'audio_mode': self._current_vid_prep_audio_mode(),
            'audio_file_path': self._get_vid_prep_primary_audio_path(),
            'audio_start_seconds': 0.0,
            'audio_end_seconds': 0.0,
            'crop_x': int(crop_x),
            'crop_y': int(crop_y),
            'crop_width': int(crop_w),
            'crop_height': int(crop_h),
            'trim_start_frame': int(self.vid_prep_trim_start_frame),
            'trim_end_frame': int(self.vid_prep_trim_end_frame),
            'source_frame_count': int(self.vid_prep_frame_count),
            'source_fps': float(self.vid_prep_fps),
            'source_duration_seconds': float(self.vid_prep_duration_s),
        }

    def persist_vid_prep_output_metadata(self, output_path, overwrite_existing, ffmpeg_command=None, output_kind='video'):
        """Persist current Vid Prep save metadata to VIDEO.VideoOutput/AudioTracks/FileAssembly."""
        if (not self.content_db or not getattr(self.content_db, 'db', None)) and self.current_username:
            try:
                self.content_db = ContentDatabaseManager(str(config.DATA_DIR), self.current_username)
            except Exception:
                pass

        if not self.content_db or not self.content_db.db:
            raise Exception("Content database is not available")

        video_payload = self._build_vid_prep_video_output_payload(output_path, output_kind=output_kind)
        tracks_payload = self._build_vid_prep_audio_track_payload() if output_kind == 'video' else []
        assembly_payload = self._build_vid_prep_file_assembly_payload(
            output_path,
            ffmpeg_command=ffmpeg_command,
            output_kind=output_kind,
        )
        return self.content_db.db.save_video_output_record(
            video_output=video_payload,
            audio_tracks=tracks_payload,
            file_assembly=assembly_payload,
            delete_existing=bool(overwrite_existing),
        )

    def initialize_vid_prep_suggested_applications_editor(self):
        """Initialize Suggested Applications controls beneath Suggested Description."""
        self.vid_prep_suggested_applications = []
        self.vid_prep_suggested_applications_dirty = False
        self._set_vid_prep_combo_placeholder(self.vid_prep_sport_combo, "Select Sport")
        self._set_vid_prep_combo_placeholder(self.vid_prep_technique_class_combo, "Select Technique Class")
        self._set_vid_prep_combo_placeholder(self.vid_prep_technique_type_combo, "Select Technique Type")
        self._set_vid_prep_combo_placeholder(self.vid_prep_series_combo, "Select Technique Application Series")
        self.refresh_vid_prep_suggested_applications_table()
        self.load_vid_prep_sports()
        self.update_vid_prep_add_application_state()

    def _set_vid_prep_combo_placeholder(self, combo, placeholder_text):
        combo.blockSignals(True)
        combo.clear()
        combo.addItem(placeholder_text, -1)
        combo.setCurrentIndex(0)
        combo.blockSignals(False)

    def _set_vid_prep_apps_loading(self, loading_text=''):
        """Show a lightweight loading indicator for Suggested Applications fetches."""
        if hasattr(self, 'vid_prep_apps_loading_label'):
            self.vid_prep_apps_loading_label.setText(loading_text or '')
        QApplication.processEvents()

    def _ensure_vid_prep_content_db(self):
        """Ensure content DB manager exists for current account."""
        if self.content_db and getattr(self.content_db, 'db', None):
            return True
        if not self.current_username:
            return False
        try:
            self.content_db = ContentDatabaseManager(str(config.DATA_DIR), self.current_username)
            return bool(self.content_db and self.content_db.db)
        except Exception as e:
            logger.error("Failed to initialize content DB for suggested applications: %s", e)
            return False

    def load_vid_prep_sports(self):
        """Load Sports dropdown values from soccr API."""
        if self.soccr_api_client_mode == 'off':
            self._set_vid_prep_combo_placeholder(self.vid_prep_sport_combo, "Soccr API Off")
            self._set_vid_prep_combo_placeholder(self.vid_prep_technique_class_combo, "Select Technique Class")
            self._set_vid_prep_combo_placeholder(self.vid_prep_technique_type_combo, "Select Technique Type")
            self._set_vid_prep_combo_placeholder(self.vid_prep_series_combo, "Select Technique Application Series")
            self.vid_prep_add_application_btn.setEnabled(False)
            self._set_vid_prep_apps_loading('')
            return

        try:
            self._set_vid_prep_apps_loading("Loading sports...")
            from soccr_api_client import ApiClient
            from soccr_api_client.api.techniques_api import TechniquesApi

            configuration = self.get_soccr_api_client_configuration()
            with ApiClient(configuration) as api_client:
                techniques_api = TechniquesApi(api_client)
                sports = techniques_api.sports_select_all(include_any=False, _request_timeout=(3, 15)) or []

            self.vid_prep_sport_combo.blockSignals(True)
            self.vid_prep_sport_combo.clear()
            self.vid_prep_sport_combo.addItem("Select Sport", -1)

            target_index = 0
            for sport in sports:
                raw_sport_id = getattr(sport, 'sport_id', None)
                if raw_sport_id is None:
                    continue
                sport_id = int(raw_sport_id)
                sport_name = (getattr(sport, 'sport_name', '') or f"Sport {sport_id}").strip()
                self.vid_prep_sports_cache[sport_id] = sport_name
                self.vid_prep_sport_combo.addItem(sport_name, sport_id)
                if sport_id == 1:
                    target_index = self.vid_prep_sport_combo.count() - 1

            if self.vid_prep_sport_combo.count() > 1:
                self.vid_prep_sport_combo.setCurrentIndex(target_index if target_index > 0 else 1)
            else:
                self.vid_prep_sport_combo.setCurrentIndex(0)
            self.vid_prep_sport_combo.blockSignals(False)
            self.on_vid_prep_sport_changed(self.vid_prep_sport_combo.currentIndex())
        except Exception as e:
            logger.error("Failed to load sports for suggested applications: %s", e)
            self._set_vid_prep_combo_placeholder(self.vid_prep_sport_combo, "Failed to load sports")
            self._set_vid_prep_combo_placeholder(self.vid_prep_technique_class_combo, "Select Technique Class")
            self._set_vid_prep_combo_placeholder(self.vid_prep_technique_type_combo, "Select Technique Type")
            self._set_vid_prep_combo_placeholder(self.vid_prep_series_combo, "Select Technique Application Series")
            self.vid_prep_add_application_btn.setEnabled(False)
        finally:
            self._set_vid_prep_apps_loading('')

    def on_vid_prep_sport_changed(self, _index):
        """Cascade sport selection to technique classes."""
        sport_id = self.vid_prep_sport_combo.currentData()
        sport_id = int(sport_id) if sport_id is not None else -1

        self._set_vid_prep_combo_placeholder(self.vid_prep_technique_class_combo, "Select Technique Class")
        self._set_vid_prep_combo_placeholder(self.vid_prep_technique_type_combo, "Select Technique Type")
        self._set_vid_prep_combo_placeholder(self.vid_prep_series_combo, "Select Technique Application Series")
        if sport_id < 0:
            self.update_vid_prep_add_application_state()
            return

        try:
            self._set_vid_prep_apps_loading("Loading technique classes...")
            from soccr_api_client import ApiClient
            from soccr_api_client.api.techniques_api import TechniquesApi

            configuration = self.get_soccr_api_client_configuration()
            with ApiClient(configuration) as api_client:
                techniques_api = TechniquesApi(api_client)
                classes = techniques_api.technique_classes_select_sport(sport_id=sport_id, _request_timeout=(3, 15)) or []

            self.vid_prep_technique_class_combo.blockSignals(True)
            self.vid_prep_technique_class_combo.clear()
            self.vid_prep_technique_class_combo.addItem("Select Technique Class", -1)
            for cls in classes:
                raw_class_id = getattr(cls, 'technique_class_id', None)
                if raw_class_id is None:
                    continue
                class_id = int(raw_class_id)
                class_name = (getattr(cls, 'technique_class_name', '') or f"Class {class_id}").strip()
                self.vid_prep_technique_class_cache[class_id] = {
                    'name': class_name,
                    'sport_id': sport_id,
                    'sport_name': (getattr(cls, 'sport_name', '') or self.vid_prep_sports_cache.get(sport_id, '')).strip(),
                }
                self.vid_prep_technique_class_combo.addItem(class_name, class_id)
            if self.vid_prep_technique_class_combo.count() > 1:
                self.vid_prep_technique_class_combo.setCurrentIndex(1)
            self.vid_prep_technique_class_combo.blockSignals(False)
            self.on_vid_prep_technique_class_changed(self.vid_prep_technique_class_combo.currentIndex())
        except Exception as e:
            logger.error("Failed to load technique classes for sport %s: %s", sport_id, e)
            self._set_vid_prep_combo_placeholder(self.vid_prep_technique_class_combo, "Failed to load classes")
            self._set_vid_prep_combo_placeholder(self.vid_prep_technique_type_combo, "Select Technique Type")
            self._set_vid_prep_combo_placeholder(self.vid_prep_series_combo, "Select Technique Application Series")
            self.update_vid_prep_add_application_state()
        finally:
            self._set_vid_prep_apps_loading('')

    def on_vid_prep_technique_class_changed(self, _index):
        """Cascade class selection to technique types."""
        class_id = self.vid_prep_technique_class_combo.currentData()
        class_id = int(class_id) if class_id is not None else -1

        self._set_vid_prep_combo_placeholder(self.vid_prep_technique_type_combo, "Select Technique Type")
        self._set_vid_prep_combo_placeholder(self.vid_prep_series_combo, "Select Technique Application Series")
        if class_id < 0:
            self.update_vid_prep_add_application_state()
            return

        try:
            self._set_vid_prep_apps_loading("Loading technique types...")
            from soccr_api_client import ApiClient
            from soccr_api_client.api.techniques_api import TechniquesApi

            configuration = self.get_soccr_api_client_configuration()
            with ApiClient(configuration) as api_client:
                techniques_api = TechniquesApi(api_client)
                technique_types = techniques_api.technique_types_select_active(
                    technique_class_id=class_id,
                    _request_timeout=(3, 15),
                ) or []

            self.vid_prep_technique_type_combo.blockSignals(True)
            self.vid_prep_technique_type_combo.clear()
            self.vid_prep_technique_type_combo.addItem("Select Technique Type", -1)
            for technique_type in technique_types:
                raw_type_id = getattr(technique_type, 'technique_type_id', None)
                if raw_type_id is None:
                    continue
                type_id = int(raw_type_id)
                type_name = (getattr(technique_type, 'technique_type_name', '') or f"Type {type_id}").strip()
                self.vid_prep_technique_type_cache[type_id] = {
                    'name': type_name,
                    'technique_class_id': class_id,
                }
                self.vid_prep_technique_type_combo.addItem(type_name, type_id)
            if self.vid_prep_technique_type_combo.count() > 1:
                self.vid_prep_technique_type_combo.setCurrentIndex(1)
            self.vid_prep_technique_type_combo.blockSignals(False)
            self.on_vid_prep_technique_type_changed(self.vid_prep_technique_type_combo.currentIndex())
        except Exception as e:
            logger.error("Failed to load technique types for class %s: %s", class_id, e)
            self._set_vid_prep_combo_placeholder(self.vid_prep_technique_type_combo, "Failed to load types")
            self._set_vid_prep_combo_placeholder(self.vid_prep_series_combo, "Select Technique Application Series")
            self.update_vid_prep_add_application_state()
        finally:
            self._set_vid_prep_apps_loading('')

    def on_vid_prep_technique_type_changed(self, _index):
        """Cascade technique type selection to application series."""
        type_id = self.vid_prep_technique_type_combo.currentData()
        type_id = int(type_id) if type_id is not None else -1

        self._set_vid_prep_combo_placeholder(self.vid_prep_series_combo, "Select Technique Application Series")
        if type_id < 0:
            self.update_vid_prep_add_application_state()
            return

        try:
            self._set_vid_prep_apps_loading("Loading application series...")
            from soccr_api_client import ApiClient
            from soccr_api_client.api.technique_series_api import TechniqueSeriesApi

            configuration = self.get_soccr_api_client_configuration()
            with ApiClient(configuration) as api_client:
                series_api = TechniqueSeriesApi(api_client)
                series_items = series_api.technique_application_series_for_application(
                    technique_type_id=type_id,
                    _request_timeout=(3, 15),
                ) or []

            self.vid_prep_series_combo.blockSignals(True)
            self.vid_prep_series_combo.clear()
            self.vid_prep_series_combo.addItem("Select Technique Application Series", -1)
            for series in series_items:
                raw_tsid = getattr(series, 'tsid', None)
                if raw_tsid is None:
                    continue
                tsid = int(raw_tsid)
                series_name = (getattr(series, 'technique_series_name', '') or f"Series {tsid}").strip()
                self.vid_prep_series_cache[tsid] = {
                    'name': series_name,
                    'technique_type_id': type_id,
                }
                self.vid_prep_series_combo.addItem(series_name, tsid)
            if self.vid_prep_series_combo.count() > 1:
                self.vid_prep_series_combo.setCurrentIndex(1)
            self.vid_prep_series_combo.blockSignals(False)
        except Exception as e:
            logger.error("Failed to load technique application series for type %s: %s", type_id, e)
            self._set_vid_prep_combo_placeholder(self.vid_prep_series_combo, "Failed to load series")
        finally:
            self._set_vid_prep_apps_loading('')

        self.update_vid_prep_add_application_state()

    def update_vid_prep_add_application_state(self):
        """Enable Add when all dropdown values and VidID are present."""
        sport_id = self.vid_prep_sport_combo.currentData() if hasattr(self, 'vid_prep_sport_combo') else -1
        class_id = self.vid_prep_technique_class_combo.currentData() if hasattr(self, 'vid_prep_technique_class_combo') else -1
        type_id = self.vid_prep_technique_type_combo.currentData() if hasattr(self, 'vid_prep_technique_type_combo') else -1
        tsid = self.vid_prep_series_combo.currentData() if hasattr(self, 'vid_prep_series_combo') else -1

        complete_selection = all([
            sport_id is not None and int(sport_id) >= 0,
            class_id is not None and int(class_id) >= 0,
            type_id is not None and int(type_id) >= 0,
            tsid is not None and int(tsid) >= 0,
        ])
        can_add = bool(complete_selection)
        self.vid_prep_add_application_btn.setEnabled(can_add)
        self.vid_prep_add_application_btn.setToolTip("Stage selected application mapping (saved to SQL when video is saved)")

    def on_vid_prep_add_application_clicked(self):
        """Stage selected Suggested Application row (persisted on video save)."""
        sport_id = self.vid_prep_sport_combo.currentData()
        class_id = self.vid_prep_technique_class_combo.currentData()
        type_id = self.vid_prep_technique_type_combo.currentData()
        tsid = self.vid_prep_series_combo.currentData()
        if any(v is None or int(v) < 0 for v in [sport_id, class_id, type_id, tsid]):
            QMessageBox.warning(self, "Suggested Applications", "Select Sport, Class, Technique Type, and Series before adding.")
            return

        sport_id = int(sport_id)
        class_id = int(class_id)
        type_id = int(type_id)
        tsid = int(tsid)
        key_technique = bool(self.vid_prep_key_technique_check.isChecked())

        duplicate_exists = any(
            int(row.get('TechniqueClassID') or -1) == class_id and
            int(row.get('TechniqueTypeID') or -1) == type_id and
            int(row.get('TSID') or -1) == tsid
            for row in self.vid_prep_suggested_applications
        )
        if duplicate_exists:
            QMessageBox.information(
                self,
                "Suggested Applications",
                "That application mapping is already staged for this video."
            )
            return

        self.vid_prep_suggested_applications.append({
            'VidAID': None,
            'VidID': self.vid_prep_current_vid_id,
            'SportID': sport_id,
            'TechniqueClassID': class_id,
            'TechniqueTypeID': type_id,
            'TSID': tsid,
            'KeyTechnique': key_technique,
            'SportName': (self.vid_prep_sports_cache.get(sport_id, self.vid_prep_sport_combo.currentText()) or '').strip(),
            'TechniqueClassName': (self.vid_prep_technique_class_cache.get(class_id, {}).get('name', self.vid_prep_technique_class_combo.currentText()) or '').strip(),
            'TechniqueTypeName': (self.vid_prep_technique_type_cache.get(type_id, {}).get('name', self.vid_prep_technique_type_combo.currentText()) or '').strip(),
            'TechniqueSeriesName': (self.vid_prep_series_cache.get(tsid, {}).get('name', self.vid_prep_series_combo.currentText()) or '').strip(),
        })
        self.vid_prep_suggested_applications_dirty = True
        self.refresh_vid_prep_suggested_applications_table()
        self.vid_prep_status.setText("Suggested application staged (will save with video).")

    def refresh_vid_prep_suggested_applications_table(self):
        """Rebuild Suggested Applications list table."""
        table = self.vid_prep_applications_table
        table.setRowCount(len(self.vid_prep_suggested_applications))

        for row_index, row in enumerate(self.vid_prep_suggested_applications):
            table.setItem(row_index, 0, QTableWidgetItem(f"{row_index + 1}."))
            table.setItem(row_index, 1, QTableWidgetItem(str(row.get('SportName') or f"Sport {row.get('SportID') or ''}")))
            table.setItem(row_index, 2, QTableWidgetItem(str(row.get('TechniqueClassName') or f"Class {row.get('TechniqueClassID') or ''}")))
            table.setItem(row_index, 3, QTableWidgetItem(str(row.get('TechniqueTypeName') or f"Type {row.get('TechniqueTypeID') or ''}")))
            table.setItem(row_index, 4, QTableWidgetItem(str(row.get('TechniqueSeriesName') or f"Series {row.get('TSID') or ''}")))
            table.setItem(row_index, 5, QTableWidgetItem("Yes" if bool(row.get('KeyTechnique')) else "No"))

            delete_btn = QPushButton("X")
            delete_btn.setFixedWidth(34)
            delete_btn.clicked.connect(lambda _checked=False, idx=row_index: self.on_vid_prep_delete_application_by_index(idx))
            table.setCellWidget(row_index, 6, delete_btn)

    def load_vid_prep_video_applications(self, vid_id=None, preloaded_rows=None):
        """Load VIDEO.Applications rows for current VidID and render the table."""
        if vid_id is not None:
            try:
                self.vid_prep_current_vid_id = int(vid_id) if vid_id else None
            except Exception:
                self.vid_prep_current_vid_id = None

        if not self.vid_prep_current_vid_id:
            self.vid_prep_suggested_applications = []
            self.vid_prep_suggested_applications_dirty = False
            self.refresh_vid_prep_suggested_applications_table()
            self.update_vid_prep_add_application_state()
            return

        if preloaded_rows is not None:
            rows = preloaded_rows
        else:
            if not self._ensure_vid_prep_content_db():
                self.vid_prep_suggested_applications = []
                self.refresh_vid_prep_suggested_applications_table()
                self.update_vid_prep_add_application_state()
                return
            rows = self.content_db.db.get_video_applications(int(self.vid_prep_current_vid_id))

        resolved_rows = []
        for row in rows or []:
            resolved_rows.append(self._resolve_vid_prep_application_row_display(row))

        self.vid_prep_suggested_applications = resolved_rows
        self.vid_prep_suggested_applications_dirty = False
        self.refresh_vid_prep_suggested_applications_table()
        self.update_vid_prep_add_application_state()

    def _resolve_vid_prep_application_row_display(self, row):
        """Resolve row display fields for Suggested Applications table."""
        class_id = int(row.get('TechniqueClassID') or 0)
        type_id = int(row.get('TechniqueTypeID') or 0)
        tsid = int(row.get('TSID') or 0)
        sport_id = int(row.get('SportID') or 0)

        class_name = self.vid_prep_technique_class_cache.get(class_id, {}).get('name', '')
        sport_name = self.vid_prep_technique_class_cache.get(class_id, {}).get('sport_name', '')
        cached_sport_id = self.vid_prep_technique_class_cache.get(class_id, {}).get('sport_id')
        if cached_sport_id and not sport_id:
            sport_id = int(cached_sport_id)
        type_name = self.vid_prep_technique_type_cache.get(type_id, {}).get('name', '')
        series_name = self.vid_prep_series_cache.get(tsid, {}).get('name', '')

        if self.soccr_api_client_mode != 'off':
            try:
                from soccr_api_client import ApiClient
                from soccr_api_client.api.techniques_api import TechniquesApi
                from soccr_api_client.api.technique_series_api import TechniqueSeriesApi

                configuration = self.get_soccr_api_client_configuration()
                with ApiClient(configuration) as api_client:
                    techniques_api = TechniquesApi(api_client)
                    series_api = TechniqueSeriesApi(api_client)

                    if class_id and not class_name:
                        class_item = techniques_api.technique_classes_select_item(
                            technique_class_id=class_id,
                            _request_timeout=(3, 10),
                        )
                        class_name = (getattr(class_item, 'technique_class_name', '') or f"Class {class_id}").strip()
                        resolved_sport_id = int(getattr(class_item, 'sport_id', 0) or 0)
                        sport_id = resolved_sport_id or sport_id
                        sport_name = (getattr(class_item, 'sport_name', '') or sport_name).strip()
                        self.vid_prep_technique_class_cache[class_id] = {
                            'name': class_name,
                            'sport_id': sport_id,
                            'sport_name': sport_name,
                        }

                    if type_id and not type_name:
                        type_item = techniques_api.technique_types_select_item(
                            technique_type_id=type_id,
                            _request_timeout=(3, 10),
                        )
                        type_name = (getattr(type_item, 'technique_type_name', '') or f"Type {type_id}").strip()
                        self.vid_prep_technique_type_cache[type_id] = {
                            'name': type_name,
                            'technique_class_id': int(getattr(type_item, 'technique_class_id', 0) or class_id or 0),
                        }

                    if tsid and not series_name:
                        series_item = series_api.technique_application_series_detail_for_edit(
                            tsid=tsid,
                            _request_timeout=(3, 10),
                        )
                        series_name = (getattr(series_item, 'technique_series_name', '') or f"Series {tsid}").strip()
                        self.vid_prep_series_cache[tsid] = {
                            'name': series_name,
                            'technique_type_id': type_id,
                        }
            except Exception as e:
                logger.warning("Could not fully resolve suggested application names for VidAID=%s: %s", row.get('VidAID'), e)

        if sport_id and not sport_name:
            sport_name = self.vid_prep_sports_cache.get(sport_id, '')

        return {
            'VidAID': row.get('VidAID'),
            'VidID': row.get('VidID'),
            'SportID': sport_id or None,
            'TechniqueClassID': class_id or None,
            'TechniqueTypeID': type_id or None,
            'TSID': tsid or None,
            'KeyTechnique': bool(row.get('KeyTechnique')) if row.get('KeyTechnique') is not None else False,
            'SportName': (sport_name or f"Sport {sport_id}" if sport_id else "").strip(),
            'TechniqueClassName': (class_name or f"Class {class_id}" if class_id else "").strip(),
            'TechniqueTypeName': (type_name or f"Type {type_id}" if type_id else "").strip(),
            'TechniqueSeriesName': (series_name or f"Series {tsid}" if tsid else "").strip(),
        }

    def on_vid_prep_delete_application_by_index(self, row_index):
        """Remove a Suggested Application row from the staged list by visible row index."""
        if row_index is None:
            return
        if row_index < 0 or row_index >= len(self.vid_prep_suggested_applications):
            return
        self.vid_prep_suggested_applications.pop(int(row_index))

        self.vid_prep_suggested_applications_dirty = True
        self.refresh_vid_prep_suggested_applications_table()
        self.vid_prep_status.setText("Suggested application removed (pending save).")

    def persist_vid_prep_video_applications(self, vid_id):
        """Persist currently staged Suggested Applications rows for a VidID."""
        if vid_id is None:
            return
        if not self._ensure_vid_prep_content_db():
            raise Exception("Database manager is not available")

        payload_rows = []
        for row in self.vid_prep_suggested_applications:
            payload_rows.append({
                'TechniqueClassID': int(row.get('TechniqueClassID')),
                'TechniqueTypeID': int(row.get('TechniqueTypeID')),
                'TSID': int(row.get('TSID')) if row.get('TSID') is not None else None,
                'KeyTechnique': bool(row.get('KeyTechnique')),
            })

        self.content_db.db.replace_video_applications(int(vid_id), payload_rows)
        self.load_vid_prep_video_applications(vid_id=vid_id)

    def on_vid_prep_video_notes_changed(self):
        """Mark output preview stale when Suggested Title/Description changes."""
        self._set_vid_prep_output_preview_dirty(True)

    def _apply_vid_prep_desc_format(self, fmt_type: str, on: bool):
        """Apply a bold/italic/underline format toggle to the desc editor selection."""
        editor = self.vid_prep_video_desc_input
        fmt = QTextCharFormat()
        if fmt_type == 'bold':
            fmt.setFontWeight(QFont.Bold if on else QFont.Normal)
        elif fmt_type == 'italic':
            fmt.setFontItalic(on)
        elif fmt_type == 'underline':
            fmt.setFontUnderline(on)
        editor.mergeCurrentCharFormat(fmt)
        editor.setFocus()

    def _sync_vid_prep_desc_toolbar(self, char_fmt: QTextCharFormat):
        """Keep the B/I/U toolbar buttons in sync with the cursor's format."""
        if not hasattr(self, 'vid_prep_desc_bold_btn'):
            return
        self.vid_prep_desc_bold_btn.blockSignals(True)
        self.vid_prep_desc_italic_btn.blockSignals(True)
        self.vid_prep_desc_underline_btn.blockSignals(True)
        self.vid_prep_desc_bold_btn.setChecked(char_fmt.fontWeight() >= QFont.Bold)
        self.vid_prep_desc_italic_btn.setChecked(char_fmt.fontItalic())
        self.vid_prep_desc_underline_btn.setChecked(char_fmt.fontUnderline())
        self.vid_prep_desc_bold_btn.blockSignals(False)
        self.vid_prep_desc_italic_btn.blockSignals(False)
        self.vid_prep_desc_underline_btn.blockSignals(False)

    # ── Suggested Nodes ─────────────────────────────────────────────────────

    def refresh_vid_prep_suggested_nodes_table(self):
        """Rebuild the staged Suggested Nodes list table."""
        if not hasattr(self, 'vid_prep_nodes_table'):
            return
        table = self.vid_prep_nodes_table
        table.setRowCount(len(self.vid_prep_suggested_nodes))
        for row_idx, node in enumerate(self.vid_prep_suggested_nodes):
            flow_id = node.get('FlowID')
            flow_label = node.get('FlowName') or (str(flow_id) if flow_id not in (None, -1) else '')
            parent_id = node.get('ParentNodeID')
            parent_label = str(parent_id) if parent_id is not None else ''
            table.setItem(row_idx, 0, QTableWidgetItem(f"{row_idx + 1}."))
            table.setItem(row_idx, 1, QTableWidgetItem(flow_label))
            table.setItem(row_idx, 2, QTableWidgetItem(parent_label))
            table.setItem(row_idx, 3, QTableWidgetItem(node.get('NodeName') or ''))
            del_btn = QPushButton("X")
            del_btn.setFixedWidth(28)
            del_btn.clicked.connect(lambda _checked=False, idx=row_idx: self.on_vid_prep_delete_node_by_index(idx))
            table.setCellWidget(row_idx, 4, del_btn)

    def on_vid_prep_add_node_clicked(self):
        """Stage a Suggested Node row (persisted to VIDEO.NodeOutput on video save)."""
        node_name = (self.vid_prep_node_name_input.text() or '').strip()
        if not node_name:
            QMessageBox.warning(self, "Suggested Nodes", "Node Name is required.")
            return

        flow_id = self.vid_prep_node_flow_combo.currentData()
        flow_id = int(flow_id) if flow_id is not None and int(flow_id) >= 0 else None
        flow_name = self.vid_prep_node_flow_combo.currentText() if flow_id is not None else ''

        parent_id_text = (self.vid_prep_node_parent_id_input.text() or '').strip()
        try:
            parent_id = int(parent_id_text) if parent_id_text else None
        except ValueError:
            parent_id = None

        node_desc = (self.vid_prep_node_description_input.toPlainText() or '').strip()

        self.vid_prep_suggested_nodes.append({
            'FlowID': flow_id,
            'FlowName': flow_name,
            'ParentNodeID': parent_id,
            'NodeName': node_name,
            'NodeDescription': node_desc,
        })
        self.vid_prep_suggested_nodes_dirty = True
        self.refresh_vid_prep_suggested_nodes_table()

        # Clear the form inputs ready for next entry
        self.vid_prep_node_parent_id_input.clear()
        self.vid_prep_node_name_input.clear()
        self.vid_prep_node_description_input.clear()
        self.vid_prep_status.setText("Suggested node staged (will save with video).")

    def on_vid_prep_delete_node_by_index(self, row_index):
        """Remove a staged Suggested Node by visible row index."""
        if row_index is None or row_index < 0 or row_index >= len(self.vid_prep_suggested_nodes):
            return
        self.vid_prep_suggested_nodes.pop(int(row_index))
        self.vid_prep_suggested_nodes_dirty = True
        self.refresh_vid_prep_suggested_nodes_table()
        self.vid_prep_status.setText("Suggested node removed (pending save).")

    def load_vid_prep_video_nodes(self, vid_id=None, preloaded_rows=None):
        """Load VIDEO.NodeOutput rows for current VidID and render the table."""
        if vid_id is not None:
            try:
                self.vid_prep_current_vid_id = int(vid_id) if vid_id else None
            except Exception:
                pass

        if not self.vid_prep_current_vid_id:
            self.vid_prep_suggested_nodes = []
            self.vid_prep_suggested_nodes_dirty = False
            self.refresh_vid_prep_suggested_nodes_table()
            return

        if preloaded_rows is not None:
            rows = preloaded_rows
        else:
            if not self._ensure_vid_prep_content_db():
                self.vid_prep_suggested_nodes = []
                self.refresh_vid_prep_suggested_nodes_table()
                return
            try:
                rows = self.content_db.db.get_video_nodes(int(self.vid_prep_current_vid_id))
            except Exception as e:
                logger.error("Failed to load video nodes: %s", e)
                rows = []

        self.vid_prep_suggested_nodes = [
            {
                'FlowID': row.get('FlowID'),
                'FlowName': str(row.get('FlowID') or '') if row.get('FlowID') else '',
                'ParentNodeID': row.get('ParentNodeID'),
                'NodeName': row.get('NodeName') or '',
                'NodeDescription': row.get('NodeDescription') or '',
            }
            for row in (rows or [])
        ]
        self.vid_prep_suggested_nodes_dirty = False
        self.refresh_vid_prep_suggested_nodes_table()

    def persist_vid_prep_video_nodes(self, vid_id):
        """Persist staged Suggested Nodes to VIDEO.NodeOutput for a VidID."""
        if vid_id is None:
            return
        if not self._ensure_vid_prep_content_db():
            raise Exception("Database manager not available for node persistence")

        payload = [
            {
                'FlowID': node.get('FlowID'),
                'ParentNodeID': node.get('ParentNodeID'),
                'NodeName': node.get('NodeName'),
                'NodeDescription': node.get('NodeDescription'),
            }
            for node in self.vid_prep_suggested_nodes
        ]
        self.content_db.db.replace_video_nodes(int(vid_id), payload)
        self.load_vid_prep_video_nodes(vid_id=vid_id)

    def _save_vid_prep_ui_settings(self):
        """Persist Vid Prep tab UI settings in account settings database."""
        if getattr(self, '_vid_prep_ui_loading', False):
            return
        if not self.current_username:
            return

        self.save_ui_setting('vid_prep_codec_preset', self.vid_prep_codec_preset.currentText())
        self.save_ui_setting('vid_prep_crf', str(self.vid_prep_crf.value()))
        self.save_ui_setting('vid_prep_output_resolution', self.vid_prep_output_resolution_combo.currentText())
        self.save_ui_setting('vid_prep_output_width', str(self.vid_prep_output_width.value()))
        self.save_ui_setting('vid_prep_output_height', str(self.vid_prep_output_height.value()))
        self.save_ui_setting('vid_prep_bg_mode', self.vid_prep_bg_mode.currentText())
        self.save_ui_setting('vid_prep_bg_color', str(self.vid_prep_bg_color))
        self.save_ui_setting('vid_prep_bg_image_path', self.vid_prep_bg_image_path.text().strip())
        self.save_ui_setting('vid_prep_input_volume', str(self.vid_prep_input_volume_slider.value()))
        self.save_ui_setting('vid_prep_input_muted', 'true' if self.vid_prep_input_mute_btn.isChecked() else 'false')

        if self.vid_prep_audio_replace_radio.isChecked():
            audio_mode = 'replace'
        elif self.vid_prep_audio_maintain_radio.isChecked():
            audio_mode = 'maintain'
        elif self.vid_prep_audio_mix_radio.isChecked():
            audio_mode = 'mix'
        else:
            audio_mode = 'remove'

        self.save_ui_setting('vid_prep_audio_mode', audio_mode)
        self.save_ui_setting('vid_prep_mp3_path', self._get_vid_prep_primary_audio_path())
        self.save_ui_setting('vid_prep_selected_topic', (self.vid_prep_selected_topic_input.text() or '').strip())
        self._update_vid_prep_file_prefix_history(self._current_vid_prep_file_prefix_text())
        self.save_ui_setting('vid_prep_file_prefix', self._current_vid_prep_file_prefix_text())
        self.save_ui_setting('vid_prep_file_index', self._current_vid_prep_file_index())
        self.save_ui_setting('vid_prep_modifier', self._current_vid_prep_modifier())
        self.save_ui_setting('vid_prep_separator', self._current_vid_prep_separator())
        self.save_ui_setting('vid_prep_prepend_topic_filename', 'true' if self.vid_prep_prepend_topic_checkbox.isChecked() else 'false')
        self.save_ui_setting('vid_prep_output_folder_mode', self.vid_prep_output_folder_mode)
        self.save_ui_setting('vid_prep_output_folder_path', self.vid_prep_output_folder_path_input.text().strip())

    def _load_vid_prep_ui_settings(self):
        """Load Vid Prep tab UI settings from account settings database."""
        if not self.current_username:
            return

        previous_loading = getattr(self, '_vid_prep_ui_loading', False)
        self._vid_prep_ui_loading = True
        try:
            codec = self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_codec_preset', self.vid_prep_codec_preset.currentText())
            if codec in [self.vid_prep_codec_preset.itemText(i) for i in range(self.vid_prep_codec_preset.count())]:
                self.vid_prep_codec_preset.setCurrentText(codec)

            try:
                self.vid_prep_crf.setValue(max(0, min(51, int(self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_crf', str(self.vid_prep_crf.value()))))))
            except Exception:
                pass

            saved_resolution = self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_output_resolution', self.vid_prep_output_resolution_combo.currentText())
            if saved_resolution in [self.vid_prep_output_resolution_combo.itemText(i) for i in range(self.vid_prep_output_resolution_combo.count())]:
                self.vid_prep_output_resolution_combo.setCurrentText(saved_resolution)

            try:
                self.vid_prep_output_width.setValue(max(2, min(7680, int(self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_output_width', str(self.vid_prep_output_width.value()))))))
                self.vid_prep_output_height.setValue(max(2, min(7680, int(self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_output_height', str(self.vid_prep_output_height.value()))))))
            except Exception:
                pass

            saved_bg_mode = self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_bg_mode', self.vid_prep_bg_mode.currentText())
            if saved_bg_mode in [self.vid_prep_bg_mode.itemText(i) for i in range(self.vid_prep_bg_mode.count())]:
                self.vid_prep_bg_mode.setCurrentText(saved_bg_mode)
            self.vid_prep_bg_color = self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_bg_color', str(self.vid_prep_bg_color))
            self.vid_prep_bg_image_path.setText(self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_bg_image_path', self.vid_prep_bg_image_path.text()))

            try:
                self.vid_prep_input_volume_slider.setValue(max(0, min(100, int(self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_input_volume', str(self.vid_prep_input_volume_slider.value()))))))
            except Exception:
                pass
            input_muted = self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_input_muted', 'false') == 'true'
            self.vid_prep_input_mute_btn.setChecked(input_muted)

            audio_mode = self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_audio_mode', 'remove')
            if audio_mode == 'replace':
                self.vid_prep_audio_replace_radio.setChecked(True)
            elif audio_mode == 'maintain':
                self.vid_prep_audio_maintain_radio.setChecked(True)
            elif audio_mode == 'mix':
                self.vid_prep_audio_mix_radio.setChecked(True)
            else:
                self.vid_prep_audio_remove_radio.setChecked(True)

            self.vid_prep_selected_audio_path = self._normalize_vid_prep_audio_path(
                self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_mp3_path', getattr(self, 'vid_prep_selected_audio_path', ''))
            )
            self.refresh_vid_prep_audio_library_list(self.vid_prep_selected_audio_path)
            self.refresh_vid_prep_sfx_library_list(self.vid_prep_selected_audio_path)

            self.vid_prep_selected_topic_input.setText(self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_selected_topic', self.vid_prep_selected_topic_input.text()))
            self._set_vid_prep_file_prefix_text(
                self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_file_prefix', self._current_vid_prep_file_prefix_text()),
                update_history=False,
            )
            saved_file_index = self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_file_index', self._current_vid_prep_file_index())
            if saved_file_index in [self.vid_prep_file_index_combo.itemText(i) for i in range(self.vid_prep_file_index_combo.count())]:
                self.vid_prep_file_index_combo.setCurrentText(saved_file_index)
            saved_modifier = self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_modifier', self._current_vid_prep_modifier())
            if saved_modifier in [self.vid_prep_modifier_combo.itemText(i) for i in range(self.vid_prep_modifier_combo.count())]:
                self.vid_prep_modifier_combo.setCurrentText(saved_modifier)
            saved_separator = self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_separator', self._current_vid_prep_separator())
            if saved_separator in [self.vid_prep_separator_combo.itemText(i) for i in range(self.vid_prep_separator_combo.count())]:
                self.vid_prep_separator_combo.setCurrentText(saved_separator)

            self.vid_prep_file_prefix = self._current_vid_prep_file_prefix_text()
            self.vid_prep_file_index = self._current_vid_prep_file_index()
            self.vid_prep_modifier = self._current_vid_prep_modifier()
            self.vid_prep_separator = self._current_vid_prep_separator()
            prepend_topic = self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_prepend_topic_filename', 'true' if self.vid_prep_prepend_topic_checkbox.isChecked() else 'false') == 'true'
            self.vid_prep_prepend_topic_checkbox.setChecked(prepend_topic)

            saved_folder_mode = self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_output_folder_mode', self.vid_prep_output_folder_mode)
            valid_modes = ('same_as_input', 'user_specified', 'default_video_output', 'dvo_topic')
            self.vid_prep_output_folder_mode = saved_folder_mode if saved_folder_mode in valid_modes else 'same_as_input'
            mode_text_map = {
                'same_as_input': 'Same as input',
                'user_specified': 'User specified',
                'default_video_output': 'Default Video Output',
                'dvo_topic': 'DVO/Topic',
            }
            self.vid_prep_output_folder_mode_combo.setCurrentText(mode_text_map[self.vid_prep_output_folder_mode])
            self.vid_prep_output_folder_path_input.setText(self.account_manager.get_account_setting(self.current_username, 'ui_vid_prep_output_folder_path', self.vid_prep_output_folder_path_input.text()))
            self.vid_prep_output_folder_path = (self.vid_prep_output_folder_path_input.text() or '').strip()
            self.vid_prep_output_folder_path_input.setEnabled(self.vid_prep_output_folder_mode == 'user_specified')
            self.vid_prep_output_folder_browse_btn.setEnabled(self.vid_prep_output_folder_mode == 'user_specified')
            if hasattr(self, 'settings_video_output_path_input'):
                self.settings_video_output_path_input.setText(self.vid_prep_output_folder_path_input.text())

            self.vid_prep_output_preview_dirty = True
            self.update_vid_prep_resolution_ui()
            self.update_vid_prep_background_mode_ui()
            self.update_vid_prep_audio_mode_ui()
            self.update_vid_prep_output_filename_preview()
        finally:
            self._vid_prep_ui_loading = previous_loading

    def on_vid_prep_format_setting_changed(self, *args):
        """Persist format/background controls and mark preview stale."""
        self._save_vid_prep_ui_settings()
        self._set_vid_prep_output_preview_dirty(True)

    def _set_vid_prep_output_preview_dirty(self, is_dirty):
        """Track whether output preview is stale and update the tiny status label."""
        self.vid_prep_output_preview_dirty = bool(is_dirty)
        if self.vid_prep_output_preview_dirty:
            self.vid_prep_preview_stale_label.setText("Preview out of date")
            self.vid_prep_preview_stale_label.setVisible(True)
        else:
            self.vid_prep_preview_stale_label.setText("Preview up to date")
            self.vid_prep_preview_stale_label.setVisible(False)

    def _vid_prep_frame_to_seconds(self, frame_idx):
        """Convert a frame index to seconds using the current FPS."""
        if self.vid_prep_fps and self.vid_prep_fps > 0:
            return float(frame_idx) / float(self.vid_prep_fps)
        return 0.0

    def update_vid_prep_trim_label(self):
        """Refresh the visible trim range label."""
        if self.vid_prep_frame_count <= 0:
            self.vid_prep_trim_label.setText("Trim: full video")
            return

        start_s = self._vid_prep_frame_to_seconds(self.vid_prep_trim_start_frame)
        end_s = self._vid_prep_frame_to_seconds(self.vid_prep_trim_end_frame + 1)
        self.vid_prep_trim_label.setText(
            f"Trim: {self._format_vid_prep_time(start_s)} -> {self._format_vid_prep_time(end_s)}"
        )

    def on_vid_prep_trim_range_changed(self, start_frame, end_frame):
        """Store the trim markers and refresh the trim label."""
        self.vid_prep_trim_start_frame = max(0, int(start_frame))
        self.vid_prep_trim_end_frame = max(self.vid_prep_trim_start_frame, int(end_frame))
        if self.vid_prep_frame_count > 0:
            self.vid_prep_trim_start_frame = min(self.vid_prep_trim_start_frame, self.vid_prep_frame_count - 1)
            self.vid_prep_trim_end_frame = min(self.vid_prep_trim_end_frame, self.vid_prep_frame_count - 1)
        self.update_vid_prep_trim_label()
        self._set_vid_prep_output_preview_dirty(True)

    def update_vid_prep_resolution_ui(self):
        """Enable resolution fields based on the selected preset."""
        preset = self.vid_prep_output_resolution_combo.currentText()
        preset_map = {
            "Match Crop": None,
            "Original": None,
            "720x1280": (720, 1280),
            "1080x1920": (1080, 1920),
            "1080x1080": (1080, 1080),
        }
        custom_enabled = preset == "Custom"
        self.vid_prep_output_width.setEnabled(custom_enabled)
        self.vid_prep_output_height.setEnabled(custom_enabled)

        if preset == "Match Crop":
            crop = self.vid_prep_crop_rect or self.vid_prep_preview.get_crop_rect_source()
            if crop:
                _, _, crop_w, crop_h = crop
                if crop_w % 2 != 0:
                    crop_w += 1
                if crop_h % 2 != 0:
                    crop_h += 1
                self.vid_prep_output_width.setValue(max(2, int(crop_w)))
                self.vid_prep_output_height.setValue(max(2, int(crop_h)))

        if preset in preset_map and preset_map[preset]:
            width, height = preset_map[preset]
            self.vid_prep_output_width.setValue(width)
            self.vid_prep_output_height.setValue(height)

        self.update_vid_prep_output_filename_preview()
        self._set_vid_prep_output_preview_dirty(True)

    def update_vid_prep_background_mode_ui(self):
        """Enable background controls based on the selected background mode."""
        mode = self.vid_prep_bg_mode.currentText()
        image_enabled = mode == "Image File"
        color_enabled = mode == "Custom Color"
        self.vid_prep_bg_image_path.setEnabled(image_enabled)
        self.vid_prep_bg_image_browse_btn.setEnabled(image_enabled)
        self.vid_prep_bg_color_button.setEnabled(color_enabled)

        if mode == "Black":
            self.vid_prep_bg_color = "#000000"
        elif mode == "White":
            self.vid_prep_bg_color = "#ffffff"

        self.vid_prep_bg_color_button.setText(f"Color: {self.vid_prep_bg_color}")
        self._set_vid_prep_output_preview_dirty(True)

    def update_vid_prep_output_format_ui(self):
        """Refresh output format and background controls together."""
        self.update_vid_prep_resolution_ui()
        self.update_vid_prep_background_mode_ui()

    def choose_vid_prep_bg_color(self):
        """Pick a custom background color."""
        chosen = QColorDialog.getColor(QColor(self.vid_prep_bg_color), self, "Choose background color")
        if chosen.isValid():
            self.vid_prep_bg_color = chosen.name()
            self.vid_prep_bg_color_button.setText(f"Color: {self.vid_prep_bg_color}")
            self._set_vid_prep_output_preview_dirty(True)

    def pick_vid_prep_bg_color(self):
        """Compatibility wrapper for existing button wiring."""
        self.choose_vid_prep_bg_color()

    def browse_vid_prep_bg_image(self):
        """Browse for a background image file."""
        file_path, _ = QFileDialog.getOpenFileName(
            self,
            "Select Background Image",
            "",
            "Images (*.png *.jpg *.jpeg *.webp *.bmp)"
        )
        if file_path:
            self.vid_prep_bg_image_path.setText(file_path)
            self._set_vid_prep_output_preview_dirty(True)

    def browse_vid_prep_mp3(self):
        """Browse for replacement audio tracks."""
        file_path, _ = QFileDialog.getOpenFileName(
            self,
            "Select Music File",
            "",
            "Audio Files (*.mp3 *.wav *.m4a *.aac *.flac *.ogg);;MP3 Files (*.mp3);;All Files (*)"
        )
        if file_path:
            normalized = self._normalize_vid_prep_audio_path(file_path)
            self.vid_prep_selected_audio_path = normalized
            self.add_vid_prep_audio_to_library(normalized, select_added=True)
            self.on_vid_prep_audio_tracks_dropped([normalized])
            self.vid_prep_audio_replace_radio.setChecked(True)
            self.refresh_vid_prep_audio_library_list(normalized)
            self.on_vid_prep_audio_setting_changed()

    def _sanitize_vid_prep_filename_component(self, value):
        """Return a filesystem-safe filename component."""
        cleaned = re.sub(r'[<>:"/\\|?*]+', '_', str(value or '').strip())
        cleaned = re.sub(r'\s+', ' ', cleaned).strip()
        return cleaned or "output"

    def _sanitize_vid_prep_filename_token(self, value, fallback=''):
        """Return a safe filename token, without spaces and separators."""
        cleaned = re.sub(r'[<>:"/\\|?*]+', '_', str(value or '').strip())
        cleaned = re.sub(r'\s+', '_', cleaned)
        cleaned = re.sub(r'_+', '_', cleaned).strip('._ ')
        if cleaned:
            return cleaned
        return fallback

    def _extract_vid_prep_shortcode(self, source_path):
        """Best-effort extraction of shortcode from source filename."""
        stem = Path(source_path).stem
        tokens = re.split(r'[^A-Za-z0-9_-]+', stem)
        for token in reversed(tokens):
            if re.fullmatch(r'[A-Za-z0-9_-]{6,}', token):
                return token
        return self._sanitize_vid_prep_filename_token(stem, 'unknown')

    def _current_vid_prep_file_index(self):
        """Return the currently selected file index string (01-20)."""
        if hasattr(self, 'vid_prep_file_index_combo') and self.vid_prep_file_index_combo.count() > 0:
            current = (self.vid_prep_file_index_combo.currentText() or '').strip()
            if current:
                return current
        return getattr(self, 'vid_prep_file_index', '01') or '01'

    def _current_vid_prep_modifier(self):
        """Return active modifier value from UI/state."""
        if hasattr(self, 'vid_prep_modifier_combo') and self.vid_prep_modifier_combo.count() > 0:
            current = (self.vid_prep_modifier_combo.currentText() or '').strip()
            if current:
                return current
        return getattr(self, 'vid_prep_modifier', '[NOTHING]') or '[NOTHING]'

    def _current_vid_prep_separator(self):
        """Return active filename separator from UI/state."""
        if hasattr(self, 'vid_prep_separator_combo') and self.vid_prep_separator_combo.count() > 0:
            current = (self.vid_prep_separator_combo.currentText() or '').strip()
            if current in ('-', '_', '.'):
                return current
        saved = getattr(self, 'vid_prep_separator', '.')
        return saved if saved in ('-', '_', '.') else '.'

    def _current_vid_prep_file_prefix_text(self):
        """Return the current file prefix text from the combo box or cached state."""
        if hasattr(self, 'vid_prep_file_prefix_input'):
            current = (self.vid_prep_file_prefix_input.currentText() or '').strip()
            if current or self.vid_prep_file_prefix_input.count() >= 0:
                return current
        return (getattr(self, 'vid_prep_file_prefix', '') or '').strip()

    def _load_vid_prep_file_prefix_history_setting(self):
        """Load persisted prefix history as up to 20 unique items."""
        raw_value = self.account_manager.get_setting('vid_prep_file_prefix_history', '[]')
        try:
            parsed = json.loads(raw_value)
        except Exception:
            return []

        if not isinstance(parsed, list):
            return []

        history = []
        seen = set()
        for value in parsed:
            prefix = str(value or '').strip()
            if not prefix:
                continue
            key = prefix.lower()
            if key in seen:
                continue
            seen.add(key)
            history.append(prefix)
            if len(history) >= 20:
                break
        return history

    def _save_vid_prep_file_prefix_history_setting(self):
        """Persist the current prefix history list."""
        history = getattr(self, 'vid_prep_file_prefix_history', [])[:20]
        self.account_manager.set_setting('vid_prep_file_prefix_history', json.dumps(history))

    def _update_vid_prep_file_prefix_history(self, prefix_text):
        """Move the given prefix to the top of the remembered history."""
        prefix = (prefix_text or '').strip()
        if not prefix:
            return

        history = [entry for entry in getattr(self, 'vid_prep_file_prefix_history', []) if entry.strip().lower() != prefix.lower()]
        history.insert(0, prefix)
        self.vid_prep_file_prefix_history = history[:20]
        self._save_vid_prep_file_prefix_history_setting()

        if hasattr(self, 'vid_prep_file_prefix_input'):
            current_text = self._current_vid_prep_file_prefix_text()
            self.vid_prep_file_prefix_input.blockSignals(True)
            self.vid_prep_file_prefix_input.clear()
            self.vid_prep_file_prefix_input.addItems(self.vid_prep_file_prefix_history)
            self.vid_prep_file_prefix_input.setCurrentText(current_text)
            self.vid_prep_file_prefix_input.blockSignals(False)

    def _set_vid_prep_file_prefix_text(self, prefix_text, update_history=False):
        """Set the file prefix field and optionally remember it."""
        prefix = (prefix_text or '').strip()
        self.vid_prep_file_prefix = prefix
        if hasattr(self, 'vid_prep_file_prefix_input'):
            self.vid_prep_file_prefix_input.blockSignals(True)
            self.vid_prep_file_prefix_input.setCurrentText(prefix)
            self.vid_prep_file_prefix_input.blockSignals(False)
        if update_history and prefix:
            self._update_vid_prep_file_prefix_history(prefix)

    def _reset_vid_prep_filename_parts_for_new_source(self):
        """Reset filename fields when a new source video is loaded."""
        self._set_vid_prep_file_prefix_text('', update_history=False)

        if hasattr(self, 'vid_prep_file_index_combo'):
            self.vid_prep_file_index_combo.blockSignals(True)
            self.vid_prep_file_index_combo.setCurrentText('01')
            self.vid_prep_file_index_combo.blockSignals(False)
        self.vid_prep_file_index = '01'

        if hasattr(self, 'vid_prep_modifier_combo'):
            self.vid_prep_modifier_combo.blockSignals(True)
            self.vid_prep_modifier_combo.setCurrentText('[NOTHING]')
            self.vid_prep_modifier_combo.blockSignals(False)
        self.vid_prep_modifier = '[NOTHING]'

        self.account_manager.set_setting('vid_prep_file_prefix', self.vid_prep_file_prefix)
        self.account_manager.set_setting('vid_prep_file_index', self.vid_prep_file_index)
        self.account_manager.set_setting('vid_prep_modifier', self.vid_prep_modifier)
        self.save_ui_setting('vid_prep_file_prefix', self.vid_prep_file_prefix)
        self.save_ui_setting('vid_prep_file_index', self.vid_prep_file_index)
        self.save_ui_setting('vid_prep_modifier', self.vid_prep_modifier)

    def _increment_vid_prep_file_index(self):
        """Advance file index after successful save, capped at 20."""
        current = self._current_vid_prep_file_index()
        try:
            value = int(current)
        except ValueError:
            value = 1
        next_value = min(20, max(1, value + 1))
        next_text = f"{next_value:02d}"

        if hasattr(self, 'vid_prep_file_index_combo'):
            self.vid_prep_file_index_combo.setCurrentText(next_text)
        self.vid_prep_file_index = next_text
        self.account_manager.set_setting('vid_prep_file_index', self.vid_prep_file_index)
        self.save_ui_setting('vid_prep_file_index', self.vid_prep_file_index)

    def increment_vid_prep_file_index(self):
        """User-triggered increment of file index (button handler)."""
        self._increment_vid_prep_file_index()
        if self.vid_prep_source_path:
            self.regenerate_vid_prep_output_filename()

    def decrement_vid_prep_file_index(self):
        """Decrement file index (button handler)."""
        current = self._current_vid_prep_file_index()
        try:
            value = int(current)
        except ValueError:
            value = 1
        prev_value = max(1, min(20, value - 1))
        prev_text = f"{prev_value:02d}"

        if hasattr(self, 'vid_prep_file_index_combo'):
            self.vid_prep_file_index_combo.setCurrentText(prev_text)
        self.vid_prep_file_index = prev_text
        self.account_manager.set_setting('vid_prep_file_index', self.vid_prep_file_index)
        self.save_ui_setting('vid_prep_file_index', self.vid_prep_file_index)

        if self.vid_prep_source_path:
            self.regenerate_vid_prep_output_filename()

    def delete_vid_prep_generated_filename(self):
        """Delete current generated output file and matching Vid Prep database record."""
        target_path = None

        if self.vid_prep_source_path:
            try:
                target_path = self._build_vid_prep_output_path(self.vid_prep_source_path)
            except Exception:
                target_path = None

        if target_path is None and self.vid_prep_saved_output_path:
            target_path = Path(self.vid_prep_saved_output_path)

        if target_path is None:
            QMessageBox.information(self, "Vid Prep", "No generated output target is available to delete yet.")
            return

        response = QMessageBox.question(
            self,
            "Delete Vid Prep Output",
            f"Delete this output file and its Vid Prep metadata?\n\n{target_path}\n\nSource media will NOT be deleted.",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        if response != QMessageBox.Yes:
            return

        removed_file = False
        removed_record = False

        try:
            if target_path.exists():
                if self.vid_prep_last_output_path and os.path.normcase(str(self.vid_prep_last_output_path)) == os.path.normcase(str(target_path)):
                    self.vid_prep_output_player.stop()
                    self.vid_prep_output_player.setMedia(QMediaContent())
                    if hasattr(self, 'vid_prep_output_display_stack') and hasattr(self, 'vid_prep_output_placeholder'):
                        self.vid_prep_output_display_stack.setCurrentWidget(self.vid_prep_output_placeholder)
                target_path.unlink()
                removed_file = True
        except Exception as e:
            QMessageBox.warning(self, "Vid Prep", f"Failed to delete file:\n{target_path}\n\n{e}")
            return

        try:
            if (not self.content_db or not getattr(self.content_db, 'db', None)) and self.current_username:
                self.content_db = ContentDatabaseManager(str(config.DATA_DIR), self.current_username)
            if self.content_db and getattr(self.content_db, 'db', None):
                removed_record = bool(self.content_db.db.delete_video_output_record(str(target_path), account_name=self.current_username))
        except Exception as e:
            logger.error(f"Failed deleting Vid Prep DB record for {target_path}: {e}")
            QMessageBox.warning(self, "Vid Prep", f"File deletion succeeded, but metadata deletion failed:\n{e}")

        if self.vid_prep_saved_output_path and os.path.normcase(str(self.vid_prep_saved_output_path)) == os.path.normcase(str(target_path)):
            self.vid_prep_saved_output_path = None
            self.vid_prep_last_output_path = None
            self.vid_prep_open_saved_btn.setEnabled(False)
            self._set_vid_prep_output_media(None)
            self._set_vid_prep_output_preview_dirty(True)

        if removed_file and removed_record:
            self.vid_prep_status.setText(f"Deleted output file and metadata: {target_path}")
        elif removed_file:
            self.vid_prep_status.setText(f"Deleted output file: {target_path}")
        elif removed_record:
            self.vid_prep_status.setText(f"Deleted output metadata record: {target_path}")
        else:
            self.vid_prep_status.setText(f"Nothing to delete for: {target_path}")

    def _get_vid_prep_output_directory(self, source_path):
        """Resolve output directory from UI mode settings."""
        src = Path(source_path)
        if self.vid_prep_output_folder_mode == 'default_video_output':
            default_root = self._get_vid_prep_default_video_output_root()
            if default_root:
                return default_root
            raise ValueError("Default Video Output is selected, but the Default Video Output setting is blank.")

        if self.vid_prep_output_folder_mode == 'dvo_topic':
            default_root = self._get_vid_prep_default_video_output_root()
            if not default_root:
                raise ValueError("DVO/Topic is selected, but the Default Video Output setting is blank.")

            topic_rel = self._get_vid_prep_topic_relative_path()
            if not topic_rel:
                raise ValueError("DVO/Topic is selected, but no topic path is available to append. Select a topic first.")

            # Normalize selected topic path before appending to the configured video root.
            topic_parts = list(topic_rel.parts)
            while topic_parts and topic_parts[0].lower() == 'topics':
                topic_parts = topic_parts[1:]
            normalized_topic_rel = Path(*topic_parts) if topic_parts else Path('.')

            return default_root if str(normalized_topic_rel) == '.' else (default_root / normalized_topic_rel)

        if self.vid_prep_output_folder_mode == 'user_specified':
            folder = (self.vid_prep_output_folder_path_input.text() or '').strip()
            if folder:
                return Path(folder)
        return src.parent

    def _generate_vid_prep_output_filename(self, source_path):
        """Generate output filename as TOPIC[sep][PREFIX[sep]]INDEX[sep]MODIFIER[sep]SHORTCODE.ext."""
        src = Path(source_path)
        ext = src.suffix.lstrip('.')
        separator = self._current_vid_prep_separator()

        topic = self._sanitize_vid_prep_filename_token(self._get_vid_prep_topic_filename_prefix_text(), 'TOPIC')

        prefix_text = self._current_vid_prep_file_prefix_text()
        file_prefix = self._sanitize_vid_prep_filename_token(prefix_text, '')

        file_index = self._current_vid_prep_file_index()

        modifier_value = self._current_vid_prep_modifier()
        modifier = '' if modifier_value == '[NOTHING]' else self._sanitize_vid_prep_filename_token(modifier_value, '')

        shortcode = self._sanitize_vid_prep_filename_token(self._extract_vid_prep_shortcode(source_path), 'unknown')

        parts = [topic]
        if file_prefix:
            parts.append(file_prefix)
        parts.append(file_index)
        if modifier:
            parts.append(modifier)
        parts.append(shortcode)

        base_name = separator.join([part for part in parts if part])
        if ext:
            return f"{base_name}.{ext}"
        return base_name

    def _get_vid_prep_topic_filename_prefix_text(self):
        """Return a stable topic prefix text for generated output filenames."""
        # Prefer resolved topic data so topic-name collisions and manual path text still map cleanly.
        topic_data = self._get_vid_prep_selected_topic_data()
        if topic_data:
            topic_name = (topic_data.get('topic_name') or '').strip()
            if topic_name:
                return topic_name

        topic_text = (self.vid_prep_selected_topic_input.text() if hasattr(self, 'vid_prep_selected_topic_input') else self.vid_prep_selected_topic_name) or ''
        topic_text = topic_text.strip()
        if not topic_text:
            return ''

        # If user enters a tree path directly, use the leaf topic for filename prefix.
        if '/' in topic_text or '\\' in topic_text:
            sanitized_path, is_absolute = self.sanitize_topic_path(topic_text)
            if sanitized_path:
                topic_path = Path(sanitized_path)
                if is_absolute:
                    return topic_path.name
                return topic_path.parts[-1] if topic_path.parts else topic_text

        return topic_text

    def regenerate_vid_prep_output_filename(self):
        """Regenerate filename from current source and settings."""
        if not self.vid_prep_source_path:
            self.vid_prep_output_filename_input.setText("")
            self.update_vid_prep_output_filename_preview()
            return
        generated_name = self._generate_vid_prep_output_filename(self.vid_prep_source_path)
        self.vid_prep_output_filename_input.setText(generated_name)
        self.update_vid_prep_output_filename_preview()

    def on_vid_prep_prepend_topic_toggled(self, checked):
        """Persist prepend-topic preference and regenerate filename."""
        self.vid_prep_prepend_topic_enabled = bool(checked)
        self.account_manager.set_setting('vid_prep_prepend_topic_filename', 'true' if checked else 'false')
        self.save_ui_setting('vid_prep_prepend_topic_filename', 'true' if checked else 'false')
        self.regenerate_vid_prep_output_filename()

    def on_vid_prep_selected_topic_changed(self, topic_text):
        """Persist selected topic text and refresh generated filename/path."""
        self.vid_prep_selected_topic_name = (topic_text or '').strip()
        self.account_manager.set_setting('vid_prep_selected_topic', self.vid_prep_selected_topic_name)
        self.save_ui_setting('vid_prep_selected_topic', self.vid_prep_selected_topic_name)
        self.update_vid_prep_output_filename_preview()
        if self.vid_prep_source_path:
            self.regenerate_vid_prep_output_filename()

    def on_vid_prep_file_prefix_changed(self, prefix_text):
        """Persist file prefix and regenerate output filename."""
        self._set_vid_prep_file_prefix_text(prefix_text, update_history=True)
        self.account_manager.set_setting('vid_prep_file_prefix', self.vid_prep_file_prefix)
        self.save_ui_setting('vid_prep_file_prefix', self.vid_prep_file_prefix)
        if self.vid_prep_source_path:
            self.regenerate_vid_prep_output_filename()
        else:
            self.update_vid_prep_output_filename_preview()

    def on_vid_prep_file_index_changed(self, index_text):
        """Persist file index and regenerate output filename."""
        text = (index_text or '').strip()
        self.vid_prep_file_index = text if text else '01'
        self.account_manager.set_setting('vid_prep_file_index', self.vid_prep_file_index)
        self.save_ui_setting('vid_prep_file_index', self.vid_prep_file_index)
        if self.vid_prep_source_path:
            self.regenerate_vid_prep_output_filename()
        else:
            self.update_vid_prep_output_filename_preview()

    def on_vid_prep_modifier_changed(self, modifier_text):
        """Persist modifier and regenerate output filename."""
        self.vid_prep_modifier = (modifier_text or '').strip() or '[NOTHING]'
        self.account_manager.set_setting('vid_prep_modifier', self.vid_prep_modifier)
        self.save_ui_setting('vid_prep_modifier', self.vid_prep_modifier)
        if self.vid_prep_source_path:
            self.regenerate_vid_prep_output_filename()
        else:
            self.update_vid_prep_output_filename_preview()

    def on_vid_prep_separator_changed(self, separator_text):
        """Persist separator and regenerate output filename."""
        sep = (separator_text or '').strip()
        self.vid_prep_separator = sep if sep in ('-', '_', '.') else '.'
        self.account_manager.set_setting('vid_prep_separator', self.vid_prep_separator)
        self.save_ui_setting('vid_prep_separator', self.vid_prep_separator)
        if self.vid_prep_source_path:
            self.regenerate_vid_prep_output_filename()
        else:
            self.update_vid_prep_output_filename_preview()

    def pick_vid_prep_topic(self):
        """Open a topic picker dialog and set selected topic for filename prefixing."""
        if not self.content_db or not self.content_db.db:
            QMessageBox.information(self, "Vid Prep", "Topics database is not available.")
            return

        try:
            topics = self.content_db.db.get_all_topics() or []
        except Exception as e:
            QMessageBox.warning(self, "Vid Prep", f"Failed to load topics:\n{e}")
            return

        topic_names = sorted({(t.get('topic_name') or '').strip() for t in topics if t.get('topic_name')})
        if not topic_names:
            QMessageBox.information(self, "Vid Prep", "No topics found. Create topics first.")
            return

        current = (self.vid_prep_selected_topic_input.text() or '').strip() if hasattr(self, 'vid_prep_selected_topic_input') else ''
        start_index = topic_names.index(current) if current in topic_names else 0
        chosen_name, ok = QInputDialog.getItem(
            self,
            "Select Topic",
            "Choose topic to prepend to generated filename:",
            topic_names,
            start_index,
            False,
        )
        if ok and chosen_name:
            self.vid_prep_selected_topic_input.setText(chosen_name)

    def on_vid_prep_output_folder_mode_changed(self, mode_text):
        """Persist output folder mode and update path field availability."""
        mode_map = {
            "Same as input": 'same_as_input',
            "User specified": 'user_specified',
            "Default Video Output": 'default_video_output',
            "DVO/Topic": 'dvo_topic',
        }
        self.vid_prep_output_folder_mode = mode_map.get(mode_text, 'same_as_input')
        self.account_manager.set_setting('vid_prep_output_folder_mode', self.vid_prep_output_folder_mode)
        self.save_ui_setting('vid_prep_output_folder_mode', self.vid_prep_output_folder_mode)
        user_specified = self.vid_prep_output_folder_mode == 'user_specified'
        self.vid_prep_output_folder_path_input.setEnabled(user_specified)
        self.vid_prep_output_folder_browse_btn.setEnabled(user_specified)
        self.regenerate_vid_prep_output_filename()

    def on_vid_prep_output_folder_path_changed(self, folder_path):
        """Persist custom output folder path while typing."""
        self.vid_prep_output_folder_path = folder_path.strip()
        self.account_manager.set_setting('vid_prep_output_folder_path', self.vid_prep_output_folder_path)
        self.save_ui_setting('vid_prep_output_folder_path', self.vid_prep_output_folder_path)
        self.update_vid_prep_output_filename_preview()

    def browse_vid_prep_output_folder(self):
        """Browse for custom output folder."""
        folder = QFileDialog.getExistingDirectory(self, "Select Output Folder", self.vid_prep_output_folder_path or "")
        if folder:
            self.vid_prep_output_folder_path_input.setText(folder)
            self.on_vid_prep_output_folder_path_changed(folder)
            self.regenerate_vid_prep_output_filename()

    def _format_vid_prep_time(self, seconds):
        """Format seconds as mm:ss.mmm for timeline labels."""
        seconds = max(0.0, float(seconds))
        minutes = int(seconds // 60)
        rem = seconds - (minutes * 60)
        return f"{minutes:02d}:{rem:06.3f}"

    def _format_vid_prep_source_timeline_label(self, current_frame: int, total_frames: int) -> str:
        """Format source timeline label with time and frame counter."""
        total_frames = max(0, int(total_frames or 0))
        current_frame = max(0, int(current_frame or 0))

        if total_frames > 0:
            current_frame = min(current_frame, total_frames - 1)
            current_display = current_frame + 1
        else:
            current_display = 0

        current_s = self._vid_prep_frame_to_seconds(current_frame)
        total_s = max(0.0, float(self.vid_prep_duration_s or 0.0))
        return (
            f"{self._format_vid_prep_time(current_s)} / {self._format_vid_prep_time(total_s)}"
            f"  |  Frame {current_display}/{total_frames}"
        )

    def _format_vid_prep_output_timeline_label(self, position_ms: int, duration_ms: int) -> str:
        """Format output timeline label with time and frame counter."""
        position_ms = max(0, int(position_ms or 0))
        duration_ms = max(0, int(duration_ms or 0))
        current_s = position_ms / 1000.0
        total_s = duration_ms / 1000.0

        # Output playback does not expose frame index directly; estimate from timeline + source fps.
        fps = max(1.0, float(self.vid_prep_fps or 30.0))
        total_frames = max(0, int(round(total_s * fps)))
        if total_frames > 0:
            current_frame = max(0, min(int(round(current_s * fps)), total_frames - 1))
            current_display = current_frame + 1
        else:
            current_display = 0

        return (
            f"{self._format_vid_prep_time(current_s)} / {self._format_vid_prep_time(total_s)}"
            f"  |  Frame {current_display}/{total_frames}"
        )

    def _release_vid_prep_capture(self):
        """Release existing OpenCV capture if present."""
        if self.vid_prep_cap is not None:
            try:
                self.vid_prep_cap.release()
            except Exception:
                pass
            self.vid_prep_cap = None

    def _get_cv2_for_vid_prep(self):
        """Import cv2 for Vid Prep features. Returns module or None if unavailable."""
        try:
            import cv2
            return cv2
        except ModuleNotFoundError:
            QMessageBox.warning(
                self,
                "Vid Prep",
                "OpenCV (cv2) is not installed.\n\n"
                "Install opencv-python to enable frame scrubbing and crop preview."
            )
            self.vid_prep_status.setText("OpenCV not installed. Install opencv-python to use crop preview.")
            return None

    def update_vid_prep_output_filename_preview(self):
        """Update live output path preview and keep filename editable."""
        if not self.vid_prep_source_path:
            self.vid_prep_output_preview_label.setText("Output path: (drop a source video first)")
            return

        try:
            preview_path = self._build_vid_prep_output_path(self.vid_prep_source_path)
            self.vid_prep_output_preview_label.setText(f"Output path: {preview_path}")
        except Exception as e:
            self.vid_prep_output_preview_label.setText(f"Output path: (error: {e})")

    def on_vid_prep_output_duration_changed(self, duration_ms):
        """Keep the output scrubber and duration label in sync."""
        duration_ms = max(0, int(duration_ms))
        self.vid_prep_output_scrubber.blockSignals(True)
        self.vid_prep_output_scrubber.setRange(0, duration_ms)
        self.vid_prep_output_scrubber.blockSignals(False)
        self.vid_prep_output_time_label.setText(
            self._format_vid_prep_output_timeline_label(0, duration_ms)
        )

    def on_vid_prep_output_position_changed(self, position_ms):
        """Refresh the output scrubber position while playing."""
        position_ms = max(0, int(position_ms))
        if not self.vid_prep_output_scrubber.isSliderDown():
            self.vid_prep_output_scrubber.blockSignals(True)
            self.vid_prep_output_scrubber.setValue(position_ms)
            self.vid_prep_output_scrubber.blockSignals(False)
        duration_ms = max(0, self.vid_prep_output_scrubber.maximum())
        self.vid_prep_output_time_label.setText(self._format_vid_prep_output_timeline_label(position_ms, duration_ms))

    def seek_vid_prep_output(self, position_ms):
        """Seek the output preview player to a new position."""
        if self.vid_prep_output_player is not None:
            self.vid_prep_output_player.setPosition(int(position_ms))

    def step_vid_prep_source_frames(self, frame_delta):
        """Step source timeline by a signed number of frames."""
        if not hasattr(self, 'vid_prep_scrubber'):
            return
        if self.vid_prep_cap is None or self.vid_prep_frame_count <= 0:
            return

        try:
            delta = int(frame_delta)
        except (TypeError, ValueError):
            return

        current = int(self.vid_prep_scrubber.value())
        target = max(0, min(self.vid_prep_frame_count - 1, current + delta))
        if target == current:
            return

        self.vid_prep_scrubber.setValue(target)

        # If playback is active, re-anchor timing to current frame after jump.
        if self.vid_prep_play_timer.isActive():
            self.vid_prep_play_start_time = time.monotonic()
            self.vid_prep_play_start_frame = int(self.vid_prep_scrubber.value())

    def step_vid_prep_source_seconds(self, seconds_delta):
        """Step source timeline by a signed number of seconds."""
        fps = max(1.0, float(self.vid_prep_fps or 30.0))
        frames = int(round(float(seconds_delta) * fps))
        if frames == 0 and seconds_delta != 0:
            frames = 1 if seconds_delta > 0 else -1
        self.step_vid_prep_source_frames(frames)

    def reset_vid_prep_source_to_first_frame(self):
        """Reset source timeline to frame 0."""
        if not hasattr(self, 'vid_prep_scrubber'):
            return
        self.vid_prep_scrubber.setValue(0)
        if self.vid_prep_play_timer.isActive():
            self.vid_prep_play_start_time = time.monotonic()
            self.vid_prep_play_start_frame = 0

    def jump_vid_prep_source_to_last_frame(self):
        """Jump source timeline to the final frame."""
        if not hasattr(self, 'vid_prep_scrubber') or self.vid_prep_frame_count <= 0:
            return

        last_frame = max(0, self.vid_prep_frame_count - 1)
        self.vid_prep_scrubber.setValue(last_frame)
        if self.vid_prep_play_timer.isActive():
            self.vid_prep_play_start_time = time.monotonic()
            self.vid_prep_play_start_frame = last_frame

    def jump_vid_prep_source_to_trim_in(self):
        """Move source timeline marker to current Trim In frame."""
        if not hasattr(self, 'vid_prep_scrubber') or self.vid_prep_frame_count <= 0:
            self.vid_prep_status.setText("Load a video first, then move to trim in.")
            return

        target = max(0, min(int(self.vid_prep_trim_start_frame), self.vid_prep_frame_count - 1))
        self.vid_prep_scrubber.setValue(target)
        if self.vid_prep_play_timer.isActive():
            self.vid_prep_play_start_time = time.monotonic()
            self.vid_prep_play_start_frame = target

    def jump_vid_prep_source_to_trim_out(self):
        """Move source timeline marker to current Trim Out frame."""
        if not hasattr(self, 'vid_prep_scrubber') or self.vid_prep_frame_count <= 0:
            self.vid_prep_status.setText("Load a video first, then move to trim out.")
            return

        target = max(0, min(int(self.vid_prep_trim_end_frame), self.vid_prep_frame_count - 1))
        self.vid_prep_scrubber.setValue(target)
        if self.vid_prep_play_timer.isActive():
            self.vid_prep_play_start_time = time.monotonic()
            self.vid_prep_play_start_frame = target

    def on_vid_prep_input_volume_changed(self, value):
        """Adjust input preview audio volume."""
        if self.vid_prep_input_audio_player is not None:
            self.vid_prep_input_audio_player.setVolume(int(value))
        if hasattr(self, 'vid_prep_music_preview_player') and self.vid_prep_music_preview_player is not None:
            self.vid_prep_music_preview_player.setVolume(int(value))
        self.save_ui_setting('vid_prep_input_volume', str(int(value)))

    def on_vid_prep_input_mute_toggled(self, muted):
        """Mute/unmute input preview audio."""
        if self.vid_prep_input_audio_player is not None:
            self.vid_prep_input_audio_player.setMuted(bool(muted))
        if hasattr(self, 'vid_prep_music_preview_player') and self.vid_prep_music_preview_player is not None:
            self.vid_prep_music_preview_player.setMuted(bool(muted))
        self.vid_prep_input_mute_btn.setText("🔈 Unmute" if muted else "🔇 Mute")
        self.save_ui_setting('vid_prep_input_muted', 'true' if muted else 'false')

    def on_vid_prep_output_volume_changed(self, value):
        """Adjust output preview audio volume."""
        if self.vid_prep_output_player is not None:
            self.vid_prep_output_player.setVolume(int(value))

    def on_vid_prep_output_mute_toggled(self, muted):
        """Mute/unmute output preview audio."""
        if self.vid_prep_output_player is not None:
            self.vid_prep_output_player.setMuted(bool(muted))
        self.vid_prep_output_mute_btn.setText("🔈 Unmute" if muted else "🔇 Mute")

    def _vid_prep_set_render_progress(self, visible, label_text="Rendering..."):
        """Show or hide the Vid Prep inline render progress meter."""
        if not hasattr(self, 'vid_prep_render_progress'):
            return
        self.vid_prep_render_progress.setFormat(label_text)
        self.vid_prep_render_progress.setRange(0, 0)
        self.vid_prep_render_progress.setVisible(bool(visible))
        QApplication.processEvents()

    def on_vid_prep_scrubber_changed(self, frame_idx):
        """Seek to the requested frame and update crop preview."""
        cv2 = self._get_cv2_for_vid_prep()
        if cv2 is None:
            return

        if self.vid_prep_cap is None:
            return

        if frame_idx < 0:
            frame_idx = 0

        self.vid_prep_cap.set(cv2.CAP_PROP_POS_FRAMES, frame_idx)
        ok, frame = self.vid_prep_cap.read()
        if not ok or frame is None:
            return

        self._update_vid_prep_source_preview_frame(frame_idx, frame, sync_audio=not self.vid_prep_play_timer.isActive())

    def _update_vid_prep_source_preview_frame(self, frame_idx, frame, sync_audio=False):
        """Render source frame and synchronize timeline labels/widgets."""
        if frame is None:
            return

        if self.vid_prep_frame_count > 0:
            frame_idx = max(0, min(int(frame_idx), self.vid_prep_frame_count - 1))
        else:
            frame_idx = max(0, int(frame_idx))

        self.vid_prep_preview.set_video_frame(frame)

        self.vid_prep_scrubber.blockSignals(True)
        self.vid_prep_scrubber.setValue(frame_idx)
        self.vid_prep_scrubber.blockSignals(False)

        self.vid_prep_time_label.setText(
            self._format_vid_prep_source_timeline_label(frame_idx, self.vid_prep_frame_count)
        )

        if sync_audio and self.vid_prep_input_audio_player is not None:
            current_s = self._vid_prep_frame_to_seconds(frame_idx)
            self.vid_prep_input_audio_player.setPosition(int(current_s * 1000))

    def _set_vid_prep_output_media(self, media_path):
        """Load a media file into the output preview player."""
        if not media_path or not os.path.exists(media_path):
            self.vid_prep_output_player.stop()
            self.vid_prep_output_player.setMedia(QMediaContent())
            if hasattr(self, 'vid_prep_output_image_label'):
                self.vid_prep_output_image_label.clear()
            self._set_vid_prep_output_preview_mode('none')
            if hasattr(self, "vid_prep_output_display_stack") and hasattr(self, "vid_prep_output_placeholder"):
                self.vid_prep_output_display_stack.setCurrentWidget(self.vid_prep_output_placeholder)
            return

        output_kind = self._get_vid_prep_output_kind(media_path)
        if output_kind == 'image':
            self.vid_prep_output_player.stop()
            self.vid_prep_output_player.setMedia(QMediaContent())
            self._show_vid_prep_output_image(media_path)
            self._set_vid_prep_output_preview_mode('image')
            return

        self.vid_prep_output_player.stop()
        self.vid_prep_output_player.setMedia(QMediaContent())
        self.vid_prep_output_player.setMedia(QMediaContent(QUrl.fromLocalFile(media_path)))
        self.vid_prep_output_player.setPosition(0)
        self._set_vid_prep_output_preview_mode('video')
        if hasattr(self, "vid_prep_output_display_stack"):
            self.vid_prep_output_display_stack.setCurrentWidget(self.vid_prep_output_video_widget)

    def _get_vid_prep_output_kind(self, media_path):
        """Return output kind based on file extension."""
        suffix = Path(str(media_path or '')).suffix.lower()
        if suffix in ('.png', '.jpg', '.jpeg', '.webp', '.bmp', '.gif', '.tif', '.tiff'):
            return 'image'
        return 'video'

    def _set_vid_prep_output_preview_mode(self, mode):
        """Adjust output controls for placeholder, image, or video preview."""
        is_video = mode == 'video'
        if hasattr(self, 'vid_prep_output_play_btn'):
            self.vid_prep_output_play_btn.setEnabled(is_video)
        if hasattr(self, 'vid_prep_output_pause_btn'):
            self.vid_prep_output_pause_btn.setEnabled(is_video)
            self.vid_prep_output_pause_btn.setText('⏸ Pause')
        if hasattr(self, 'vid_prep_output_stop_btn'):
            self.vid_prep_output_stop_btn.setEnabled(is_video)
        if hasattr(self, 'vid_prep_output_scrubber'):
            self.vid_prep_output_scrubber.setEnabled(is_video)
            if not is_video:
                self.vid_prep_output_scrubber.blockSignals(True)
                self.vid_prep_output_scrubber.setRange(0, 0)
                self.vid_prep_output_scrubber.setValue(0)
                self.vid_prep_output_scrubber.blockSignals(False)
        if hasattr(self, 'vid_prep_output_volume_slider'):
            self.vid_prep_output_volume_slider.setEnabled(is_video)
        if hasattr(self, 'vid_prep_output_mute_btn'):
            self.vid_prep_output_mute_btn.setEnabled(is_video)
        if hasattr(self, 'vid_prep_output_time_label') and not is_video:
            self.vid_prep_output_time_label.setText('Still image output')

    def _show_vid_prep_output_image(self, image_path):
        """Display a still-image output in the Vid Prep output preview area."""
        if not hasattr(self, 'vid_prep_output_image_label') or not hasattr(self, 'vid_prep_output_display_stack'):
            return

        pixmap = QPixmap(str(image_path))
        if pixmap.isNull():
            self.vid_prep_output_image_label.clear()
            self.vid_prep_output_display_stack.setCurrentWidget(self.vid_prep_output_placeholder)
            return

        target_size = self.vid_prep_output_image_label.size()
        if target_size.width() <= 0 or target_size.height() <= 0:
            target_size = self.vid_prep_output_display_stack.size()
        scaled = pixmap.scaled(target_size, Qt.KeepAspectRatio, Qt.SmoothTransformation)
        self.vid_prep_output_image_label.setPixmap(scaled)
        self.vid_prep_output_display_stack.setCurrentWidget(self.vid_prep_output_image_label)

    def play_vid_prep_source(self):
        """Play the source clip inside the input viewer/cropper."""
        if not self.vid_prep_source_path or self.vid_prep_cap is None:
            QMessageBox.information(self, "Vid Prep", "No source video loaded.")
            return

        if self.vid_prep_play_timer.isActive():
            return

        source_end = max(0, self.vid_prep_frame_count - 1)
        current_frame = int(self.vid_prep_scrubber.value())
        # If the marker is at the end, Play should restart from the beginning.
        if self.vid_prep_frame_count > 0 and current_frame >= source_end:
            self.reset_vid_prep_source_to_first_frame()

        interval_ms = max(15, int(1000 / max(1.0, self.vid_prep_fps)))
        self.vid_prep_play_start_time = time.monotonic()
        self.vid_prep_play_start_frame = int(self.vid_prep_scrubber.value())
        if self.vid_prep_input_audio_player is not None:
            self.vid_prep_input_audio_player.setPosition(int(self._vid_prep_frame_to_seconds(self.vid_prep_scrubber.value()) * 1000))
            self.vid_prep_input_audio_player.play()
        self.vid_prep_play_timer.start(interval_ms)
        if hasattr(self, 'vid_prep_source_pause_btn'):
            self.vid_prep_source_pause_btn.setText("⏸ Pause")
        self.vid_prep_status.setText("Playing source in cropper view.")

    def toggle_vid_prep_source_pause_resume(self):
        """Toggle source playback between paused and resumed states."""
        if self.vid_prep_play_timer.isActive():
            self.pause_vid_prep_source()
            return

        if not self.vid_prep_source_path or self.vid_prep_cap is None:
            QMessageBox.information(self, "Vid Prep", "No source video loaded.")
            return

        self.play_vid_prep_source()

    def pause_vid_prep_source(self):
        """Pause the source clip playback."""
        if self.vid_prep_play_timer.isActive():
            self.vid_prep_play_timer.stop()
            if self.vid_prep_input_audio_player is not None:
                self.vid_prep_input_audio_player.pause()
            self.vid_prep_play_start_time = None
            if hasattr(self, 'vid_prep_source_pause_btn'):
                self.vid_prep_source_pause_btn.setText("▶ Resume")
            self.vid_prep_status.setText("Source playback paused.")

    def stop_vid_prep_source(self):
        """Stop source playback and return to the first frame."""
        if self.vid_prep_play_timer.isActive():
            self.vid_prep_play_timer.stop()
        if self.vid_prep_input_audio_player is not None:
            self.vid_prep_input_audio_player.stop()
        self.vid_prep_play_start_time = None
        self.vid_prep_play_start_frame = 0
        if self.vid_prep_cap is not None:
            self.vid_prep_scrubber.blockSignals(True)
            self.vid_prep_scrubber.setValue(0)
            self.vid_prep_scrubber.blockSignals(False)
            self.on_vid_prep_scrubber_changed(0)
        if hasattr(self, 'vid_prep_source_pause_btn'):
            self.vid_prep_source_pause_btn.setText("⏸ Pause")
        self.vid_prep_status.setText("Source playback stopped.")

    def on_vid_prep_source_loop_toggled(self, enabled):
        """Enable/disable source playback loop behavior."""
        self.vid_prep_source_loop_enabled = bool(enabled)
        self.vid_prep_source_loop_btn.setText("🔁 Loop On" if enabled else "🔁 Loop Off")
        self.vid_prep_status.setText("Source loop enabled." if enabled else "Source loop disabled.")

    def _advance_vid_prep_source_frame(self):
        """Advance source preview in real time; skip frames when behind to keep A/V sync."""
        if self.vid_prep_cap is None:
            self.vid_prep_play_timer.stop()
            return

        current_frame = int(self.vid_prep_scrubber.value())
        source_end = max(0, self.vid_prep_frame_count - 1)
        fps = max(1.0, float(self.vid_prep_fps or 30.0))

        # Use input audio clock when available; otherwise fall back to wall-clock.
        target_frame = current_frame + 1
        if self.vid_prep_input_audio_player is not None and self.vid_prep_input_audio_player.state() == QMediaPlayer.PlayingState:
            target_seconds = max(0.0, self.vid_prep_input_audio_player.position() / 1000.0)
            target_frame = int(round(target_seconds * fps))
        elif self.vid_prep_play_start_time is not None:
            elapsed = max(0.0, time.monotonic() - self.vid_prep_play_start_time)
            target_frame = int(self.vid_prep_play_start_frame + round(elapsed * fps))

        if target_frame <= current_frame:
            return

        if target_frame > source_end:
            if self.vid_prep_source_loop_enabled and self.vid_prep_frame_count > 0:
                cv2 = self._get_cv2_for_vid_prep()
                if cv2 is None:
                    self.stop_vid_prep_source()
                    return
                self.vid_prep_cap.set(cv2.CAP_PROP_POS_FRAMES, 0)
                ok, frame = self.vid_prep_cap.read()
                if not ok or frame is None:
                    self.stop_vid_prep_source()
                    return
                self.vid_prep_play_start_time = time.monotonic()
                self.vid_prep_play_start_frame = 0
                if self.vid_prep_input_audio_player is not None:
                    self.vid_prep_input_audio_player.setPosition(0)
                    self.vid_prep_input_audio_player.play()
                self._update_vid_prep_source_preview_frame(0, frame, sync_audio=False)
                return

            # End-of-playback should behave the same as pressing Stop.
            self.stop_vid_prep_source()
            return

        if target_frame > current_frame + 1:
            cv2 = self._get_cv2_for_vid_prep()
            if cv2 is None:
                self.stop_vid_prep_source()
                return
            self.vid_prep_cap.set(cv2.CAP_PROP_POS_FRAMES, target_frame)

        ok, frame = self.vid_prep_cap.read()
        if not ok or frame is None:
            self.vid_prep_play_timer.stop()
            if self.vid_prep_input_audio_player is not None:
                self.vid_prep_input_audio_player.pause()
            self.vid_prep_status.setText("Playback stopped: could not decode next frame.")
            return

        self._update_vid_prep_source_preview_frame(target_frame, frame, sync_audio=False)

    def show_vid_prep_output_preview(self):
        """Show last exported output video in preview player."""
        if self.vid_prep_output_preview_dirty or not self.vid_prep_last_output_path or not os.path.exists(self.vid_prep_last_output_path):
            self.preview_vid_prep_output()
            return
        self._set_vid_prep_output_media(self.vid_prep_last_output_path)
        self.vid_prep_output_scrubber.blockSignals(True)
        self.vid_prep_output_scrubber.setValue(0)
        self.vid_prep_output_scrubber.blockSignals(False)
        self.vid_prep_output_time_label.setText(
            self._format_vid_prep_output_timeline_label(0, self.vid_prep_output_scrubber.maximum())
        )
        self.vid_prep_output_player.play()

    def on_vid_prep_output_state_changed(self, state):
        """Keep output Pause/Resume button label aligned with playback state."""
        if not hasattr(self, 'vid_prep_output_pause_btn'):
            return
        if state == QMediaPlayer.PausedState:
            self.vid_prep_output_pause_btn.setText("▶ Resume")
        else:
            self.vid_prep_output_pause_btn.setText("⏸ Pause")

    def toggle_vid_prep_output_pause_resume(self):
        """Toggle output preview between pause and resume."""
        if self.vid_prep_output_player is None:
            return

        state = self.vid_prep_output_player.state()
        if state == QMediaPlayer.PlayingState:
            self.vid_prep_output_player.pause()
            return

        if state == QMediaPlayer.PausedState:
            self.vid_prep_output_player.play()
            return

        # If stopped and media exists, resume from current marker; otherwise build/show preview first.
        if self.vid_prep_last_output_path and os.path.exists(self.vid_prep_last_output_path) and not self.vid_prep_output_preview_dirty:
            self.vid_prep_output_player.play()
        else:
            self.show_vid_prep_output_preview()

    def stop_vid_prep_output_preview(self):
        """Stop output playback and reset preview to first frame."""
        if self.vid_prep_output_player is None:
            return
        self.vid_prep_output_player.stop()
        self.vid_prep_output_scrubber.blockSignals(True)
        self.vid_prep_output_scrubber.setValue(0)
        self.vid_prep_output_scrubber.blockSignals(False)
        duration_ms = max(0, self.vid_prep_output_scrubber.maximum())
        self.vid_prep_output_time_label.setText(self._format_vid_prep_output_timeline_label(0, duration_ms))

    def on_vid_prep_file_dropped(self, file_path):
        """Handle video file dropped onto Vid Prep preview."""
        self._reset_vid_prep_filename_parts_for_new_source()
        if hasattr(self, 'vid_prep_video_title_input'):
            self.vid_prep_video_title_input.clear()
        if hasattr(self, 'vid_prep_video_desc_input'):
            self.vid_prep_video_desc_input.clear()
        cv2 = self._get_cv2_for_vid_prep()
        if cv2 is None:
            self._release_vid_prep_capture()
            self.vid_prep_source_path = file_path
            self.vid_prep_crop_rect = None
            self.vid_prep_file_label.setText(f"File: {file_path}")
            self.vid_prep_scrubber.blockSignals(True)
            self.vid_prep_scrubber.setRange(0, 0)
            self.vid_prep_scrubber.setValue(0)
            self.vid_prep_scrubber.blockSignals(False)
            self.vid_prep_time_label.setText(self._format_vid_prep_source_timeline_label(0, 0))
            self.vid_prep_trim_slider.setRange(0, 0)
            self.vid_prep_trim_slider.setValues(0, 0)
            self.update_vid_prep_trim_label()
            self.regenerate_vid_prep_output_filename()
            self.update_vid_prep_output_filename_preview()
            self.vid_prep_preview.set_video_frame(None)
            if self.vid_prep_input_audio_player is not None:
                self.vid_prep_input_audio_player.stop()
            self.vid_prep_saved_output_path = None
            self.load_vid_prep_video_applications(vid_id=None)
            self.vid_prep_open_saved_btn.setEnabled(False)
            self._set_vid_prep_output_media(None)
            self._set_vid_prep_output_preview_dirty(True)
            return

        self._release_vid_prep_capture()
        self.vid_prep_source_path = file_path
        self.vid_prep_crop_rect = None
        self.vid_prep_file_label.setText(f"File: {file_path}")
        if hasattr(self, 'vid_prep_preview'):
            self.vid_prep_preview.clear_crop_selection()

        self.vid_prep_cap = cv2.VideoCapture(file_path)
        if not self.vid_prep_cap or not self.vid_prep_cap.isOpened():
            QMessageBox.warning(self, "Vid Prep", "Could not open video file.")
            self.vid_prep_status.setText("Failed to open video.")
            return

        self.vid_prep_frame_count = int(self.vid_prep_cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
        self.vid_prep_fps = float(self.vid_prep_cap.get(cv2.CAP_PROP_FPS) or 30.0)
        if self.vid_prep_fps <= 0:
            self.vid_prep_fps = 30.0
        self.vid_prep_duration_s = (self.vid_prep_frame_count / self.vid_prep_fps) if self.vid_prep_frame_count > 0 else 0.0
        self.vid_prep_source_w = int(self.vid_prep_cap.get(cv2.CAP_PROP_FRAME_WIDTH) or 0)
        self.vid_prep_source_h = int(self.vid_prep_cap.get(cv2.CAP_PROP_FRAME_HEIGHT) or 0)

        self.vid_prep_scrubber.blockSignals(True)
        self.vid_prep_scrubber.setRange(0, max(0, self.vid_prep_frame_count - 1))
        self.vid_prep_scrubber.setValue(0)
        self.vid_prep_scrubber.blockSignals(False)

        self.vid_prep_trim_slider.setRange(0, max(0, self.vid_prep_frame_count - 1))
        self.vid_prep_trim_slider.setValues(0, max(0, self.vid_prep_frame_count - 1))
        self.vid_prep_trim_start_frame = 0
        self.vid_prep_trim_end_frame = max(0, self.vid_prep_frame_count - 1)
        self.update_vid_prep_trim_label()
        self._sync_vid_prep_track_windows_to_video_length()
        self._refresh_vid_prep_audio_track_list()

        ok, frame = self.vid_prep_cap.read()
        if not ok or frame is None:
            QMessageBox.warning(self, "Vid Prep", "Could not read video preview frame.")
            self.vid_prep_status.setText("Failed to load preview frame.")
            return

        self.vid_prep_preview.set_video_frame(frame, keep_crop=False)
        full_crop_applied = False
        if hasattr(self, 'vid_prep_preview'):
            try:
                full_crop_applied = bool(self.vid_prep_preview.select_full_crop())
            except Exception:
                full_crop_applied = False
        if self.vid_prep_input_audio_player is not None:
            self.vid_prep_input_audio_player.stop()
            self.vid_prep_input_audio_player.setMedia(QMediaContent(QUrl.fromLocalFile(file_path)))
            self.vid_prep_input_audio_player.setVolume(self.vid_prep_input_volume_slider.value())
            self.vid_prep_input_audio_player.setMuted(self.vid_prep_input_mute_btn.isChecked())
        if not full_crop_applied:
            self.vid_prep_crop_label.setText("Crop: (draw selection)")
        self.vid_prep_time_label.setText(self._format_vid_prep_source_timeline_label(0, self.vid_prep_frame_count))
        self.regenerate_vid_prep_output_filename()
        self.update_vid_prep_output_filename_preview()
        self.vid_prep_saved_output_path = None
        self.load_vid_prep_video_applications(vid_id=None)
        self.vid_prep_open_saved_btn.setEnabled(False)
        self._set_vid_prep_output_media(None)
        self._set_vid_prep_output_preview_dirty(True)

    def on_vid_prep_crop_changed(self, x, y, w, h):
        """Update crop state when user adjusts crop selection."""
        self.vid_prep_crop_rect = (x, y, w, h)
        self.vid_prep_crop_label.setText(f"Crop: x={x}, y={y}, w={w}, h={h}")
        if self.vid_prep_output_resolution_combo.currentText() == "Match Crop":
            self.update_vid_prep_resolution_ui()
        self._set_vid_prep_output_preview_dirty(True)

    def apply_vid_prep_full_crop(self):
        """Set crop rectangle to full frame in Vid Prep input preview."""
        if not hasattr(self, 'vid_prep_preview') or not self.vid_prep_preview.select_full_crop():
            self.vid_prep_status.setText("Load a video first, then click Full Crop.")
            return
        self.vid_prep_status.setText("Full-frame crop applied.")

    def _get_vid_prep_current_marker_frame(self):
        """Return current input timeline marker frame, clamped to valid range."""
        if not hasattr(self, 'vid_prep_scrubber'):
            return 0

        frame_idx = int(self.vid_prep_scrubber.value())
        if self.vid_prep_frame_count > 0:
            frame_idx = max(0, min(frame_idx, self.vid_prep_frame_count - 1))
        return frame_idx

    def set_vid_prep_trim_in_at_marker(self):
        """Set trim start to the current input timeline marker."""
        if self.vid_prep_frame_count <= 0:
            self.vid_prep_status.setText("Load a video first, then set trim in.")
            return

        marker_frame = self._get_vid_prep_current_marker_frame()
        new_start = max(0, min(marker_frame, int(self.vid_prep_trim_end_frame)))
        new_end = max(new_start, int(self.vid_prep_trim_end_frame))

        self.vid_prep_trim_slider.setValues(new_start, new_end)
        self.on_vid_prep_trim_range_changed(new_start, new_end)
        self.vid_prep_status.setText(
            f"Trim In set to {self._format_vid_prep_time(self._vid_prep_frame_to_seconds(new_start))}."
        )

    def set_vid_prep_trim_out_at_marker(self):
        """Set trim end to the current input timeline marker."""
        if self.vid_prep_frame_count <= 0:
            self.vid_prep_status.setText("Load a video first, then set trim out.")
            return

        marker_frame = self._get_vid_prep_current_marker_frame()
        new_start = int(self.vid_prep_trim_start_frame)
        new_end = max(new_start, marker_frame)
        if self.vid_prep_frame_count > 0:
            new_end = min(new_end, self.vid_prep_frame_count - 1)

        self.vid_prep_trim_slider.setValues(new_start, new_end)
        self.on_vid_prep_trim_range_changed(new_start, new_end)
        self.vid_prep_status.setText(
            f"Trim Out set to {self._format_vid_prep_time(self._vid_prep_frame_to_seconds(new_end + 1))}."
        )

    def flip_vid_prep_trim_to_tail(self):
        """Set trim start to current trim end, and trim end to the final video frame."""
        if self.vid_prep_frame_count <= 0:
            self.vid_prep_status.setText("Load a video first, then flip trim.")
            return

        video_last_frame = max(0, int(self.vid_prep_frame_count - 1))
        new_start = max(0, min(int(self.vid_prep_trim_end_frame), video_last_frame))
        new_end = video_last_frame

        self.vid_prep_trim_slider.setValues(new_start, new_end)
        self.on_vid_prep_trim_range_changed(new_start, new_end)
        start_time = self._format_vid_prep_time(self._vid_prep_frame_to_seconds(new_start))
        self.vid_prep_status.setText(f"Flip Trim applied. Trim now starts at {start_time} and ends at video end.")

    def reset_vid_prep_trim_to_full_video(self):
        """Reset trim to cover the full loaded video."""
        if self.vid_prep_frame_count <= 0:
            self.vid_prep_status.setText("Load a video first, then reset trim.")
            return

        new_start = 0
        new_end = max(0, int(self.vid_prep_frame_count - 1))
        self.vid_prep_trim_slider.setValues(new_start, new_end)
        self.on_vid_prep_trim_range_changed(new_start, new_end)
        self.vid_prep_status.setText("Trim reset to full video.")

    def _build_vid_prep_output_path(self, source_path, suffix_override=None):
        """Create output path from editable filename + folder settings."""
        src = Path(source_path)
        output_dir = self._get_vid_prep_output_directory(source_path)

        if not output_dir.exists():
            output_dir.mkdir(parents=True, exist_ok=True)

        entered_name = (self.vid_prep_output_filename_input.text() or '').strip() if hasattr(self, 'vid_prep_output_filename_input') else ''
        if not entered_name:
            entered_name = self._generate_vid_prep_output_filename(source_path)
            if hasattr(self, 'vid_prep_output_filename_input'):
                self.vid_prep_output_filename_input.setText(entered_name)

        ext = suffix_override or src.suffix
        ext = ext if str(ext).startswith('.') else f".{ext}"
        entered_path = Path(entered_name)
        entered_stem = entered_path.stem if entered_path.suffix else entered_name
        entered_stem = self._sanitize_vid_prep_filename_component(entered_stem)
        if not entered_stem:
            entered_stem = self._sanitize_vid_prep_filename_component(src.stem) or 'output'
        entered_name = f"{entered_stem}{ext}"

        return output_dir / entered_name

    def _read_vid_prep_frame(self, frame_idx):
        """Read a single source frame by index."""
        cv2 = self._get_cv2_for_vid_prep()
        if cv2 is None or self.vid_prep_cap is None:
            return None

        try:
            frame_idx = int(frame_idx)
        except (TypeError, ValueError):
            frame_idx = 0

        if self.vid_prep_frame_count > 0:
            frame_idx = max(0, min(frame_idx, self.vid_prep_frame_count - 1))
        else:
            frame_idx = max(0, frame_idx)

        self.vid_prep_cap.set(cv2.CAP_PROP_POS_FRAMES, frame_idx)
        ok, frame = self.vid_prep_cap.read()
        if not ok or frame is None:
            return None
        return frame

    def _get_vid_prep_active_crop_rect(self):
        """Resolve the active crop rectangle for current Vid Prep settings."""
        crop = self.vid_prep_crop_rect or self.vid_prep_preview.get_crop_rect_source()
        if not crop:
            raise ValueError('Please draw a crop rectangle first.')

        try:
            crop_x, crop_y, crop_w, crop_h = [int(value) for value in crop]
        except (TypeError, ValueError):
            raise ValueError('Current crop rectangle is invalid.')

        if crop_w <= 0 or crop_h <= 0:
            raise ValueError('Please draw a crop rectangle first.')
        return crop_x, crop_y, crop_w, crop_h

    def _get_vid_prep_background_bgr(self):
        """Resolve the configured background color as a BGR tuple."""
        mode = self.vid_prep_bg_mode.currentText()
        if mode == 'White':
            color = QColor('#ffffff')
        elif mode == 'Custom Color':
            color = QColor(self.vid_prep_bg_color)
        else:
            color = QColor('#000000')

        if not color.isValid():
            color = QColor('#000000')
        return (color.blue(), color.green(), color.red())

    def _read_vid_prep_image_bgr(self, image_path):
        """Read an image file into a BGR frame, preserving Windows Unicode paths."""
        cv2 = self._get_cv2_for_vid_prep()
        if cv2 is None:
            return None
        try:
            import numpy as np
            image_bytes = np.fromfile(str(image_path), dtype=np.uint8)
            if image_bytes.size == 0:
                return None
            return cv2.imdecode(image_bytes, cv2.IMREAD_COLOR)
        except Exception:
            return None

    def _resize_vid_prep_frame_to_fit(self, frame, target_w, target_h):
        """Resize a frame to fit fully within the target dimensions."""
        cv2 = self._get_cv2_for_vid_prep()
        if cv2 is None:
            return frame
        frame_h, frame_w = frame.shape[:2]
        scale = min(target_w / max(1, frame_w), target_h / max(1, frame_h))
        resized_w = max(1, int(round(frame_w * scale)))
        resized_h = max(1, int(round(frame_h * scale)))
        interpolation = cv2.INTER_AREA if scale < 1.0 else cv2.INTER_LINEAR
        return cv2.resize(frame, (resized_w, resized_h), interpolation=interpolation)

    def _resize_vid_prep_frame_to_fill(self, frame, target_w, target_h):
        """Resize a frame to fill the target dimensions, cropping overflow from center."""
        cv2 = self._get_cv2_for_vid_prep()
        if cv2 is None:
            return frame
        frame_h, frame_w = frame.shape[:2]
        scale = max(target_w / max(1, frame_w), target_h / max(1, frame_h))
        resized_w = max(target_w, int(round(frame_w * scale)))
        resized_h = max(target_h, int(round(frame_h * scale)))
        interpolation = cv2.INTER_AREA if scale < 1.0 else cv2.INTER_LINEAR
        resized = cv2.resize(frame, (resized_w, resized_h), interpolation=interpolation)
        start_x = max(0, (resized_w - target_w) // 2)
        start_y = max(0, (resized_h - target_h) // 2)
        return resized[start_y:start_y + target_h, start_x:start_x + target_w].copy()

    def _render_vid_prep_still_output_frame(self, source_frame):
        """Render a still output frame using the same crop, resolution, and background rules as video export."""
        cv2 = self._get_cv2_for_vid_prep()
        if cv2 is None:
            raise ValueError('OpenCV is not available for still export.')

        crop_x, crop_y, crop_w, crop_h = self._get_vid_prep_active_crop_rect()
        frame_h, frame_w = source_frame.shape[:2]
        crop_x = max(0, min(crop_x, frame_w - 1))
        crop_y = max(0, min(crop_y, frame_h - 1))
        crop_w = max(1, min(crop_w, frame_w - crop_x))
        crop_h = max(1, min(crop_h, frame_h - crop_y))

        foreground = source_frame[crop_y:crop_y + crop_h, crop_x:crop_x + crop_w].copy()
        target_w, target_h = self._get_vid_prep_output_dimensions(crop_w, crop_h)
        foreground = self._resize_vid_prep_frame_to_fit(foreground, target_w, target_h)

        bg_mode = self.vid_prep_bg_mode.currentText()
        if bg_mode == 'Image File':
            bg_path = (self.vid_prep_bg_image_path.text() or '').strip()
            if not bg_path or not os.path.exists(bg_path):
                raise ValueError('Choose a valid background image file or pick a different background mode.')
            background = self._read_vid_prep_image_bgr(bg_path)
            if background is None:
                raise ValueError('Could not read the selected background image file.')
            canvas = self._resize_vid_prep_frame_to_fill(background, target_w, target_h)
        elif bg_mode == 'Zoom Source':
            canvas = self._resize_vid_prep_frame_to_fill(source_frame, target_w, target_h)
            canvas = cv2.GaussianBlur(canvas, (0, 0), sigmaX=16, sigmaY=16)
        else:
            try:
                import numpy as np
            except ModuleNotFoundError as e:
                raise ValueError(f'Numpy is required for still export backgrounds: {e}')
            canvas = np.full((target_h, target_w, 3), self._get_vid_prep_background_bgr(), dtype=source_frame.dtype)

        fg_h, fg_w = foreground.shape[:2]
        offset_x = max(0, (target_w - fg_w) // 2)
        offset_y = max(0, (target_h - fg_h) // 2)
        canvas[offset_y:offset_y + fg_h, offset_x:offset_x + fg_w] = foreground
        return canvas

    def _write_vid_prep_image_file(self, output_path, frame, image_format):
        """Write an image file with Unicode-safe bytes output on Windows."""
        cv2 = self._get_cv2_for_vid_prep()
        if cv2 is None or frame is None:
            return False, 'OpenCV is not available for image export.'

        normalized_format = str(image_format or '').strip().lower()
        ext = '.jpg' if normalized_format in ('jpg', 'jpeg') else '.png'
        encode_params = [cv2.IMWRITE_JPEG_QUALITY, 95] if ext == '.jpg' else [cv2.IMWRITE_PNG_COMPRESSION, 3]
        ok, encoded = cv2.imencode(ext, frame, encode_params)
        if not ok:
            return False, 'OpenCV could not encode the cropped frame.'

        try:
            Path(output_path).write_bytes(encoded.tobytes())
        except Exception as e:
            return False, str(e)
        return True, ''

    def export_vid_prep_frame_image(self, image_format):
        """Export the current source marker frame as a cropped still image."""
        if not self.vid_prep_source_path or not os.path.exists(self.vid_prep_source_path):
            QMessageBox.information(self, 'Vid Prep', 'Load a source video first.')
            return

        marker_frame = self._get_vid_prep_current_marker_frame()
        frame = self._read_vid_prep_frame(marker_frame)
        if frame is None:
            QMessageBox.warning(self, 'Vid Prep', 'Could not read the selected source frame for export.')
            self.vid_prep_status.setText('Frame export failed: source frame could not be read.')
            return

        output_suffix = '.jpg' if str(image_format).lower() in ('jpg', 'jpeg') else '.png'
        output_label = 'JPG' if output_suffix == '.jpg' else 'PNG'
        try:
            rendered_frame = self._render_vid_prep_still_output_frame(frame)
            output_path = self._build_vid_prep_output_path(self.vid_prep_source_path, suffix_override=output_suffix)
        except ValueError as e:
            QMessageBox.warning(self, 'Vid Prep', str(e))
            return

        if output_path.exists():
            overwrite = QMessageBox.question(
                self,
                'Vid Prep',
                f'Output file already exists:\n{output_path}\n\nOverwrite this file?',
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if overwrite != QMessageBox.Yes:
                self.vid_prep_status.setText(f'{output_label} export canceled: existing file was not overwritten.')
                return

        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            overwrite_existing = output_path.exists()
            ok, error_text = self._write_vid_prep_image_file(output_path, rendered_frame, output_suffix)
        finally:
            QApplication.restoreOverrideCursor()

        if not ok:
            logger.error(f'Vid Prep still export failed: {error_text}')
            QMessageBox.critical(self, f'Vid Prep Export {output_label} Failed', str(error_text)[:2000])
            self.vid_prep_status.setText(f'{output_label} export failed.')
            return

        metadata_warning = ''
        try:
            self.persist_vid_prep_output_metadata(output_path, overwrite_existing, output_kind='image')
        except Exception as e:
            metadata_warning = str(e)
            logger.error(f'Failed to persist Vid Prep still metadata: {e}')

        self.vid_prep_last_output_path = str(output_path)
        self.vid_prep_saved_output_path = str(output_path)
        self.vid_prep_open_saved_btn.setEnabled(True)
        self._set_vid_prep_output_media(self.vid_prep_saved_output_path)
        self._set_vid_prep_output_preview_dirty(False)
        self.vid_prep_status.setText(f'Exported {output_label}: {output_path}')
        self._increment_vid_prep_file_index()
        self.regenerate_vid_prep_output_filename()
        if metadata_warning:
            QMessageBox.warning(
                self,
                'Vid Prep',
                f'Exported {output_label}:\n{output_path}\n\nMetadata/applications persistence failed:\n{metadata_warning}',
            )
        else:
            QMessageBox.information(self, 'Vid Prep', f'Exported {output_label}:\n{output_path}')

    def open_vid_prep_saved_file_in_explorer(self):
        """Open File Explorer and select the most recently saved Vid Prep output file."""
        saved_path = self.vid_prep_saved_output_path
        if not saved_path or not os.path.exists(saved_path):
            QMessageBox.information(self, "Vid Prep", "No saved output file is available yet.")
            self.vid_prep_open_saved_btn.setEnabled(False)
            return

        try:
            if platform.system() == "Windows":
                subprocess.Popen(["explorer", f"/select,{os.path.normpath(saved_path)}"])
            else:
                os.startfile(os.path.dirname(saved_path))
        except Exception as e:
            QMessageBox.warning(self, "Vid Prep", f"Failed to open File Explorer:\n{e}")

    def load_vid_prep_saved_output_record(self):
        """Load a previously saved Vid Prep record and repopulate controls."""
        if not self.content_db or not self.content_db.db:
            QMessageBox.information(self, "Vid Prep", "Video output database is not available.")
            return

        start_folder = self.vid_prep_output_folder_path_input.text().strip() if hasattr(self, 'vid_prep_output_folder_path_input') else ''
        if not start_folder:
            start_folder = self.vid_prep_output_folder_path or ''

        file_path, _ = QFileDialog.getOpenFileName(
            self,
            "Load Saved Vid Prep Output",
            start_folder,
            "Media Files (*.mp4 *.mov *.mkv *.m4v *.webm *.png *.jpg *.jpeg *.webp *.bmp *.gif *.tif *.tiff);;All Files (*)"
        )
        if not file_path:
            return

        try:
            bundle = self.content_db.db.get_video_output_bundle(file_path, account_name=self.current_username)
        except Exception as e:
            QMessageBox.warning(self, "Vid Prep", f"Failed to load saved output record:\n{e}")
            return

        if not bundle:
            QMessageBox.information(self, "Vid Prep", "No saved output record was found for that file.")
            return

        self._apply_vid_prep_loaded_output_bundle(bundle)

    def _apply_vid_prep_loaded_output_bundle(self, bundle):
        """Apply saved Vid Prep database state to the current UI."""
        source_path = bundle.get('SourcePath') or ''
        if source_path and os.path.exists(source_path):
            self.on_vid_prep_file_dropped(source_path)
        else:
            self.vid_prep_source_path = source_path or self.vid_prep_source_path
            if hasattr(self, 'vid_prep_file_label'):
                self.vid_prep_file_label.setText(f"File: {self.vid_prep_source_path or '(missing source)'}")

        crop_x = bundle.get('CropX')
        crop_y = bundle.get('CropY')
        crop_w = bundle.get('CropWidth')
        crop_h = bundle.get('CropHeight')
        if None not in (crop_x, crop_y, crop_w, crop_h):
            self.vid_prep_crop_rect = (int(crop_x), int(crop_y), int(crop_w), int(crop_h))
            self.vid_prep_crop_label.setText(
                f"Crop: x={int(crop_x)}, y={int(crop_y)}, w={int(crop_w)}, h={int(crop_h)}"
            )

        try:
            self.vid_prep_trim_start_frame = int(bundle.get('TrimStartFrame') or 0)
            self.vid_prep_trim_end_frame = int(bundle.get('TrimEndFrame') or 0)
            if hasattr(self, 'vid_prep_trim_slider'):
                self.vid_prep_trim_slider.setValues(self.vid_prep_trim_start_frame, self.vid_prep_trim_end_frame)
            self.update_vid_prep_trim_label()
        except Exception:
            pass

        if bundle.get('SourceFrameCount') is not None:
            try:
                self.vid_prep_frame_count = int(bundle.get('SourceFrameCount') or 0)
                self.vid_prep_fps = float(bundle.get('SourceFps') or self.vid_prep_fps or 30.0)
                self.vid_prep_duration_s = float(bundle.get('SourceDurationSeconds') or self.vid_prep_duration_s or 0.0)
            except Exception:
                pass

        if bundle.get('OutputPath'):
            self.vid_prep_saved_output_path = bundle.get('OutputPath')
            self.vid_prep_last_output_path = bundle.get('OutputPath')
            self.vid_prep_open_saved_btn.setEnabled(True)

        self.load_vid_prep_video_applications(vid_id=bundle.get('VidID'), preloaded_rows=bundle.get('applications'))
        self.load_vid_prep_video_nodes(vid_id=bundle.get('VidID'), preloaded_rows=bundle.get('nodes'))

        output_file_name = bundle.get('OutputFileName') or ''
        if output_file_name and hasattr(self, 'vid_prep_output_filename_input'):
            self.vid_prep_output_filename_input.setText(output_file_name)

        if hasattr(self, 'vid_prep_video_title_input'):
            self.vid_prep_video_title_input.setText(bundle.get('VideoFileTitle') or '')
        if hasattr(self, 'vid_prep_video_desc_input'):
            desc_val = bundle.get('VideoFileDesc') or ''
            if desc_val.strip().startswith('<'):
                self.vid_prep_video_desc_input.setHtml(desc_val)
            else:
                self.vid_prep_video_desc_input.setPlainText(desc_val)

        self.vid_prep_selected_topic_input.setText(bundle.get('SelectedTopic') or '')
        self._set_vid_prep_file_prefix_text(bundle.get('FilePrefix') or '', update_history=True)

        saved_index = bundle.get('FileIndex') or '01'
        if saved_index in [self.vid_prep_file_index_combo.itemText(i) for i in range(self.vid_prep_file_index_combo.count())]:
            self.vid_prep_file_index_combo.setCurrentText(saved_index)

        saved_modifier = bundle.get('Modifier') or '[NOTHING]'
        if saved_modifier in [self.vid_prep_modifier_combo.itemText(i) for i in range(self.vid_prep_modifier_combo.count())]:
            self.vid_prep_modifier_combo.setCurrentText(saved_modifier)

        saved_separator = bundle.get('Separator') or '.'
        if saved_separator in [self.vid_prep_separator_combo.itemText(i) for i in range(self.vid_prep_separator_combo.count())]:
            self.vid_prep_separator_combo.setCurrentText(saved_separator)

        self.vid_prep_prepend_topic_checkbox.setChecked(bool(bundle.get('PrependTopic')))

        saved_folder_mode = bundle.get('OutputFolderMode') or 'same_as_input'
        mode_text_map = {
            'same_as_input': 'Same as input',
            'user_specified': 'User specified',
            'default_video_output': 'Default Video Output',
            'dvo_topic': 'DVO/Topic',
        }
        self.vid_prep_output_folder_mode_combo.setCurrentText(mode_text_map.get(saved_folder_mode, 'Same as input'))
        self.vid_prep_output_folder_path_input.setText(bundle.get('OutputFolderPath') or '')

        if bundle.get('CodecPreset') in [self.vid_prep_codec_preset.itemText(i) for i in range(self.vid_prep_codec_preset.count())]:
            self.vid_prep_codec_preset.setCurrentText(bundle.get('CodecPreset'))
        try:
            self.vid_prep_crf.setValue(int(bundle.get('CRF') or self.vid_prep_crf.value()))
        except Exception:
            pass

        if bundle.get('ResolutionPreset') in [self.vid_prep_output_resolution_combo.itemText(i) for i in range(self.vid_prep_output_resolution_combo.count())]:
            self.vid_prep_output_resolution_combo.setCurrentText(bundle.get('ResolutionPreset'))
        try:
            if bundle.get('OutputWidth') is not None:
                self.vid_prep_output_width.setValue(int(bundle.get('OutputWidth')))
            if bundle.get('OutputHeight') is not None:
                self.vid_prep_output_height.setValue(int(bundle.get('OutputHeight')))
        except Exception:
            pass

        if bundle.get('BackgroundMode') in [self.vid_prep_bg_mode.itemText(i) for i in range(self.vid_prep_bg_mode.count())]:
            self.vid_prep_bg_mode.setCurrentText(bundle.get('BackgroundMode'))
        if bundle.get('BackgroundColor'):
            self.vid_prep_bg_color = QColor(str(bundle.get('BackgroundColor')))
        self.vid_prep_bg_image_path.setText(bundle.get('BackgroundImagePath') or '')

        audio_mode = bundle.get('AudioMode') or 'remove'
        if audio_mode == 'replace':
            self.vid_prep_audio_replace_radio.setChecked(True)
        elif audio_mode == 'maintain':
            self.vid_prep_audio_maintain_radio.setChecked(True)
        elif audio_mode == 'mix':
            self.vid_prep_audio_mix_radio.setChecked(True)
        else:
            self.vid_prep_audio_remove_radio.setChecked(True)

        self.vid_prep_selected_audio_path = self._normalize_vid_prep_audio_path(bundle.get('AudioFilePath') or '')

        self.vid_prep_audio_tracks = []
        for track in bundle.get('audio_tracks') or []:
            self.vid_prep_audio_tracks.append({
                'track_id': int(track.get('AudioTrackID') or track.get('track_id') or self.vid_prep_next_audio_track_id),
                'track_path': track.get('TrackPath') or track.get('track_path') or '',
                'track_name': track.get('TrackName') or track.get('track_name') or '',
                'volume_percent': float(track.get('VolumePercent') if track.get('VolumePercent') is not None else track.get('volume_percent') or 100.0),
                'clip_start_seconds': float(track.get('ClipStartSeconds') if track.get('ClipStartSeconds') is not None else track.get('clip_start_seconds') or 0.0),
                'clip_end_seconds': float(track.get('ClipEndSeconds') if track.get('ClipEndSeconds') is not None else track.get('clip_end_seconds') or 0.0),
                'enter_frame': int(track.get('EnterFrame') if track.get('EnterFrame') is not None else track.get('enter_frame') or 0),
                'exit_frame': int(track.get('ExitFrame') if track.get('ExitFrame') is not None else track.get('exit_frame') or 0),
                'fade_in_seconds': float(track.get('FadeInSeconds') if track.get('FadeInSeconds') is not None else track.get('fade_in_seconds') or 0.0),
                'fade_out_seconds': float(track.get('FadeOutSeconds') if track.get('FadeOutSeconds') is not None else track.get('fade_out_seconds') or 0.0),
                'muted': bool(track.get('Muted') if track.get('Muted') is not None else track.get('muted') or False),
            })

        if self.vid_prep_audio_tracks:
            max_track_id = max(int(track.get('track_id', 0)) for track in self.vid_prep_audio_tracks)
            self.vid_prep_next_audio_track_id = max_track_id + 1
        else:
            self.vid_prep_next_audio_track_id = 1

        self._refresh_vid_prep_audio_track_list(self.vid_prep_audio_tracks[0]['track_id'] if self.vid_prep_audio_tracks else None)
        self._set_vid_prep_output_media(self.vid_prep_saved_output_path)
        if self.vid_prep_saved_output_path and os.path.exists(self.vid_prep_saved_output_path):
            self.vid_prep_output_preview_dirty = False
        self.update_vid_prep_output_filename_preview()
        self.vid_prep_status.setText(f"Loaded saved Vid Prep record from {bundle.get('OutputPath')}")

    def _get_vid_prep_output_dimensions(self, crop_w, crop_h):
        """Resolve the target output dimensions from the current resolution preset."""
        preset = self.vid_prep_output_resolution_combo.currentText()
        preset_map = {
            "Match Crop": (crop_w, crop_h),
            "Original": (self.vid_prep_source_w or crop_w, self.vid_prep_source_h or crop_h),
            "720x1280": (720, 1280),
            "1080x1920": (1080, 1920),
            "1080x1080": (1080, 1080),
            "Custom": (int(self.vid_prep_output_width.value()), int(self.vid_prep_output_height.value())),
        }
        target_w, target_h = preset_map.get(preset, (crop_w, crop_h))
        target_w = max(2, int(target_w))
        target_h = max(2, int(target_h))
        if target_w % 2 != 0:
            target_w += 1
        if target_h % 2 != 0:
            target_h += 1
        return target_w, target_h

    def _build_vid_prep_ffmpeg_command(self, output_path):
        """Build ffmpeg command for Vid Prep export/preview using current UI settings."""
        if not self.vid_prep_source_path or not os.path.exists(self.vid_prep_source_path):
            raise ValueError("Drop a valid source video first.")

        crop = self._get_vid_prep_active_crop_rect()

        trim_start_frame = max(0, int(self.vid_prep_trim_start_frame))
        trim_end_frame = max(trim_start_frame, int(self.vid_prep_trim_end_frame))
        if self.vid_prep_frame_count > 0:
            trim_end_frame = min(trim_end_frame, self.vid_prep_frame_count - 1)

        trim_start_s = self._vid_prep_frame_to_seconds(trim_start_frame)
        trim_end_s = self._vid_prep_frame_to_seconds(trim_end_frame + 1)
        trim_duration = max(0.0, trim_end_s - trim_start_s)
        if trim_duration <= 0:
            raise ValueError("Trim markers must define a positive video range.")

        ffmpeg_bin = shutil.which("ffmpeg")
        if not ffmpeg_bin:
            raise ValueError("ffmpeg is not available on PATH. Install ffmpeg to use Vid Prep export.")

        x, y, w, h = crop
        preset = self.vid_prep_codec_preset.currentText().strip()
        crf = int(self.vid_prep_crf.value())
        target_w, target_h = self._get_vid_prep_output_dimensions(w, h)
        bg_mode = self.vid_prep_bg_mode.currentText()
        bg_color = "#000000"
        if bg_mode == "White":
            bg_color = "#ffffff"
        elif bg_mode == "Custom Color":
            bg_color = self.vid_prep_bg_color

        base_video_filter = f"crop={w}:{h}:{x}:{y},scale={target_w}:{target_h}:force_original_aspect_ratio=decrease"

        audio_mode = self._current_vid_prep_audio_mode()
        include_source_audio = audio_mode in ('maintain', 'mix')
        include_music_audio = audio_mode in ('replace', 'mix')
        track_payloads = self._build_vid_prep_audio_track_payload()
        active_track_payloads = [track for track in track_payloads if not bool(track.get('muted'))] if include_music_audio else []

        if include_music_audio and not active_track_payloads:
            raise ValueError("Add at least one audio track for Music/Mix audio mode.")

        cmd = [ffmpeg_bin, "-y", "-ss", f"{trim_start_s:.3f}", "-to", f"{trim_end_s:.3f}", "-i", self.vid_prep_source_path]

        next_input_index = 1
        bg_input_index = None
        track_input_indices = []

        if bg_mode == "Image File":
            bg_image_path = self.vid_prep_bg_image_path.text().strip()
            if not bg_image_path or not os.path.exists(bg_image_path):
                raise ValueError("Choose a valid background image file or pick a different background mode.")
            cmd.extend(["-loop", "1", "-i", bg_image_path])
            bg_input_index = next_input_index
            next_input_index += 1

        for track in active_track_payloads:
            track_path = str(track.get('track_path') or '').strip()
            if not track_path or not os.path.exists(track_path):
                raise ValueError(f"Audio track file is missing: {track_path or '(empty)'}")
            cmd.extend(["-i", track_path])
            track_input_indices.append(next_input_index)
            next_input_index += 1

        def _track_filter_chain(track_data, input_index, output_label):
            clip_start = max(0.0, float(track_data.get('clip_start_seconds') or 0.0))
            clip_end = float(track_data.get('clip_end_seconds') or 0.0)
            enter_frame = int(track_data.get('enter_frame') or 0)
            exit_frame = int(track_data.get('exit_frame') or 0)
            volume_percent = float(track_data.get('volume_percent') or 100.0)
            fade_in_seconds = max(0.0, float(track_data.get('fade_in_seconds') or 0.0))
            fade_out_seconds = max(0.0, float(track_data.get('fade_out_seconds') or 0.0))
            fps = max(1.0, float(self.vid_prep_fps or 30.0))

            timeline_duration = None
            if exit_frame > enter_frame:
                timeline_duration = max(0.0, (exit_frame - enter_frame) / fps)

            # Clamp to remaining export window so fades/timing line up with final render length.
            timeline_start_s = max(0.0, enter_frame / fps)
            remaining_timeline = max(0.0, trim_duration - timeline_start_s)
            if remaining_timeline > 0:
                timeline_duration = remaining_timeline if timeline_duration is None else min(timeline_duration, remaining_timeline)

            clip_duration = None
            if clip_end > clip_start:
                clip_duration = clip_end - clip_start

            duration_candidates = [value for value in (clip_duration, timeline_duration) if value is not None and value > 0]
            track_duration = min(duration_candidates) if duration_candidates else None

            start_offset_frames = max(0, -enter_frame)
            source_start = clip_start + (start_offset_frames / fps)
            source_end = source_start + track_duration if track_duration is not None else None

            parts = [f"[{input_index}:a]aformat=sample_fmts=fltp:sample_rates=48000:channel_layouts=stereo"]
            if source_end is not None and source_end > source_start:
                parts.append(f"atrim=start={source_start:.3f}:end={source_end:.3f}")
            elif source_start > 0:
                parts.append(f"atrim=start={source_start:.3f}")
            parts.append("asetpts=PTS-STARTPTS")
            if abs(volume_percent - 100.0) > 0.01:
                parts.append(f"volume={volume_percent / 100.0:.3f}")

            effective_fade_in = fade_in_seconds
            effective_fade_out = fade_out_seconds
            if track_duration is not None and track_duration > 0:
                effective_fade_in = min(effective_fade_in, track_duration)
                effective_fade_out = min(effective_fade_out, track_duration)

            if effective_fade_in > 0:
                parts.append(f"afade=t=in:st=0:d={effective_fade_in:.3f}")
            if effective_fade_out > 0 and track_duration is not None and track_duration > 0:
                fade_out_start = max(0.0, track_duration - effective_fade_out)
                parts.append(f"afade=t=out:st={fade_out_start:.3f}:d={effective_fade_out:.3f}")
            if enter_frame > 0:
                delay_ms = int(round((enter_frame / fps) * 1000.0))
                parts.append(f"adelay={delay_ms}|{delay_ms}")
            parts.append("aformat=sample_fmts=fltp:sample_rates=48000:channel_layouts=stereo")
            return f"{','.join(parts)}[{output_label}]"

        if bg_mode == "Image File":
            video_filter = (
                f"[0:v]{base_video_filter}[fg];"
                f"[{bg_input_index}:v]scale={target_w}:{target_h}:force_original_aspect_ratio=increase,crop={target_w}:{target_h}[bg];"
                f"[bg][fg]overlay=(W-w)/2:(H-h)/2,format=yuv420p[v]"
            )
        elif bg_mode == "Zoom Source":
            video_filter = (
                f"[0:v]split=2[bgsrc][fgsrc];"
                f"[bgsrc]scale={target_w}:{target_h}:force_original_aspect_ratio=increase,crop={target_w}:{target_h},boxblur=10:1[bg];"
                f"[fgsrc]{base_video_filter}[fg];"
                f"[bg][fg]overlay=(W-w)/2:(H-h)/2,format=yuv420p[v]"
            )
        else:
            video_filter = (
                f"[0:v]{base_video_filter},pad={target_w}:{target_h}:(ow-iw)/2:(oh-ih)/2:color={bg_color},format=yuv420p[v]"
            )

        audio_filters = []
        audio_labels = []

        if include_source_audio:
            audio_filters.append("[0:a]aformat=sample_fmts=fltp:sample_rates=48000:channel_layouts=stereo[srca]")
            audio_labels.append("[srca]")

        for idx, track in zip(track_input_indices, active_track_payloads):
            label = f"trk{len(audio_labels)}"
            audio_filters.append(_track_filter_chain(track, idx, label))
            audio_labels.append(f"[{label}]")

        if audio_labels:
            audio_filters.append(f"{''.join(audio_labels)}amix=inputs={len(audio_labels)}:duration=longest:dropout_transition=2[aout]")
            cmd.extend(["-filter_complex", ";".join([video_filter] + audio_filters), "-map", "[v]", "-map", "[aout]", "-c:v", "libx264", "-preset", preset, "-crf", str(crf), "-c:a", "aac", "-t", f"{trim_duration:.3f}"])
        else:
            cmd.extend(["-filter_complex", video_filter, "-map", "[v]", "-an", "-c:v", "libx264", "-preset", preset, "-crf", str(crf), "-t", f"{trim_duration:.3f}"])

        cmd.append(str(output_path))
        return cmd

    def preview_vid_prep_output(self):
        """Render a temporary output using current settings and play it on the output preview."""
        suffix = Path(self.vid_prep_source_path).suffix if self.vid_prep_source_path else ".mp4"
        if not suffix:
            suffix = ".mp4"
        preview_path = Path(tempfile.gettempdir()) / f"vidprep_preview_{int(time.time() * 1000)}{suffix}"

        try:
            cmd = self._build_vid_prep_ffmpeg_command(preview_path)
        except ValueError as e:
            QMessageBox.warning(self, "Vid Prep", str(e))
            return

        self.vid_prep_status.setText("Rendering preview with output settings...")
        self._vid_prep_set_render_progress(True, "Rendering preview...")
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            result = subprocess.run(cmd, capture_output=True, text=True)
        finally:
            QApplication.restoreOverrideCursor()
            self._vid_prep_set_render_progress(False)

        if result.returncode != 0:
            err = (result.stderr or "Unknown ffmpeg error").strip()
            logger.error(f"Vid Prep preview render failed: {err}")
            QMessageBox.critical(self, "Vid Prep Preview Failed", err[:2000])
            self.vid_prep_status.setText("Preview render failed.")
            return

        self.vid_prep_last_output_path = str(preview_path)
        self._set_vid_prep_output_media(self.vid_prep_last_output_path)
        self.vid_prep_output_player.play()
        self.vid_prep_status.setText("Preview ready (temporary render).")
        self.vid_prep_open_saved_btn.setEnabled(False)
        self._set_vid_prep_output_preview_dirty(False)

    def save_vid_prep_output(self):
        """Process and save cropped video with selected audio mode."""
        topic_text = self._get_vid_prep_topic_filename_prefix_text().strip()
        if topic_text and self.vid_prep_output_folder_mode != 'dvo_topic':
            response = QMessageBox.warning(
                self,
                "Vid Prep Output Folder Mode",
                "A topic is selected, but Output Folder Mode is not set to DVO/Topic.\n\n"
                "Your output folder will NOT include the topic tree path.\n\n"
                "Continue saving anyway?",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if response != QMessageBox.Yes:
                self.vid_prep_status.setText("Save canceled: switch Output Folder Mode to DVO/Topic to include topic tree folders.")
                return

        output_path = self._build_vid_prep_output_path(self.vid_prep_source_path)
        overwrite_existing = output_path.exists()

        if overwrite_existing:
            overwrite = QMessageBox.question(
                self,
                "Vid Prep",
                f"Output file already exists:\n{output_path}\n\nOverwrite this file?",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if overwrite != QMessageBox.Yes:
                self.vid_prep_status.setText("Save canceled: existing file was not overwritten.")
                return

        try:
            cmd = self._build_vid_prep_ffmpeg_command(output_path)
        except ValueError as e:
            QMessageBox.warning(self, "Vid Prep", str(e))
            return

        self.vid_prep_status.setText("Processing with ffmpeg...")
        self._vid_prep_set_render_progress(True, "Saving video...")
        QApplication.setOverrideCursor(Qt.WaitCursor)
        try:
            if overwrite_existing and self.vid_prep_last_output_path and os.path.normcase(str(self.vid_prep_last_output_path)) == os.path.normcase(str(output_path)):
                self.vid_prep_output_player.stop()
                self.vid_prep_output_player.setMedia(QMediaContent())
                if hasattr(self, 'vid_prep_output_display_stack') and hasattr(self, 'vid_prep_output_placeholder'):
                    self.vid_prep_output_display_stack.setCurrentWidget(self.vid_prep_output_placeholder)
            result = subprocess.run(cmd, capture_output=True, text=True)
        finally:
            QApplication.restoreOverrideCursor()
            self._vid_prep_set_render_progress(False)

        if result.returncode != 0:
            err = (result.stderr or "Unknown ffmpeg error").strip()
            logger.error(f"Vid Prep export failed: {err}")
            QMessageBox.critical(self, "Vid Prep Export Failed", err[:2000])
            self.vid_prep_status.setText("Export failed.")
            return

        metadata_warning = ''
        try:
            vid_id = self.persist_vid_prep_output_metadata(output_path, overwrite_existing, ffmpeg_command=cmd)
            self.persist_vid_prep_video_applications(vid_id)
            self.persist_vid_prep_video_nodes(vid_id)
            logger.info(f"Persisted Vid Prep metadata to VIDEO.VideoOutput VidID={vid_id}")
        except Exception as e:
            metadata_warning = str(e)
            logger.error(f"Failed to persist Vid Prep metadata: {e}")

        self.vid_prep_last_output_path = str(output_path)
        self.vid_prep_saved_output_path = str(output_path)
        self.vid_prep_open_saved_btn.setEnabled(True)
        self.update_vid_prep_output_filename_preview()
        self._set_vid_prep_output_media(self.vid_prep_last_output_path)
        self.vid_prep_output_player.play()
        self.vid_prep_status.setText(f"Saved: {output_path}")
        self._set_vid_prep_output_preview_dirty(False)
        self._increment_vid_prep_file_index()
        self.regenerate_vid_prep_output_filename()
        if metadata_warning:
            self.vid_prep_status.setText(f"Saved: {output_path} (metadata save failed)")
            QMessageBox.warning(
                self,
                "Vid Prep",
                f"Saved output:\n{output_path}\n\nMetadata/applications persistence failed:\n{metadata_warning}",
            )
        else:
            QMessageBox.information(self, "Vid Prep", f"Saved output:\n{output_path}")
    
    def create_shot_breakdown_tab(self):
        """Create the Shot Breakdown tab for video analysis"""
        tab = QWidget()
        layout = QVBoxLayout(tab)
        layout.setSpacing(15)
        layout.setContentsMargins(20, 20, 20, 20)
        
        # Initialize Shot Breakdown Manager
        self.shot_breakdown_manager = ShotBreakdownManager()
        self.shot_breakdown_current_video = None
        self.shot_breakdown_results = None
        self.shot_breakdown_current_shot = None
        
        # Header
        header = QLabel("🎬 Shot Breakdown - Cinematic Video Analysis")
        header.setStyleSheet("font-size: 18pt; font-weight: bold; color: #3b82f6;")
        layout.addWidget(header)
        
        description = QLabel(
            "Automated shot detection, frame extraction, scene labeling, dependency mapping, "
            "and AI prompt generation for cinematic video tools (Runway, Pika, Luma, Kling, etc.)"
        )
        description.setWordWrap(True)
